/** A paste-ready brief for a task, used by the Agent center and the UI. */
function taskBrief(task, source) {
  const lines = []
  lines.push('## 任务：' + task.title)
  lines.push('')
  lines.push('- 状态：' + task.status + ' · 优先级：' + task.priority)
  if (task.dueAt) lines.push('- 截止：' + task.dueAt)
  if (task.assignee) lines.push('- 负责人：' + task.assignee)
  lines.push('')
  if (task.description) {
    lines.push('### 背景')
    lines.push(task.description)
    lines.push('')
  }
  if (source) {
    lines.push('### 来源证据')
    lines.push('- ' + source.provider + ' · ' + source.title)
    if (source.url) lines.push('- ' + source.url)
    if (source.excerpt) lines.push('- 原文摘录：' + source.excerpt)
    lines.push('')
  }
  lines.push('### 期望产出')
  lines.push('1. 结论与依据（引用来源）')
  lines.push('2. 可执行的下一步')
  lines.push('3. 需要人工确认的风险点')
  return lines.join('\n')
}

// ===== 20-store.js =====
/* ============================================================================
 * dev-workbench host — persistence
 *
 * One in-memory authoritative document, flushed atomically on every mutation.
 * Reads are lazy (first use wins), so a profile that never opens the workbench
 * never touches the disk.
 * ========================================================================== */

let workbenchCachedState = null
let workbenchLoadNote = null

function loadWorkbenchState() {
  if (workbenchCachedState) return workbenchCachedState
  const path = workbenchStatePath()
  const raw = readJsonFile(path)
  const result = normalizeState(raw)
  if (result.corrupt) {
    // 损坏保护（TODO 11）：先把原文件原样改名留存，**绝不**用空状态直接覆盖它。
    // 内存里从空状态起步；只有在用户后续真正写入时才落新文件，原损坏文件仍可人工恢复。
    let preserved = null
    try {
      preserved = path + '.corrupt-' + hostNowIso().replace(/[:.]/g, '-') + '.json'
      renameSync(path, preserved)
    } catch (e) {
      preserved = null
    }
    workbenchLoadNote =
      'state.json 无法解析，已从空状态启动' + (preserved ? '；原文件已保留为 ' + preserved : '') + '：' + result.corrupt
    workbenchCachedState = result.state
    return workbenchCachedState
  }
  if (!raw) {
    workbenchLoadNote = '首次运行，已创建空状态：' + path
  } else if (result.migrated) {
    workbenchLoadNote = '已将 state.json 迁移到 schema v' + HOST_STATE_VERSION
  }
  workbenchCachedState = result.state
  if (!raw || result.migrated) saveWorkbenchState(workbenchCachedState)
  return workbenchCachedState
}

/* ---------------------------------------------------------------------------
 * 备份与恢复（TODO 11）：每天首次写入前留一份快照，保留最近 5 份；
 * 支持手动备份/列出/恢复。恢复后清空内存缓存，下一次读取重新从文件加载。
 * ------------------------------------------------------------------------- */
const BACKUP_KEEP = 5

function backupDir() {
  return join(workbenchDir(), 'backups')
}

function listBackups() {
  const dir = backupDir()
  try {
    return readdirSync(dir)
      .filter(function (name) {
        return name.endsWith('.json')
      })
      .sort()
      .reverse()
      .map(function (name) {
        return { id: name, path: join(dir, name), bytes: fileSizeOf(join(dir, name)) }
      })
  } catch (e) {
    return []
  }
}

function createBackup(reason) {
  const source = workbenchStatePath()
  if (!existsSync(source)) return null
  const stamp = hostNowIso().replace(/[:.]/g, '-')
  const target = join(backupDir(), 'state-' + stamp + (reason ? '-' + reason : '') + '.json')
  try {
    mkdirSync(backupDir(), { recursive: true })
    writeFileSync(target, readFileSync(source), 'utf8')
  } catch (e) {
    return null
  }
  // 只保留最近 N 份
  const all = listBackups()
  all.slice(BACKUP_KEEP).forEach(function (item) {
    try {
      renameSync(item.path, item.path + '.trash')
    } catch (e) {
      /* 尽力而为 */
    }
  })
  listBackups().forEach(function (item) {
    if (item.id.endsWith('.trash')) return
  })
  return target
}

/** 恢复某份备份：先备份当前文件，再用备份覆盖，最后清空缓存。 */
function restoreBackup(id) {
  const safeId = asString(id, 120)
  const candidate = listBackups().find(function (item) {
    return item.id === safeId
  })
  if (!candidate) throw new Error('找不到该备份：' + safeId)
  createBackup('pre-restore')
  writeFileSync(workbenchStatePath(), readFileSync(candidate.path), 'utf8')
  workbenchCachedState = null
  workbenchLoadNote = '已从备份恢复：' + safeId
  return loadWorkbenchState()
}

let lastAutoBackupDay = null

function saveWorkbenchState(state, options) {
  const opts = options || {}
  if (!opts.skipBackup && existsSync(workbenchStatePath())) {
    const today = hostNowIso().slice(0, 10)
    if (lastAutoBackupDay !== today) {
      lastAutoBackupDay = today
      createBackup('auto-' + today)
    }
  }
  state.version = HOST_STATE_VERSION
  state.updatedAt = hostNowIso()
  // 业务修订号（与 schema version 区分）：单调递增，Client 用它判断快照新旧，
  // 避免旧快照覆盖新数据（AI-COMMAND-EXECUTION §4）。schema 版本不能当并发号用。
  state.revision = (Number(state.revision) || 0) + 1
  writeJsonAtomic(workbenchStatePath(), state)
  workbenchCachedState = state
  return state
}

async function mutateWorkbenchState(mutator) {
  const state = loadWorkbenchState()
  const replacement = await mutator(state)
  const next = replacement && typeof replacement === 'object' && replacement.version ? replacement : state
  return saveWorkbenchState(next)
}

/** 查幂等键对应的历史操作（工具重试时直接返回原结果）。 */
function findOperation(state, key) {
  if (!key) return null
  return ensureArray(state.operations).find(function (operation) {
    return operation.key === key
  }) || null
}

/** 记一条操作账本（cap 200，按时间淘汰）。 */
function recordOperation(state, entry) {
  state.operations = ensureArray(state.operations)
    .concat([
      {
        key: asString(entry.key, 160),
        tool: asString(entry.tool, 60),
        at: hostNowIso(),
        entityIds: ensureArray(entry.entityIds).slice(0, 10),
        status: asString(entry.status, 20) || 'succeeded',
      },
    ])
    .slice(-OPERATION_LIMIT)
  return state
}

function workbenchAudit(event, summary) {
  mutateWorkbenchState(function (state) {
    auditEntry(state, event, summary)
    return state
  })
}

function workbenchCounts(state) {
  return {
    tasks: ensureArray(state.tasks).length,
    runs: ensureArray(state.runs).length,
    knowledge: ensureArray(state.knowledge).length,
    radar: ensureArray(state.radar).length,
    sources: ensureArray(state.sources).length,
    knowledgeSnippets: ensureArray(state.knowledge).filter(function (item) {
      return item.kind === 'snippet'
    }).length,
  }
}

// ===== 25-connectors.js =====
/* ============================================================================
 * dev-workbench host — connector probe
 *
 * A Connector row is a claim about what this Host can actually do right now.
 * Everything reported here is measured: a binary resolves or it does not, a
 * service exists on the context or it does not. Enterprise systems the design
 * report wants (云之家 / 企业搜索) stay `unconfigured` with an explanation —
 * the report's §6.3 capability checklist has to be answered against the real
 * CLI before a row may claim otherwise.
 * ========================================================================== */

const CONNECTOR_TTL_MS = 60 * 1000

function probeExecutable(ctx, command) {
  const subprocess = ctx.get ? ctx.get('subprocess') : ctx.subprocess
  if (!subprocess || typeof subprocess.resolveExecutable !== 'function') {
    return Promise.resolve(null)
  }
  let signal
  try {
    signal = typeof AbortSignal !== 'undefined' && AbortSignal.timeout ? AbortSignal.timeout(2500) : undefined
  } catch (e) {
    signal = undefined
  }
  return Promise.resolve()
    .then(function () {
      return subprocess.resolveExecutable(command, undefined, signal)
    })
    .then(function (resolved) {
      return typeof resolved === 'string' && resolved.length > 0 ? resolved : null
    })
    .catch(function () {
      return null
    })
}

async function detectConnectors(ctx) {
  const at = hostNowIso()
  const rows = []

  rows.push({
    id: 'local-storage',
    type: 'storage',
    label: '本地持久化',
    capabilities: ['原子写入', '快照', 'schema v' + HOST_STATE_VERSION],
    authState: 'ok',
    updatedAt: at,
    note: workbenchStatePath(),
  })

  rows.push({
    id: 'host-runtime',
    type: 'runtime',
    label: 'Host 运行时',
    capabilities: [HOST_META.platform, HOST_META.arch, 'node ' + HOST_META.nodeVersion],
    authState: 'ok',
    updatedAt: at,
    note: '状态与 Remote 端点由 Host 持有，前端只读快照。',
  })

  const gitPath = await probeExecutable(ctx, 'git')
  rows.push({
    id: 'git',
    type: 'vcs',
    label: 'Git',
    capabilities: gitPath ? ['版本库读取（只读）'] : [],
    authState: gitPath ? 'ok' : 'unconfigured',
    updatedAt: at,
    note: gitPath ? gitPath : '未在 PATH 中找到 git；接入前不显示仓库状态。',
  })

  const dockerPath = await probeExecutable(ctx, 'docker')
  rows.push({
    id: 'docker',
    type: 'container',
    label: 'Docker',
    capabilities: dockerPath ? ['容器状态（只读）'] : [],
    authState: dockerPath ? 'ok' : 'unconfigured',
    updatedAt: at,
    note: dockerPath ? dockerPath : '未在 PATH 中找到 docker；只读诊断能力待接入。',
  })

  const web = ctx.get ? ctx.get('web') : ctx.web
  rows.push({
    id: 'web',
    type: 'network',
    label: '外网检索',
    capabilities: web ? ['search', 'fetch'] : [],
    authState: web ? 'ok' : 'unconfigured',
    updatedAt: at,
    note: web ? '经 Host 的 web 服务调用，结果需标注来源与时间。' : '当前 profile 未组合 web 服务。',
  })

  // 云之家：真实能力发现（§6.3）。whoami 通了才算「已连接」，
  // 能力列表是这里实际调过的命令；token 快过期时给「待授权」。
  const yzProbe = await probeYunzhijia(ctx)
  const yzCapabilities = []
  if (yzProbe.state === 'ok') {
    yzCapabilities.push('IM @我 检索', '跨群消息搜索', '知识库标题搜索')
    if (yzProbe.expiresAt) {
      const expires = new Date(yzProbe.expiresAt).getTime()
      if (Number.isFinite(expires) && expires - Date.now() < 60 * 60 * 1000) {
        yzCapabilities.push('token 1 小时内到期')
      }
    }
  }
  rows.push({
    id: 'yunzhijia',
    type: 'enterprise-im',
    label: '云之家',
    capabilities: yzCapabilities,
    authState:
      yzProbe.state === 'ok' ? 'ok' : yzProbe.state === 'unauthorized' ? 'unauthorized' : 'unconfigured',
    updatedAt: at,
    note:
      yzProbe.state === 'ok'
        ? '以 ' + yzProbe.name + ' 身份只读调用 yzj-cli（whoami 已验证）。能力=消息搜索 / 文档搜索 / @我 检索；发送/审批/删除等写操作不在插件内，留在会话里走逐次审批。' +
          (yzProbe.expiresAt ? ' token 至 ' + yzProbe.expiresAt.slice(0, 16).replace('T', ' ') + '。' : '')
        : yzProbe.state === 'unauthorized'
          ? 'yzj-cli 需要重新认证：运行 yzj-cli auth login 后再刷新。'
          : yzProbe.note || '未找到 yzj-cli，保持未配置。',
  })

  return rows
}

async function refreshConnectors(ctx, state) {
  const existing = ensureArray(state.connectors)
  const newest = existing.reduce(function (latest, item) {
    const stamp = item && item.updatedAt ? new Date(item.updatedAt).getTime() : 0
    return Number.isFinite(stamp) && stamp > latest ? stamp : latest
  }, 0)
  if (existing.length > 0 && Date.now() - newest < CONNECTOR_TTL_MS) {
    return state
  }
  const rows = await detectConnectors(ctx)
  return mutateWorkbenchState(function (current) {
    current.connectors = rows
    return current
  })
}

// ===== 28-exec.js =====
/* ============================================================================
 * dev-workbench host — bounded read-only command runner
 *
 * Design report §7.2 requires parameterised calls against an explicit
 * allowlist, and forbids splicing natural language into a shell. This module is
 * the only place the plugin ever starts a process:
 *
 *   - argv arrays only, never a shell string;
 *   - a fixed whitelist of read-only subcommands (git status/log/rev-parse,
 *     docker ps, lsof -i) checked BEFORE spawn;
 *   - an explicit cwd, a wall-clock timeout, and a byte cap per stream;
 *   - no stdin, so nothing can be driven interactively.
 *
 * Every failure is reported as data ({status:'unavailable'|'error'}), never as
 * a thrown error, because a missing git must degrade the panel, not break it.
 * ========================================================================== */

const EXEC_TIMEOUT_MS = 5000
const EXEC_MAX_BYTES = 128 * 1024

/** 子命令必须按完整前缀收紧的工具（gh 的写操作如 pr merge 绝不可放行）。 */
const READ_ONLY_ARGV_PREFIXES = [
  'gh pr list',
  'gh pr view',
  'gh pr status',
  'gh run list',
  'gh run view',
  'gh repo view',
  'gh search repos',
  'ps aux',
  'ps -axo',
]

/** Read-only subcommands this plugin is allowed to run. */
const READ_ONLY_ALLOWLIST = {
  git: new Set(['status', 'log', 'rev-parse', 'branch']),
  docker: new Set(['ps', 'version', 'info']),
  lsof: new Set(['-i']),
}

function execAllowed(argv) {
  if (!Array.isArray(argv) || argv.length < 2) return false
  const binary = String(argv[0]).split('/').pop()
  // 候选串包含二进制 basename，白名单前缀才能写成 'gh pr list' / 'ps aux'
  const candidate = [binary]
    .concat(
      argv.slice(1).map(function (token) {
        return String(token)
      }),
    )
    .join(' ')
  // 1) 多段前缀精确匹配（gh / ps）
  const prefixHit = READ_ONLY_ARGV_PREFIXES.some(function (prefix) {
    return candidate === prefix || candidate.startsWith(prefix + ' ')
  })
  if (prefixHit) return true
  // 2) 单命令白名单（git / docker / lsof）
  const allowed = READ_ONLY_ALLOWLIST[binary]
  if (!allowed) return false
  return argv.slice(1).some(function (token) {
    return allowed.has(String(token))
  })
}

function execUnavailable(reason) {
  return { status: 'unavailable', exitCode: null, stdout: '', stderr: '', reason: reason }
}

async function runReadOnlyCommand(ctx, argv, cwd) {
  if (!execAllowed(argv)) {
    return execUnavailable('命令不在只读 allowlist 内：' + argv.join(' '))
  }
  const subprocess = ctx && ctx.get ? ctx.get('subprocess') : null
  if (!subprocess || typeof subprocess.spawn !== 'function') {
    return execUnavailable('当前 profile 未组合 subprocess 服务')
  }
  let signal
  try {
    signal = AbortSignal.timeout(EXEC_TIMEOUT_MS)
  } catch (e) {
    signal = undefined
  }
  let handle
  try {
    handle = subprocess.spawn({
      argv: argv.map(String),
      cwd: cwd,
      stdio: {
        stdin: 'ignore',
        stdout: { maxBytes: EXEC_MAX_BYTES },
        stderr: { maxBytes: 16 * 1024 },
      },
      graceMs: 1200,
      signal: signal,
    })
  } catch (e) {
    return execUnavailable('无法启动进程：' + String((e && e.message) || e))
  }
  try {
    const outcome = await handle.done
    const read = function (reader) {
      if (!reader || typeof reader.readFrom !== 'function') return ''
      try {
        return String(reader.readFrom(0).text || '')
      } catch (e) {
        return ''
      }
    }
    const stdout = read(handle.collected && handle.collected.stdout)
    const stderr = read(handle.collected && handle.collected.stderr)
    return {
      status: outcome && outcome.exitCode === 0 ? 'ok' : 'error',
      exitCode: outcome ? outcome.exitCode : null,
      stdout: stdout,
      stderr: stderr.slice(0, 2000),
      reason: outcome && outcome.exitCode === 0 ? null : '退出码 ' + (outcome ? outcome.exitCode : 'unknown'),
    }
  } catch (e) {
    return {
      status: 'error',
      exitCode: null,
      stdout: '',
      stderr: '',
      reason: String((e && e.message) || e),
    }
  }
}

// ===== 30-service.js =====
/* ============================================================================
 * dev-workbench host — workbench service
 *
 * The single authority for workbench state. Every mutation returns the whole
 * new snapshot, so the Client never has to merge: it swaps. That is the
 * "Host 维护可重建快照" contract from design report §5.2, kept deliberately
 * boring so a reconnecting Client cannot drift.
 * ========================================================================== */

let workbenchCtx = null

function workbenchContext() {
  return workbenchCtx
}

async function workbenchServiceState() {
  const state = loadWorkbenchState()
  const ctx = workbenchContext()
  if (!ctx) return state
  try {
    return await refreshConnectors(ctx, state)
  } catch (e) {
    return state
  }
}

function requireTask(state, id) {
  const task = ensureArray(state.tasks).find(function (item) {
    return item.id === id
  })
  if (!task) throw new Error('找不到该待办：' + String(id))
  return task
}

/* ---------------------------------------------------------------------------
 * 统一写入原语：返回 { state, entity }，由 workbenchApi 与 Agent 工具共用。
 * 工具此前各自复制一份写入逻辑，容易与 Remote 路径行为分叉（TODO 04）。
 * ------------------------------------------------------------------------- */
function applyCreateTask(state, payload) {
  if (payload.projectId === undefined && state.settings.defaultProjectId) {
    payload.projectId = state.settings.defaultProjectId
  }
  const task = normalizeTask(payload, null)
  state.tasks = ensureArray(state.tasks).concat([task])
  auditEntry(state, 'task.created', task.title)
  return { state: state, entity: task }
}

function applyUpdateTask(state, id, patch) {
  const index = ensureArray(state.tasks).findIndex(function (task) {
    return task.id === id
  })
  if (index < 0) throw new Error('找不到该待办：' + String(id))
  const next = normalizeTask(patch || {}, state.tasks[index])
  // TODO 17 人工保护：记录人工实际修改的字段，后台/AI 不得直接覆盖它们
  const watched = ['title', 'description', 'status', 'priority', 'dueAt', 'assignee', 'projectId', 'replyStage', 'needsReply', 'needsAction', 'eventType']
  const previous = state.tasks[index]
  const edited = watched.filter(function (field) {
    return JSON.stringify(next[field] === undefined ? null : next[field]) !== JSON.stringify(previous[field] === undefined ? null : previous[field])
  })
  const guard = Object.assign({}, next.humanGuard, { editedFields: edited })
  next.humanGuard = guard
  next.id = state.tasks[index].id
  next.createdAt = state.tasks[index].createdAt
  state.tasks = state.tasks.slice()
  state.tasks[index] = next
  auditEntry(state, 'task.updated', next.title + ' → ' + next.status)
  return { state: state, entity: next }
}

function applyRecordRun(state, payload) {
  const run = normalizeRun(payload || {}, null)
  if (run.taskId && !ensureArray(state.tasks).some(function (task) {
    return task.id === run.taskId
  })) {
    throw new Error('关联的待办不存在：' + run.taskId)
  }
  state.runs = ensureArray(state.runs).concat([run])
  if (run.taskId) {
    state.tasks = ensureArray(state.tasks).map(function (task) {
      if (task.id !== run.taskId) return task
      const next = Object.assign({}, task)
      next.runIds = ensureArray(task.runIds).concat([run.id])
      next.updatedAt = hostNowIso()
      if (run.status === 'failed') next.status = 'failed'
      else if (run.status === 'running' && (task.status === 'ready' || task.status === 'draft')) next.status = 'running'
      return next
    })
  }
  auditEntry(state, 'agent.run.created', run.summary || run.id)
  return { state: state, entity: run }
}

const workbenchApi = {
  async snapshot() {
    return workbenchServiceState()
  },

  async saveSettings(patch) {
    return mutateWorkbenchState(function (state) {
      state.settings = normalizeSettings(Object.assign({}, state.settings, patch || {}))
      auditEntry(state, 'settings.updated', '更新设置：' + Object.keys(patch || {}).join(', '))
      return state
    })
  },

  async createTask(input) {
    const payload = input && typeof input === 'object' ? Object.assign({}, input) : {}
    if (!asString(payload.title, 200)) throw new Error('待办标题不能为空')
    return mutateWorkbenchState(function (state) {
      return applyCreateTask(state, payload).state
    })
  },

  async updateTask(id, patch) {
    return mutateWorkbenchState(function (state) {
      return applyUpdateTask(state, id, patch).state
    })
  },

  async deleteTask(id) {
    return mutateWorkbenchState(function (state) {
      const task = requireTask(state, id)
      state.tasks = ensureArray(state.tasks).filter(function (item) {
        return item.id !== id
      })
      state.runs = ensureArray(state.runs).filter(function (run) {
        return run.taskId !== id
      })
      auditEntry(state, 'task.deleted', task.title)
      return state
    })
  },

  async addSource(input) {
    const source = normalizeSource(input || {})
    return mutateWorkbenchState(function (state) {
      const duplicate = ensureArray(state.sources).find(function (item) {
        return item.payloadHash === source.payloadHash
      })
      if (!duplicate) {
        state.sources = ensureArray(state.sources).concat([source])
        auditEntry(state, 'source.added', source.title)
      }
      return state
    })
  },

  async createKnowledge(input) {
    const item = normalizeKnowledge(input || {})
    return mutateWorkbenchState(function (state) {
      const duplicate = ensureArray(state.knowledge).find(function (existing) {
        return existing.title === item.title && (existing.url || '') === (item.url || '')
      })
      if (!duplicate) {
        state.knowledge = ensureArray(state.knowledge).concat([item])
        auditEntry(state, 'knowledge.created', item.title)
      }
      return state
    })
  },

  async updateKnowledge(id, patch) {
    return mutateWorkbenchState(function (state) {
      const existing = ensureArray(state.knowledge).find(function (item) {
        return item.id === id
      })
      if (!existing) throw new Error('找不到该知识条目：' + String(id))
      const next = normalizeKnowledge(patch || {}, existing)
      next.id = existing.id
      state.knowledge = ensureArray(state.knowledge).map(function (item) {
        return item.id === id ? next : item
      })
      auditEntry(state, 'knowledge.updated', next.title)
      return state
    })
  },

  async deleteKnowledge(id) {
    return mutateWorkbenchState(function (state) {
      state.knowledge = ensureArray(state.knowledge).filter(function (item) {
        return item.id !== id
      })
      auditEntry(state, 'knowledge.deleted', String(id))
      return state
    })
  },

  async saveRadarItem(input) {
    const payload = input && typeof input === 'object' ? input : {}
    return mutateWorkbenchState(function (state) {
      const list = ensureArray(state.radar)
      const existing = payload.id
        ? list.find(function (item) {
            return item.id === payload.id
          })
        : payload.url
          ? list.find(function (item) {
              return item.url === asUrl(payload.url)
            })
          : null
      const item = normalizeRadarItem(payload, existing || null)
      state.radar = existing
        ? list.map(function (row) {
            return row.id === item.id ? item : row
          })
        : list.concat([item])
      auditEntry(state, existing ? 'radar.updated' : 'radar.added', item.title)
      return state
    })
  },

  async deleteRadarItem(id) {
    return mutateWorkbenchState(function (state) {
      state.radar = ensureArray(state.radar).filter(function (item) {
        return item.id !== id
      })
      auditEntry(state, 'radar.deleted', String(id))
      return state
    })
  },

  async recordRun(input) {
    return mutateWorkbenchState(function (state) {
      return applyRecordRun(state, input).state
    })
  },

  async updateRun(id, patch) {
    return mutateWorkbenchState(function (state) {
      const run = ensureArray(state.runs).find(function (item) {
        return item.id === id
      })
      if (!run) throw new Error('找不到该执行记录：' + String(id))
      const next = normalizeRun(Object.assign({}, patch || {}, { taskId: run.taskId }), run)
      next.id = run.id
      next.startedAt = run.startedAt
      state.runs = ensureArray(state.runs).map(function (item) {
        return item.id === id ? next : item
      })
      if (next.taskId && next.status === 'completed') {
        state.tasks = ensureArray(state.tasks).map(function (task) {
          if (task.id !== next.taskId) return task
          return Object.assign({}, task, { updatedAt: hostNowIso() })
        })
      }
      auditEntry(state, 'agent.run.' + next.status, next.summary || next.id)
      return state
    })
  },

  async reset(scope) {
    const target = scope === 'tasks' || scope === 'runs' ? scope : 'all'
    return mutateWorkbenchState(function (state) {
      if (target === 'tasks') {
        const removed = ensureArray(state.tasks).length
        state.tasks = []
        state.runs = []
        auditEntry(state, 'state.reset', '清空 ' + removed + ' 条待办与全部执行记录')
        return state
      }
      if (target === 'runs') {
        state.runs = []
        auditEntry(state, 'state.reset', '清空执行记录')
        return state
      }
      state.tasks = []
      state.runs = []
      state.knowledge = []
      state.radar = []
      state.sources = []
      state.audit = []
      auditEntry(state, 'state.reset', '清空业务数据，保留设置')
      return state
    })
  },

  async seedDemo() {
    return mutateWorkbenchState(function (state) {
      state.tasks = ensureArray(state.tasks).filter(function (task) {
        return task.demo !== true
      })
      state.radar = ensureArray(state.radar).filter(function (item) {
        return item.demo !== true
      })
      state.sources = ensureArray(state.sources).filter(function (item) {
        return asString(item.externalId, 40) !== 'demo-msg-1'
      })
      state.runs = []
      seedDemoData(state)
      auditEntry(state, 'state.seeded', '载入示例数据')
      return state
    })
  },

  async saveProject(input) {
    const payload = input && typeof input === 'object' ? input : {}
    const repoPath = asString(payload.repoPath, 500)
    if (!repoPath) throw new Error('仓库目录不能为空')
    return mutateWorkbenchState(function (state) {
      const list = ensureArray(state.projects)
      const existing = payload.id
        ? list.find(function (project) {
            return project.id === payload.id
          })
        : list.find(function (project) {
            return project.repoPath === repoPath
          })
      const project = normalizeProject(payload, existing || null)
      project.repoPath = repoPath
      state.projects = existing
        ? list.map(function (item) {
            return item.id === project.id ? project : item
          })
        : list.concat([project])
      invalidateEnvironmentCache()
      auditEntry(state, existing ? 'project.updated' : 'project.created', project.name + ' · ' + project.repoPath)
      return state
    })
  },

  async deleteProject(id) {
    return mutateWorkbenchState(function (state) {
      const target = ensureArray(state.projects).find(function (project) {
        return project.id === id
      })
      state.projects = ensureArray(state.projects).filter(function (project) {
        return project.id !== id
      })
      state.tasks = ensureArray(state.tasks).map(function (task) {
        return task.projectId === id ? Object.assign({}, task, { projectId: null }) : task
      })
      if (state.settings.defaultProjectId === id) state.settings.defaultProjectId = null
      invalidateEnvironmentCache()
      auditEntry(state, 'project.deleted', target ? target.name : String(id))
      return state
    })
  },

  async fetchRadar() {
    // 未配置 RSS 时按关注主题走联网发现（TODO 06 的默认路径）
    return runRadarFetchOrDiscover(workbenchContext())
  },

  /** 写回四段摘要（Agent 读原文后调用）；只改摘要字段，不动来源与时间。 */
  async updateRadar(id, patch) {
    return mutateWorkbenchState(function (state) {
      const item = ensureArray(state.radar).find(function (row) {
        return row.id === id
      })
      if (!item) throw new Error('找不到该资讯：' + String(id))
      const summary = patch && patch.summary && typeof patch.summary === 'object' ? patch.summary : null
      const index = state.radar.indexOf(item)
      const next = normalizeRadarItem(
        {
          title: patch && patch.title !== undefined ? patch.title : item.title,
          topics: patch && patch.topics !== undefined ? patch.topics : item.topics,
          summary: summary
            ? {
                change: asString(summary.change, 800),
                usage: asString(summary.usage, 800),
                risk: asString(summary.risk, 800),
                practice: asString(summary.practice, 800),
              }
            : item.summary,
        },
        item,
      )
      next.id = item.id
      next.createdAt = item.createdAt
      state.radar = state.radar.slice()
      state.radar[index] = next
      auditEntry(state, 'radar.summary', next.title)
      return state
    })
  },

  /**
   * Design report §3.2: pull @-mention messages as source evidence through the
   * real yzj-cli. Deterministic collection only — turning a mention into a task
   * stays an agent decision, so nothing is auto-created here.
   */
  /** 规则候选提取（确定性，无模型）：为尚未提取的 @我 来源生成待确认候选。 */
  async extractCandidates() {
    return mutateWorkbenchState(function (state) {
      return extractCandidatesInto(state)
    })
  },

  /** 采纳候选：原子地建任务（带来源证据）并把候选标记为已采纳。 */
  async acceptCandidate(id, patch) {
    const input = patch && typeof patch === 'object' ? patch : {}
    return mutateWorkbenchState(function (state) {
      const candidate = ensureArray(state.candidates).find(function (row) {
        return row.id === id
      })
      if (!candidate) throw new Error('找不到该候选：' + String(id))
      if (candidate.status === 'accepted' && candidate.taskId) {
        return state
      }
      const task = normalizeTask(
        {
          title: input.title || candidate.title,
          description:
            input.description ||
            [candidate.excerpt, candidate.sourceTitle ? '来源：' + candidate.sourceTitle : '']
              .filter(Boolean)
              .join('\n'),
          status: input.status || 'ready',
          priority: input.priority || 'normal',
          dueAt: input.dueAt === undefined ? candidate.dueAt : input.dueAt,
          tags: input.tags || [],
          sourceRefId: candidate.sourceRefId,
          projectId: state.settings ? state.settings.defaultProjectId : null,
          aiExtracted: true,
          confidence: candidate.confidence,
        },
        null,
      )
      state.tasks = ensureArray(state.tasks).concat([task])
      const index = state.candidates.indexOf(candidate)
      const next = normalizeCandidate(
        Object.assign({}, candidate, { status: 'accepted', taskId: task.id }),
        candidate,
      )
      next.status = 'accepted'
      next.taskId = task.id
      state.candidates = state.candidates.slice()
      state.candidates[index] = next
      auditEntry(state, 'candidate.accepted', task.title)
      return state
    })
  },

  async rejectCandidate(id) {
    return mutateWorkbenchState(function (state) {
      const candidate = ensureArray(state.candidates).find(function (row) {
        return row.id === id
      })
      if (!candidate) throw new Error('找不到该候选：' + String(id))
      const index = state.candidates.indexOf(candidate)
      state.candidates = state.candidates.slice()
      state.candidates[index] = normalizeCandidate(Object.assign({}, candidate, { status: 'rejected' }), candidate)
      state.candidates[index].status = 'rejected'
      auditEntry(state, 'candidate.rejected', candidate.title)
      return state
    })
  },

  async fetchMentions() {
    return mutateWorkbenchState(function (state) {
      return fetchYunzhijiaMentionsInto(workbenchContext(), state)
    })
  },

  /**
   * Design report §3.1 后续行动: turn one radar item into a real task, keeping
   * the source evidence. Atomic on the Host so the task can never exist
   * without its SourceRef.
   */
  async createTaskFromRadar(id) {
    return mutateWorkbenchState(function (state) {
      const item = ensureArray(state.radar).find(function (row) {
        return row.id === id
      })
      if (!item) throw new Error('找不到该资讯：' + String(id))

      const summary = item.summary || {}
      const brief = [
        summary.change ? '技术变化：' + summary.change : '',
        summary.usage ? '应用场景：' + summary.usage : '',
        summary.risk ? '采用风险：' + summary.risk : '',
        summary.practice ? '推荐实践：' + summary.practice : '',
        item.excerpt ? '原文摘录：' + item.excerpt : '',
        item.url ? '原文：' + item.url : '',
      ]
        .filter(Boolean)
        .join('\n')

      const source = normalizeSource({
        provider: asString(item.source, 40) || 'radar',
        url: item.url,
        title: item.title,
        excerpt: brief.slice(0, 2000),
        fetchedAt: item.publishedAt || item.updatedAt || hostNowIso(),
      })
      const duplicate = ensureArray(state.sources).find(function (row) {
        return row.payloadHash === source.payloadHash
      })
      const sourceId = duplicate ? duplicate.id : source.id
      if (!duplicate) {
        state.sources = ensureArray(state.sources).concat([source])
      }

      const duplicateTask = ensureArray(state.tasks).find(function (row) {
        return row.sourceRefId === sourceId && row.title === '实践：' + item.title
      })
      if (duplicateTask) {
        auditEntry(state, 'task.fromRadar', '重复生成已忽略：' + item.title)
        return state
      }
      const task = normalizeTask(
        {
          title: '实践：' + item.title,
          description: brief,
          status: 'ready',
          priority: 'normal',
          tags: asTags(item.topics),
          sourceRefId: sourceId,
          projectId: state.settings ? state.settings.defaultProjectId : null,
        },
        null,
      )
      state.tasks = ensureArray(state.tasks).concat([task])
      auditEntry(state, 'task.fromRadar', task.title)
      return state
    })
  },

  async search(request) {
    return runUnifiedSearch(workbenchContext(), request || {})
  },

  async environment() {
    return buildEnvironment(workbenchContext())
  },

  /** GitHub 只读快照（PR / CI），走 gh CLI 白名单命令。 */
  async github() {
    return buildGithubSnapshot(workbenchContext())
  },

  /** 按消息 id 取助手回复正文（原生聊天内嵌动作使用）。 */
  async assistantMessage(request) {
    return readAssistantMessage(workbenchContext(), request || {})
  },

  /** TODO 15：AI 识别状态（队列概览）。 */
  async analysisStatus() {
    const state = loadWorkbenchState()
    const queue = ensureArray(state.analysisQueue)
    const by = function (status) {
      return queue.filter(function (row) { return row.status === status }).length
    }
    return {
      enabled: !!(state.settings.aiExtract && state.settings.aiExtract.enabled),
      autoRegister: !!(state.settings.aiExtract && state.settings.aiExtract.autoRegister),
      pending: by('pending'),
      failed: by('failed'),
      awaitingHuman: by('awaiting_human'),
      done: by('done'),
      entries: queue.slice(-12).reverse(),
      note: '采集与识别解耦：消息先入库，AI 识别单独运行、失败可重放。',
    }
  },

  /** TODO 15：运行一批 AI 识别（手动触发；自动运行由 19 接管）。 */
  async analyzeRun(request) {
    return runAnalysisBatch(workbenchContext(), request || {})
  },

  /** TODO 20：批量生成四段摘要（读原文 → 模型 → 写回卡片）。 */
  async radarSummarize(request) {
    return runRadarSummarizeBatch(workbenchContext(), request || {})
  },

  /** TODO 14：清空分析队列（重新采集/重整时使用）。 */
  async analyzeReset() {
    return mutateWorkbenchState(function (state) {
      state.analysisQueue = []
      auditEntry(state, 'analysis.reset', '清空分析队列')
      return state
    })
  },

  /** TODO 15：人工确认——把 awaiting_human 的条目按已保存分析建待办。 */
  async analyzeConfirm(entryId) {
    return confirmAnalysis(workbenchContext(), entryId)
  },

  /** TODO 17：人工处置（保护字段）。ignore/snooze/handled 不改任务 status，仅写 humanGuard。 */
  async taskMarkHuman(id, mark) {
    const payload = mark && typeof mark === 'object' ? mark : {}
    return mutateWorkbenchState(function (state) {
      const index = ensureArray(state.tasks).findIndex(function (task) {
        return task.id === id
      })
      if (index < 0) throw new Error('找不到该待办：' + String(id))
      const task = state.tasks[index]
      const guard = normalizeHumanGuard(
        Object.assign({}, normalizeHumanGuard(task.humanGuard), {
          ignored: payload.ignored === true ? true : normalizeHumanGuard(task.humanGuard).ignored && payload.ignored !== false,
          handledConfirmed: payload.handledConfirmed === true ? true : normalizeHumanGuard(task.humanGuard).handledConfirmed && payload.handledConfirmed !== false,
          snoozeUntil: payload.snoozeUntil === undefined ? normalizeHumanGuard(task.humanGuard).snoozeUntil : asIso(payload.snoozeUntil) || null,
        }),
      )
      const next = normalizeTask({ status: task.status }, task)
      next.humanGuard = guard
      state.tasks = state.tasks.slice()
      state.tasks[index] = next
      auditEntry(state, 'task.humanMarked', task.title + '（' + JSON.stringify(payload).slice(0, 80) + '）')
      return state
    })
  },

  /** 删除来源证据：同时清理派生候选，并把引用它的待办解除来源关联。 */
  async deleteSource(id) {
    return mutateWorkbenchState(function (state) {
      const sourceId = String(id)
      const exists = ensureArray(state.sources).some(function (row) {
        return row.id === sourceId
      })
      if (!exists) throw new Error('找不到该来源：' + sourceId)
      state.sources = ensureArray(state.sources).filter(function (row) {
        return row.id !== sourceId
      })
      state.candidates = ensureArray(state.candidates).filter(function (candidate) {
        return candidate.sourceRefId !== sourceId
      })
      state.tasks = ensureArray(state.tasks).map(function (task) {
        if (task.sourceRefId !== sourceId) return task
        return Object.assign({}, task, { sourceRefId: null, updatedAt: hostNowIso() })
      })
      auditEntry(state, 'source.deleted', '删除来源 ' + sourceId)
      return state
    })
  },

  /** 删除执行记录：同步从关联任务的 runIds 中移除。 */
  async deleteRun(id) {
    return mutateWorkbenchState(function (state) {
      const runId = String(id)
      const exists = ensureArray(state.runs).some(function (row) {
        return row.id === runId
      })
      if (!exists) throw new Error('找不到该执行记录：' + runId)
      state.runs = ensureArray(state.runs).filter(function (row) {
        return row.id !== runId
      })
      state.tasks = ensureArray(state.tasks).map(function (task) {
        if (ensureArray(task.runIds).indexOf(runId) < 0) return task
        return Object.assign({}, task, { runIds: ensureArray(task.runIds).filter(function (item) { return item !== runId }), updatedAt: hostNowIso() })
      })
      auditEntry(state, 'run.deleted', '删除执行记录 ' + runId)
      return state
    })
  },

  /** 删除候选（彻底移除，区别于 reject）。 */
  async deleteCandidate(id) {
    return mutateWorkbenchState(function (state) {
      const candidateId = String(id)
      const exists = ensureArray(state.candidates).some(function (row) {
        return row.id === candidateId
      })
      if (!exists) throw new Error('找不到该候选：' + candidateId)
      state.candidates = ensureArray(state.candidates).filter(function (row) {
        return row.id !== candidateId
      })
      auditEntry(state, 'candidate.deleted', '删除候选 ' + candidateId)
      return state
    })
  },

  /** 工作台助手：向原生会话提交提示并等待本轮回复（TODO 04）。 */
  async assistantAsk(request) {
    return runAssistantAsk(workbenchContext(), request || {})
  },

  /** 只提交提示（立即返回 fromSeq），配合 assistantDelta 做渐进渲染。 */
  async assistantSend(request) {
    return sendAssistantPrompt(workbenchContext(), request || {})
  },

  /** 增量读取会话记录（fromSeq 之后的新条目 + turnActive）。 */
  async assistantDelta(request) {
    return readAssistantDelta(workbenchContext(), request || {})
  },

  async assistantHistory() {
    return readAssistantHistory(workbenchContext())
  },

  /** 最近原生会话列表（供侧栏切换）。 */
  async assistantSessions(request) {
    return listAssistantSessions(workbenchContext(), request || {})
  },

  /** 读取指定会话的记录（缺省为助手会话）。 */
  async assistantTranscript(request) {
    return readAssistantTranscript(workbenchContext(), request || {})
  },

  async assistantReset() {
    return resetAssistantSession(workbenchContext())
  },

  /** 立即跑一次后台自动化（TODO 07）；返回本次结果。 */
  async automationRun() {
    return runAutomationTick(workbenchContext())
  },

  /** 自动化状态：是否开启、间隔、上次结果、是否到期。 */
  async automationStatus() {
    const state = loadWorkbenchState()
    const config = (state.settings && state.settings.automation) || {}
    return {
      enabled: config.enabled === true,
      intervalMinutes: Number(config.intervalMinutes) || 60,
      radar: config.radar !== false,
      mentions: config.mentions !== false,
      lastAutomation: state.lastAutomation || null,
      due: automationDue(state, Date.now()),
      note: '插件侧定时器：仅在 DSH 进程运行期间生效，退出/休眠时暂停，恢复后按到期补跑一次。',
    }
  },

  /** 手动备份 + 列出 + 恢复（TODO 11）。 */
  async backup() {
    const path = createBackup('manual')
    return {
      created: path,
      backups: listBackups().slice(0, BACKUP_KEEP),
    }
  },

  async backups() {
    return { backups: listBackups().slice(0, BACKUP_KEEP) }
  },

  async restoreBackup(id) {
    const state = restoreBackup(id)
    return state
  },

  /** 轻量版本探测：Client 轮询这个端点，只有 revision 变新才重取整份快照。 */
  async revision() {
    const state = loadWorkbenchState()
    return { revision: Number(state.revision) || 0, updatedAt: state.updatedAt }
  },

  async diagnostics() {
    const state = loadWorkbenchState()
    const path = workbenchStatePath()
    const toolNames = ensureArray(workbenchCtxToolNames())
    return {
      platform: HOST_META.platform,
      arch: HOST_META.arch,
      nodeVersion: HOST_META.nodeVersion,
      statePath: path,
      dataPath: path,
      dataBytes: fileSizeOf(path),
      counts: workbenchCounts(state),
      hostTime: hostNowIso(),
      loadNote: workbenchLoadNote,
      toolNames: toolNames,
    }
  },
}

/* ---------------------------------------------------------------------------
 * The Typert gateway resolves `workbench/<method>` by reading a `typertRemote`
 * binding off the service instance that `ctx.get('workbench')` returns — see
 * the gateway's validateBinding(): `Reflect.get(original, 'typertRemote')`
 * must yield `{ service: original, serviceKey: 'workbench', namespace: … }`,
 * otherwise it throws
 *   gateway/binding-invalid: Service "workbench" has no visible typertRemote
 *   binding
 * which is exactly the failure the shipped UI reported. `service` must be this
 * same object so readBinding()'s identity check passes; the frozen shape
 * mirrors bindTypertRemote() from @deepseek-ai/dsh-typert-protocol.
 * ------------------------------------------------------------------------- */
Object.defineProperty(workbenchApi, 'typertRemote', {
  value: Object.freeze({
    service: workbenchApi,
    serviceKey: 'workbench',
    namespace: 'workbench',
  }),
  enumerable: false,
  configurable: false,
  writable: false,
})

let workbenchToolNames = []

function workbenchCtxToolNames() {
  return workbenchToolNames
}

function registerWorkbenchToolNames(names) {
  workbenchToolNames = names.slice()
}

// ===== 33-search.js =====
/* ============================================================================
 * dev-workbench host — unified search orchestration
 *
 * Design report §3.3: several providers, each with its own capability and its
 * own failure mode; a single source failing must return partial results, and an
 * answer without sources must not be presented as fact.
 *
 * This module therefore returns GROUPS, not a flat list: every group carries
 * its own `status` (`ok` / `empty` / `unavailable` / `error`) and the reason, so
 * the UI can say "互联网这一路没查成" instead of silently showing fewer rows.
 * The plugin never summarises with a model here — that stays an Agent job, so
 * no search result is ever turned into an unsourced claim.
 * ========================================================================== */

const SEARCH_GROUP_LIMIT = 20

function searchNeedle(value) {
  return asString(value, 200).toLowerCase()
}

function matchesText(haystack, needle) {
  if (!needle) return false
  return String(haystack || '').toLowerCase().indexOf(needle) >= 0
}

function searchSnippet(text, needle, fallback) {
  const source = String(text || fallback || '')
  if (!source) return ''
  if (!needle) return source.slice(0, 160)
  const index = source.toLowerCase().indexOf(needle)
  if (index < 0) return source.slice(0, 160)
  const start = Math.max(0, index - 50)
  return (start > 0 ? '…' : '') + source.slice(start, start + 160)
}

function searchLocalGroups(state, query) {
  const needle = searchNeedle(query)
  const groups = []

  const tasks = ensureArray(state.tasks)
    .filter(function (task) {
      return (
        matchesText(task.title, needle) ||
        matchesText(task.description, needle) ||
        asTags(task.tags).some(function (tag) {
          return matchesText(tag, needle)
        })
      )
    })
    .slice(0, SEARCH_GROUP_LIMIT)
    .map(function (task) {
      return {
        id: task.id,
        title: task.title,
        snippet: searchSnippet(task.description, needle, task.title),
        url: null,
        kind: 'task',
        extra: {
          status: task.status,
          priority: task.priority,
          dueAt: task.dueAt,
          projectId: task.projectId,
          tags: task.tags,
          at: task.dueAt || task.updatedAt || task.createdAt,
        },
      }
    })

  const knowledge = ensureArray(state.knowledge)
    .filter(function (item) {
      return (
        matchesText(item.title, needle) ||
        matchesText(item.body, needle) ||
        asTags(item.tags).some(function (tag) {
          return matchesText(tag, needle)
        })
      )
    })
    .slice(0, SEARCH_GROUP_LIMIT)
    .map(function (item) {
      return {
        id: item.id,
        title: item.title,
        snippet: searchSnippet(item.body, needle, item.title),
        url: item.url || null,
        kind: 'knowledge',
        extra: { kind: item.kind, tags: item.tags, at: item.createdAt },
      }
    })

  const radar = ensureArray(state.radar)
    .filter(function (item) {
      const summary = item.summary || {}
      return (
        matchesText(item.title, needle) ||
        matchesText(item.source, needle) ||
        matchesText(summary.change, needle) ||
        matchesText(summary.usage, needle) ||
        matchesText(summary.risk, needle) ||
        matchesText(summary.practice, needle)
      )
    })
    .slice(0, SEARCH_GROUP_LIMIT)
    .map(function (item) {
      const summary = item.summary || {}
      return {
        id: item.id,
        title: item.title,
        snippet: searchSnippet([summary.change, summary.usage].filter(Boolean).join(' '), needle, item.title),
        url: item.url || null,
        kind: 'radar',
        extra: {
          source: item.source,
          topics: item.topics,
          publishedAt: item.publishedAt,
          at: item.publishedAt || item.updatedAt || item.createdAt,
        },
      }
    })

  const sources = ensureArray(state.sources)
    .filter(function (item) {
      return matchesText(item.title, needle) || matchesText(item.excerpt, needle) || matchesText(item.provider, needle)
    })
    .slice(0, SEARCH_GROUP_LIMIT)
    .map(function (item) {
      return {
        id: item.id,
        title: item.title,
        snippet: searchSnippet(item.excerpt, needle, item.title),
        url: item.url || null,
        kind: 'source',
        extra: { provider: item.provider, fetchedAt: item.fetchedAt, hash: item.payloadHash, at: item.fetchedAt },
      }
    })

  groups.push({ id: 'tasks', label: '我的待办', status: tasks.length ? 'ok' : 'empty', items: tasks, note: null })
  groups.push({ id: 'knowledge', label: '知识空间', status: knowledge.length ? 'ok' : 'empty', items: knowledge, note: null })
  groups.push({ id: 'radar', label: '技术雷达', status: radar.length ? 'ok' : 'empty', items: radar, note: null })
  groups.push({ id: 'sources', label: '来源证据', status: sources.length ? 'ok' : 'empty', items: sources, note: null })
  return groups
}

async function searchWebGroup(ctx, query) {
  const web = ctx && ctx.get ? ctx.get('web') : null
  if (!web || typeof web.search !== 'function') {
    return {
      id: 'web',
      label: '互联网',
      status: 'unavailable',
      items: [],
      note: '当前 profile 未组合 web 搜索服务；企业外部事实因此不会出现在结果里。',
    }
  }
  let signal
  try {
    signal = AbortSignal.timeout(9000)
  } catch (e) {
    signal = undefined
  }
  try {
    const result = await web.search({ query: query, maxResults: 8 }, signal)
    const items = (result && Array.isArray(result.sources) ? result.sources : []).map(function (source, index) {
      return {
        id: 'web-' + index,
        title: source.title || source.url,
        snippet: source.snippet || '',
        url: source.url,
        kind: 'web',
        extra: { publishedAt: source.publishedAt || null },
      }
    })
    return {
      id: 'web',
      label: '互联网',
      status: items.length ? 'ok' : 'empty',
      items: items,
      note: result && result.truncated ? '结果已按 maxResults 截断' : '外部事实，请以来源链接与发布时间为准。',
    }
  } catch (e) {
    return {
      id: 'web',
      label: '互联网',
      status: 'error',
      items: [],
      note: '检索失败：' + String((e && e.message) || e),
    }
  }
}

async function runUnifiedSearch(ctx, request) {
  const query = asString(request && request.query, 200)
  if (!query) throw new Error('搜索关键词不能为空')
  const state = loadWorkbenchState()
  const groups = searchLocalGroups(state, query)
  // 本地项目（文件名 + 文本片段）：不受联网与凭据影响，始终可用
  groups.push(await searchLocalFiles(ctx, query))

  if (!request || request.includeEnterprise !== false) {
    groups.push(await searchEnterpriseGroup(ctx, query))
    // 三路按意图触发：联系人（像人名/找人）、会议室（会议类）、考勤（考勤类）。
    // 返回 null 表示这次查询不适用，不显示空分组。
    for (const provider of [searchContactsGroup, searchRoomsGroup, searchAttendanceGroup, searchEventsGroup]) {
      const group = await provider(ctx, query)
      if (group) groups.push(group)
    }
  }
  // PR / CI：只在代码协作类意图下触发（每次都会打 gh，按需调用）
  if (/\bpr\b|拉取请求|评审|review|合并|merge|\bci\b|构建|流水线|github/i.test(query)) {
    const gh = await buildGithubSnapshot(ctx)
    const items = []
    if (gh.status === 'ok') {
      gh.prs.items.slice(0, 5).forEach(function (pr) {
        items.push({
          id: 'pr-' + pr.number,
          title: '#' + pr.number + ' ' + pr.title,
          snippet: [pr.author, pr.state, pr.draft ? '草稿' : ''].filter(Boolean).join(' · '),
          url: pr.url,
          kind: 'pr',
          extra: { at: pr.updatedAt },
        })
      })
      gh.runs.items.slice(0, 5).forEach(function (run) {
        items.push({
          id: 'run-' + run.id,
          title: (run.workflow || 'CI') + ' · ' + (run.conclusion || run.status || '未知'),
          snippet: [run.branch, run.status].filter(Boolean).join(' · '),
          url: run.url,
          kind: 'ci',
          extra: { at: run.createdAt },
        })
      })
    }
    groups.push({
      id: 'github',
      label: 'PR / CI',
      status: gh.status === 'ok' ? (items.length ? 'ok' : 'empty') : 'unavailable',
      items: items,
      note: gh.status === 'ok' ? gh.note : gh.note,
    })
  }

  if (!request || request.includeWeb !== false) {
    groups.push(await searchWebGroup(ctx, query))
  }
  const total = groups.reduce(function (sum, group) {
    return sum + group.items.length
  }, 0)
  return {
    query: query,
    at: hostNowIso(),
    total: total,
    groups: groups,
  }
}

// ===== 34-environment.js =====
/* ============================================================================
 * dev-workbench host — read-only engineering environment
 *
 * Design report §3.5 asks for Git branches, pending review, CI state, Docker
 * containers and port usage, "默认只读". This module delivers the part that can
 * be observed truthfully from one machine without credentials:
 *
 *   - git branch / dirty counts / last commit, per configured project and for
 *     the Host's default working directory;
 *   - docker container names, images and status.
 *
 * Everything goes through the read-only allowlist in 28-exec.js. Nothing here
 * writes, stages, pushes, or starts a container. A missing binary, a missing
 * project path and a non-repository directory are all reported as states, not
 * thrown errors, so the panel degrades instead of breaking.
 * ========================================================================== */

const ENVIRONMENT_TTL_MS = 45 * 1000
let environmentCache = { at: 0, value: null }

function cwdForHostCommands(ctx) {
  const workingDirectory = ctx && ctx.get ? ctx.get('workingDirectory') : null
  if (workingDirectory && typeof workingDirectory.defaultDirectory === 'string' && workingDirectory.defaultDirectory) {
    return workingDirectory.defaultDirectory
  }
  return dshHomeDir()
}

async function readGitRepository(ctx, dir, label) {
  if (!dir) {
    return { label: label, dir: dir || null, status: 'unavailable', reason: '未配置仓库目录' }
  }
  const status = await runReadOnlyCommand(ctx, ['git', 'status', '--porcelain=v1', '-b'], dir)
  if (status.status !== 'ok') {
    const reason =
      status.status === 'unavailable'
        ? status.reason
        : /not a git repository/i.test(status.stderr || '')
          ? '该目录不是 Git 仓库'
          : status.reason || 'git status 失败'
    return { label: label, dir: dir, status: status.status === 'unavailable' ? 'unavailable' : 'error', reason: reason }
  }

  const lines = String(status.stdout || '')
    .split('\n')
    .filter(function (line) {
      return line.trim().length > 0
    })
  const header = lines.length > 0 ? lines[0] : ''
  const branchMatch = /^##\s*([^\s.]+)/.exec(header)
  const changes = lines.slice(1)
  const uptodateMatch = /\[(ahead|behind|gone)/.exec(header)

  const log = await runReadOnlyCommand(ctx, ['git', 'log', '-1', '--pretty=%h\x1f%s\x1f%ar'], dir)
  let lastCommit = null
  if (log.status === 'ok' && log.stdout.trim()) {
    const parts = log.stdout.trim().split('\x1f')
    lastCommit = { hash: parts[0] || '', subject: parts[1] || '', when: parts[2] || '' }
  }

  return {
    label: label,
    dir: dir,
    status: 'ok',
    branch: branchMatch ? branchMatch[1] : '(detached)',
    track: uptodateMatch ? uptodateMatch[1] : 'in-sync',
    changed: changes.length,
    staged: changes.filter(function (line) {
      return /^[MADRC]/.test(line)
    }).length,
    unstaged: changes.filter(function (line) {
      return /^.[MADRC]/.test(line)
    }).length,
    untracked: changes.filter(function (line) {
      return /^\?\?/.test(line)
    }).length,
    files: changes.slice(0, 12),
    lastCommit: lastCommit,
  }
}

async function readDockerState(ctx) {
  const docker = await runReadOnlyCommand(
    ctx,
    ['docker', 'ps', '--format', '{{.Names}}\t{{.Image}}\t{{.Status}}'],
    cwdForHostCommands(ctx),
  )
  if (docker.status !== 'ok') {
    const reason =
      docker.status === 'unavailable'
        ? docker.reason
        : /Cannot connect to the Docker daemon|Is the docker daemon running/i.test(docker.stderr || '')
          ? 'Docker 守护进程未运行'
          : docker.reason || 'docker ps 失败'
    return {
      status: docker.status === 'unavailable' ? 'unavailable' : 'error',
      reason: reason,
      containers: [],
    }
  }
  const containers = String(docker.stdout || '')
    .split('\n')
    .map(function (line) {
      return line.split('\t')
    })
    .filter(function (parts) {
      return parts.length >= 3 && parts[0]
    })
    .slice(0, 20)
    .map(function (parts) {
      return { name: parts[0], image: parts[1], state: parts[2] }
    })
  return { status: 'ok', reason: null, containers: containers }
}

function invalidateEnvironmentCache() {
  environmentCache = { at: 0, value: null }
}

/** Listening TCP ports from `lsof -i -P -n -sTCP:LISTEN` (read-only). */
async function readListeningPorts(ctx) {
  const result = await runReadOnlyCommand(
    ctx,
    ['lsof', '-i', '-P', '-n', '-sTCP:LISTEN'],
    cwdForHostCommands(ctx),
  )
  if (result.status !== 'ok') {
    return {
      status: result.status === 'unavailable' ? 'unavailable' : 'error',
      reason: result.reason || 'lsof 执行失败',
      ports: [],
    }
  }
  const seen = new Set()
  const ports = []
  for (const line of String(result.stdout || '').split('\n')) {
    if (!line || /^COMMAND\b/.test(line)) continue
    const columns = line.trim().split(/\s+/)
    if (columns.length < 9) continue
    const name = columns[8]
    const match = /^(.*):(\d+)$/.exec(name)
    if (!match) continue
    const entry = {
      command: columns[0].slice(0, 24),
      pid: columns[1],
      address: match[1],
      port: Number(match[2]),
    }
    const key = entry.command + '|' + entry.address + '|' + entry.port
    if (seen.has(key)) continue
    seen.add(key)
    if (ports.length < 30) ports.push(entry)
  }
  ports.sort(function (a, b) {
    return a.port - b.port || String(a.command).localeCompare(String(b.command))
  })
  return { status: 'ok', reason: null, ports: ports }
}

/** 进程 CPU/内存 Top（ps aux，只读）。 */
async function readTopProcesses(ctx) {
  const result = await runReadOnlyCommand(ctx, ['ps', 'aux'], cwdForHostCommands(ctx))
  if (result.status !== 'ok') {
    return { status: result.status === 'unavailable' ? 'unavailable' : 'error', reason: result.reason || 'ps 失败', items: [] }
  }
  const rows = []
  for (const line of String(result.stdout || '').split('\n')) {
    if (!line || /^USER\b/.test(line)) continue
    const columns = line.trim().split(/\s+/)
    if (columns.length < 11) continue
    const cpu = Number(columns[2])
    const mem = Number(columns[3])
    if (!Number.isFinite(cpu) || !Number.isFinite(mem)) continue
    const command = columns.slice(10).join(' ').slice(0, 90)
    rows.push({ user: columns[0].slice(0, 24), pid: columns[1], cpu: cpu, mem: mem, command: command })
  }
  rows.sort(function (a, b) {
    return b.cpu - a.cpu || b.mem - a.mem
  })
  return { status: 'ok', reason: null, items: rows.slice(0, 12) }
}

async function buildEnvironment(ctx) {
  if (environmentCache.value && Date.now() - environmentCache.at < ENVIRONMENT_TTL_MS) {
    return environmentCache.value
  }
  const state = loadWorkbenchState()
  const targets = []
  const seen = new Set()

  const defaultDir = cwdForHostCommands(ctx)
  if (defaultDir) {
    targets.push({ dir: defaultDir, label: '当前工作目录' })
    seen.add(defaultDir)
  }
  ensureArray(state.projects)
    .slice(0, 6)
    .forEach(function (project) {
      if (!project.repoPath || seen.has(project.repoPath)) return
      seen.add(project.repoPath)
      targets.push({ dir: project.repoPath, label: project.name || project.repoPath })
    })

  const repositories = []
  for (const target of targets) {
    repositories.push(await readGitRepository(ctx, target.dir, target.label))
  }

  const value = {
    at: hostNowIso(),
    cwd: defaultDir,
    git: repositories,
    docker: await readDockerState(ctx),
    ports: await readListeningPorts(ctx),
    processes: await readTopProcesses(ctx),
    note: '全部为只读探测：git status/log、docker ps、lsof -i、ps aux，不写仓库、不启动容器、不结束进程。',
  }
  environmentCache = { at: Date.now(), value: value }
  return value
}

// ===== 36-files.js =====
/* ============================================================================
 * dev-workbench host — 本地项目搜索（设计报告 §3.3「本地项目」Provider）
 *
 * 在 Host 侧只读遍历工作目录 / 项目仓库，按**文件名**与**文本内容**匹配，
 * 返回相对路径 + 命中行片段。约束：
 *   - 只在配置的根目录内（Host 工作目录 + 项目 repoPath），绝不越界；
 *   - 跳过依赖/构建/版本库目录（node_modules、.git、dist 等）；
 *   - 遍历量、读取量、返回量都有上限，避免大仓卡死；
 *   - 只读文本白名单扩展名，二进制不读；命中行做长度截断。
 * ========================================================================== */

const FILE_SEARCH_MAX_ENTRIES = 4000
const FILE_SEARCH_MAX_CONTENT_READS = 300
const FILE_SEARCH_MAX_RESULTS = 12
const FILE_SEARCH_MAX_DEPTH = 7
const FILE_SEARCH_MAX_BYTES = 256 * 1024

const FILE_SEARCH_SKIP_DIRS = new Set([
  'node_modules',
  '.git',
  '.svn',
  '.hg',
  'dist',
  'build',
  'out',
  'target',
  'vendor',
  'coverage',
  '.next',
  '.nuxt',
  '.venv',
  'venv',
  '__pycache__',
  '.idea',
  '.vscode',
  'Pods',
])

const FILE_SEARCH_TEXT_EXT = new Set([
  '.ts', '.tsx', '.js', '.jsx', '.mjs', '.cjs', '.json', '.md', '.mdx',
  '.yml', '.yaml', '.toml', '.ini', '.conf', '.env', '.txt', '.csv',
  '.py', '.java', '.kt', '.kts', '.go', '.rs', '.rb', '.php', '.cs',
  '.sql', '.sh', '.bash', '.zsh', '.css', '.scss', '.less', '.html', '.htm',
  '.vue', '.svelte', '.xml', '.gradle',
])

let fileIndexCache = new Map()

function fileSearchRoots(ctx) {
  const roots = []
  const push = function (dir, label) {
    if (!dir || typeof dir !== 'string') return
    if (!existsSync(dir)) return
    if (roots.some(function (root) { return root.dir === dir })) return
    roots.push({ dir: dir, label: label })
  }
  const state = loadWorkbenchState()
  ensureArray(state.projects).forEach(function (project) {
    if (project.repoPath) push(project.repoPath, project.name || project.repoPath)
  })
  push(cwdForHostCommands(ctx), '当前工作目录')
  return roots.slice(0, 3)
}

function fileExtOf(name) {
  const index = name.lastIndexOf('.')
  return index < 0 ? '' : name.slice(index).toLowerCase()
}

/** 浅层遍历得到候选文件（带 mtime 缓存，60s 内复用）。 */
function indexRoot(root) {
  const cached = fileIndexCache.get(root.dir)
  if (cached && Date.now() - cached.at < 60 * 1000) return cached.files
  const files = []
  const queue = [{ dir: root.dir, depth: 0 }]
  let visited = 0
  while (queue.length > 0 && visited < FILE_SEARCH_MAX_ENTRIES) {
    const current = queue.shift()
    let entries
    try {
      entries = readdirSync(current.dir, { withFileTypes: true })
    } catch (e) {
      continue
    }
    for (const entry of entries) {
      if (visited >= FILE_SEARCH_MAX_ENTRIES) break
      const name = String(entry.name)
      if (name.startsWith('.') && name !== '.env') continue
      const full = join(current.dir, name)
      if (entry.isDirectory()) {
        if (FILE_SEARCH_SKIP_DIRS.has(name)) continue
        if (current.depth + 1 > FILE_SEARCH_MAX_DEPTH) continue
        queue.push({ dir: full, depth: current.depth + 1 })
        continue
      }
      if (!entry.isFile()) continue
      visited += 1
      files.push({ path: full, name: name, rel: full.slice(root.dir.length + 1) })
    }
  }
  fileIndexCache.set(root.dir, { at: Date.now(), files: files })
  return files
}

function readTextSnippet(path, needle) {
  let stat
  try {
    stat = statSync(path)
  } catch (e) {
    return null
  }
  if (!stat.isFile() || stat.size > FILE_SEARCH_MAX_BYTES) return null
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch (e) {
    return null
  }
  const lower = text.toLowerCase()
  const index = lower.indexOf(needle)
  if (index < 0) return null
  const lineStart = text.lastIndexOf('\n', index) + 1
  const lineEnd = text.indexOf('\n', index)
  const line = text.slice(lineStart, lineEnd < 0 ? Math.min(text.length, lineStart + 240) : lineEnd).trim()
  const lineNo = text.slice(0, index).split('\n').length
  return { snippet: line.slice(0, 240), line: lineNo, mtime: stat.mtime.toISOString() }
}

async function searchLocalFiles(ctx, query) {
  const needleRaw = asString(query, 120)
  const needle = needleRaw.toLowerCase()
  if (!needle) return { id: 'files', label: '本地项目', status: 'empty', items: [], note: null }
  const roots = fileSearchRoots(ctx)
  if (roots.length === 0) {
    return { id: 'files', label: '本地项目', status: 'unavailable', items: [], note: '没有可搜索的工作目录：在「连接与设置 → 项目」添加仓库目录。' }
  }

  const hits = []
  let contentReads = 0
  for (const root of roots) {
    const files = indexRoot(root)
    for (const file of files) {
      if (hits.length >= FILE_SEARCH_MAX_RESULTS) break
      const nameHit = file.name.toLowerCase().indexOf(needle) >= 0
      const isText = FILE_SEARCH_TEXT_EXT.has(fileExtOf(file.name))
      let contentHit = null
      if (!nameHit && isText && contentReads < FILE_SEARCH_MAX_CONTENT_READS) {
        contentReads += 1
        contentHit = readTextSnippet(file.path, needle)
      }
      if (!nameHit && !contentHit) continue
      hits.push({
        id: 'file-' + file.path,
        title: file.rel,
        snippet: contentHit ? '第 ' + contentHit.line + ' 行：' + contentHit.snippet : '文件名匹配 · ' + root.label,
        url: null,
        kind: 'file',
        extra: {
          at: contentHit ? contentHit.mtime : null,
          project: root.label,
          path: file.path,
        },
      })
    }
  }

  return {
    id: 'files',
    label: '本地项目',
    status: hits.length ? 'ok' : 'empty',
    items: hits,
    note:
      '只读遍历 ' +
      roots.length +
      ' 个根目录（跳过 node_modules/.git 等），命中文件与文本片段；不读取二进制、不越界。',
  }
}

// ===== 36-radar-fetch.js =====
/* ============================================================================
 * dev-workbench host — radar feed fetch (design report §3.1 内容源)
 *
 * Fetches the RSS/Atom sources configured in settings.feeds through the Host's
 * `web` service and turns new entries into radar items. Three rules from the
 * report are enforced structurally:
 *
 *   - 来源 URL、发布日期可打开：every fetched item keeps its original link and
 *     pubDate; the feed label becomes `source`.
 *   - 去重与缓存：dedupe is by URL against what is already stored (and within
 *     the batch), so a repeated fetch adds nothing.
 *   - 智能摘要：NOT generated here. A plugin has no model; the raw description
 *     is kept as `excerpt` and the four-part summary stays empty until an
 *     agent digests it. No field ever pretends to be an AI summary.
 *
 * Per-source failures degrade independently: one Cloudflare-blocked feed shows
 * as `error` in the persisted report while the others still land.
 * ========================================================================== */

const RADAR_FETCH_TIMEOUT_MS = 12000
const RADAR_FETCH_PER_FEED_LIMIT = 10
const RADAR_FETCH_TOTAL_LIMIT = 30

/** 标题三元组集合，用于语义近似去重（不依赖模型）。 */
function radarTrigrams(text) {
  const clean = String(text || '')
    .toLowerCase()
    .replace(/[\s\p{P}\p{S}]+/gu, ' ')
    .trim()
  const set = new Set()
  for (let i = 0; i < clean.length - 2; i += 1) set.add(clean.slice(i, i + 3))
  if (set.size === 0 && clean.length > 0) set.add(clean)
  return set
}

function radarSimilarity(left, right) {
  const a = radarTrigrams(left)
  const b = radarTrigrams(right)
  if (a.size === 0 || b.size === 0) return 0
  let shared = 0
  a.forEach(function (gram) {
    if (b.has(gram)) shared += 1
  })
  return shared / (a.size + b.size - shared)
}

function radarDecodeEntities(text) {
  return String(text)
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;|&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
}

function radarStripHtml(text) {
  return radarDecodeEntities(String(text || ''))
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t\r\f]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim()
}

/** Extract one inner text of `tag` from a single item block, CDATA-aware. */
function radarTagValue(block, tag) {
  const re = new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + tag + '>', 'i')
  const match = re.exec(block)
  if (!match) return ''
  let value = match[1].trim()
  const cdata = /^<!\[CDATA\[([\s\S]*)\]\]>$/i.exec(value)
  if (cdata) value = cdata[1]
  return radarDecodeEntities(value).trim()
}

/** Atom links are attribute-carrying; prefer rel="alternate" (the permalink). */
function radarAtomLink(block) {
  const links = []
  const re = /<link\b([^>]*)\/?>/gi
  let match
  while ((match = re.exec(block)) !== null) {
    const attrs = match[1] || ''
    const href = /href\s*=\s*"([^"]*)"/i.exec(attrs) || /href\s*=\s*'([^']*)'/i.exec(attrs)
    if (!href) continue
    const rel = /rel\s*=\s*"([^"]*)"/i.exec(attrs) || /rel\s*=\s*'([^']*)'/i.exec(attrs)
    links.push({ href: radarDecodeEntities(href[1]).trim(), rel: rel ? rel[1] : '' })
  }
  const alternate = links.find(function (link) {
    return link.rel === 'alternate' || link.rel === ''
  })
  return (alternate || links[0] || {}).href || ''
}

/** Parse RSS 2.0 `<item>` or Atom `<entry>` blocks into plain candidates. */
function radarParseFeed(xml) {
  const source = String(xml || '')
  if (!source) return []
  const isAtom = /<feed\b/i.test(source) && /<entry\b/i.test(source)
  const blockRe = isAtom ? /<entry\b[\s\S]*?<\/entry>/gi : /<item\b[\s\S]*?<\/item>/gi
  const out = []
  let match
  while ((match = blockRe.exec(source)) !== null) {
    const block = match[0]
    const title = radarTagValue(block, 'title')
    let url = ''
    if (isAtom) {
      url = radarAtomLink(block)
    } else {
      url = radarTagValue(block, 'link')
    }
    if (!url) url = radarTagValue(block, 'guid') || ''
    const dateRaw =
      radarTagValue(block, 'pubDate') ||
      radarTagValue(block, 'published') ||
      radarTagValue(block, 'updated') ||
      radarTagValue(block, 'dc:date')
    const parsed = dateRaw ? new Date(dateRaw) : null
    const publishedAt = parsed && !Number.isNaN(parsed.getTime()) ? parsed.toISOString() : null
    const excerpt = radarStripHtml(
      radarTagValue(block, 'description') ||
        radarTagValue(block, 'summary') ||
        radarTagValue(block, 'content:encoded') ||
        radarTagValue(block, 'content'),
    ).slice(0, 400)
    if (!title || !url) continue
    out.push({ title: title.slice(0, 300), url: url, publishedAt: publishedAt, excerpt: excerpt })
  }
  return out
}

async function fetchOneFeed(web, feed) {
  let signal
  try {
    signal = AbortSignal.timeout(RADAR_FETCH_TIMEOUT_MS)
  } catch (e) {
    signal = undefined
  }
  try {
    const response = await web.fetch({ url: feed.url }, signal)
    const status = response && Number(response.statusCode) >= 400 ? Number(response.statusCode) : null
    if (status) {
      return { status: 'error', note: 'HTTP ' + status, items: [] }
    }
    const content = response && response.body && response.body.content ? String(response.body.content) : ''
    const items = radarParseFeed(content)
    if (items.length === 0) {
      return { status: 'empty', note: '没有解析到条目（不是 RSS/Atom 或内容为空）', items: [] }
    }
    return { status: 'ok', note: null, items: items }
  } catch (e) {
    return { status: 'error', note: '抓取失败：' + String((e && e.message) || e).slice(0, 160), items: [] }
  }
}

/**
 * Fetch every configured feed once, append new items, and persist a per-source
 * report in `state.lastRadarFetch` so the UI can show what the last run did.
 * Returns the new snapshot (the same contract as every other mutation).
 */
async function runRadarFetch(ctx) {
  const state = loadWorkbenchState()
  const feeds = ensureArray(state.settings && state.settings.feeds).slice(0, RADAR_FETCH_TOTAL_LIMIT)
  const at = hostNowIso()

  if (feeds.length === 0) {
    return mutateWorkbenchState(function (current) {
      current.lastRadarFetch = {
        at: at,
        added: 0,
        skipped: 0,
        perFeed: [],
        note: '还没有配置资讯源：到「连接与设置 → 资讯源」添加 RSS/Atom 地址。',
      }
      auditEntry(current, 'radar.fetch', '没有配置资讯源')
      return current
    })
  }

  const web = ctx && ctx.get ? ctx.get('web') : null
  const perFeed = []
  const candidates = []
  const seenInBatch = new Set()
  const knownUrls = new Set(
    ensureArray(state.radar)
      .map(function (item) {
        return item.url ? String(item.url).toLowerCase() : null
      })
      .filter(Boolean),
  )
  // 语义近似去重：标题三元组相似度超过阈值视为同一事件（转载/微改写）
  const knownTitles = ensureArray(state.radar).map(function (item) {
    return String(item.title || '')
  })
  const SIMILARITY_THRESHOLD = 0.82

  let added = 0
  let skipped = 0

  for (const feed of feeds) {
    if (!web || typeof web.fetch !== 'function') {
      perFeed.push({
        id: feed.id,
        label: feed.label,
        status: 'unavailable',
        added: 0,
        skipped: 0,
        note: '当前 profile 未组合 web 服务，插件不会自己发起网络请求。',
      })
      continue
    }
    const result = await fetchOneFeed(web, feed)
    let feedAdded = 0
    let feedSkipped = 0
    if (result.status === 'ok') {
      for (const entry of result.items.slice(0, RADAR_FETCH_PER_FEED_LIMIT)) {
        const key = String(entry.url).toLowerCase()
        if (knownUrls.has(key) || seenInBatch.has(key)) {
          feedSkipped += 1
          continue
        }
        const similar = knownTitles.some(function (title) {
          return radarSimilarity(title, entry.title) >= SIMILARITY_THRESHOLD
        })
        if (similar) {
          feedSkipped += 1
          continue
        }
        seenInBatch.add(key)
        knownTitles.push(entry.title)
        candidates.push(
          normalizeRadarItem(
            {
              title: entry.title,
              source: feed.label,
              url: entry.url,
              publishedAt: entry.publishedAt,
              topics: feed.topics,
              summary: { change: '', usage: '', risk: '', practice: '' },
              excerpt: entry.excerpt,
            },
            null,
          ),
        )
        feedAdded += 1
        if (candidates.length >= RADAR_FETCH_TOTAL_LIMIT) break
      }
    }
    added += feedAdded
    skipped += feedSkipped
    perFeed.push({
      id: feed.id,
      label: feed.label,
      status: result.status,
      added: feedAdded,
      skipped: feedSkipped,
      note: result.note,
    })
    if (candidates.length >= RADAR_FETCH_TOTAL_LIMIT) break
  }

  return mutateWorkbenchState(function (current) {
    if (candidates.length > 0) {
      current.radar = ensureArray(current.radar).concat(candidates).slice(-500)
    }
    current.lastRadarFetch = { at: at, added: added, skipped: skipped, perFeed: perFeed, note: null }
    auditEntry(current, 'radar.fetch', '新增 ' + added + ' 条，跳过 ' + skipped + ' 条')
    return current
  })
}


/* ---------------------------------------------------------------- 联网发现 */
/*
 * 设计报告 §3.1 / TODO 06：未配置 RSS 时，用宿主已有的联网能力按关注主题
 * 发现资讯。查询词由主题确定性拼装（不调模型），原文标题/时间/摘要来自
 * 搜索结果本身；四段摘要留空，由 Agent 读原文后写回（见 workbench_update_radar）。
 */
const NEWS_QUERY_SUFFIX = ' release OR blog OR announcement'

async function discoverRadarByTopics(ctx) {
  const state = loadWorkbenchState()
  const web = ctx && ctx.get ? ctx.get('web') : null
  const topics = ensureArray(state.settings && state.settings.topics).slice(0, 3)
  const at = hostNowIso()

  if (!web || typeof web.search !== 'function') {
    return mutateWorkbenchState(function (current) {
      current.lastRadarFetch = {
        at: at,
        added: 0,
        skipped: 0,
        perFeed: [],
        note: '未配置 RSS 且当前 profile 没有 web 搜索服务：无法自动发现资讯。',
      }
      auditEntry(current, 'radar.discover', '没有可用的联网能力')
      return current
    })
  }
  if (topics.length === 0) {
    return mutateWorkbenchState(function (current) {
      current.lastRadarFetch = {
        at: at,
        added: 0,
        skipped: 0,
        perFeed: [],
        note: '没有关注主题：先到「连接与设置 → 关注主题」添加主题，才能按主题发现资讯。',
      }
      auditEntry(current, 'radar.discover', '没有关注主题')
      return current
    })
  }

  const perFeed = []
  const candidates = []
  const knownUrls = new Set(
    ensureArray(state.radar)
      .map(function (item) {
        return item.url ? String(item.url).toLowerCase() : null
      })
      .filter(Boolean),
  )
  const knownTitles = ensureArray(state.radar).map(function (item) {
    return String(item.title || '')
  })
  let added = 0
  let skipped = 0

  for (const topic of topics) {
    const query = topic + NEWS_QUERY_SUFFIX
    let result
    try {
      result = await web.search({ query: query, maxResults: 5 }, AbortSignal.timeout(12000))
    } catch (e) {
      perFeed.push({
        id: 'topic:' + topic,
        label: '话题 ' + topic,
        status: 'error',
        added: 0,
        skipped: 0,
        note: String((e && e.message) || e).slice(0, 160),
      })
      continue
    }
    let topicAdded = 0
    let topicSkipped = 0
    for (const source of (result && result.sources) || []) {
      const url = asUrl(source.url)
      if (!url) {
        topicSkipped += 1
        continue
      }
      const key = String(url).toLowerCase()
      if (knownUrls.has(key)) {
        topicSkipped += 1
        continue
      }
      const title = asString(source.title, 300) || url
      const similar = knownTitles.some(function (existing) {
        return radarSimilarity(existing, title) >= 0.82
      })
      if (similar) {
        topicSkipped += 1
        continue
      }
      knownUrls.add(key)
      knownTitles.push(title)
      const parsedPublished = asIso(source.publishedAt)
      candidates.push(
        normalizeRadarItem(
          {
            title: title,
            source: '联网检索 · ' + topic,
            url: url,
            publishedAt: parsedPublished,
            // TODO 20 日期纪律：publishedAt 可核实才标 published，否则 unknown（显示时注明抓取时间）
            dateKind: parsedPublished ? 'published' : 'unknown',
            fetchedAt: hostNowIso(),
            topics: [topic],
            summary: { change: '', usage: '', risk: '', practice: '' },
            excerpt: asString(source.snippet, 800),
          },
          null,
        ),
      )
      topicAdded += 1
    }
    added += topicAdded
    skipped += topicSkipped
    perFeed.push({
      id: 'topic:' + topic,
      label: '话题 ' + topic,
      status: topicAdded > 0 ? 'ok' : 'empty',
      added: topicAdded,
      skipped: topicSkipped,
      note: '查询词：' + query,
    })
    if (candidates.length >= RADAR_FETCH_TOTAL_LIMIT) break
  }

  return mutateWorkbenchState(function (current) {
    if (candidates.length > 0) {
      current.radar = ensureArray(current.radar).concat(candidates).slice(-500)
    }
    current.lastRadarFetch = {
      at: at,
      added: added,
      skipped: skipped,
      perFeed: perFeed,
      note:
        '按关注主题联网发现（未配置 RSS 时的默认路径）。四段摘要留空：' +
        '请让 Agent 读原文后用 workbench_update_radar 写回，保证结论可追溯。',
    }
    auditEntry(current, 'radar.discover', '联网发现新增 ' + added + ' 条')
    return current
  })
}

/** fetchRadar：优先抓取已配置的 RSS；没有配置时改走联网发现。 */
async function runRadarFetchOrDiscover(ctx) {
  const state = loadWorkbenchState()
  const feeds = ensureArray(state.settings && state.settings.feeds)
  if (feeds.length > 0) return runRadarFetch(ctx)
  return discoverRadarByTopics(ctx)
}

// ===== 37-yunzhijia.js =====
/* ============================================================================
 * dev-workbench host — 云之家 yzj-cli integration (design report §3.2, §6.3)
 *
 * The enterprise connector, at last, against the real CLI. Design report §6.3
 * demanded measured facts, not claims, so every capability listed here is
 * something this module actually exercised:
 *
 *   - `yzj-cli whoami`        → authenticated user (name, openId, token expiry)
 *   - `im message search`     → cross-group keyword search; @mentions carry
 *                               param.notifyType === 1 and param.desc[]
 *                               entries {type:'at', data:<openId>}
 *   - `doc search`            → knowledge-base title search (openWebUrl may be
 *                               null; never fabricate a link)
 *
 * Permission ladder (§7.1): everything here is L1 authorized read-only. The
 * allowlist below is checked BEFORE spawn and admits only read commands;
 * send / recall / write / delete / approve / grant are structurally absent —
 * those stay in agent sessions behind per-action approval, never in a plugin
 * background call. The CLI's own exit-10 confirmation gate backs this up.
 *
 * The binary is resolved through ctx.subprocess.resolveExecutable when the
 * provider can see it, with an nvm-path fallback because GUI-launched hosts
 * often lack shell-profile PATH entries.
 * ========================================================================== */

const YZJ_TIMEOUT_MS = 15000
const YZJ_MAX_BYTES = 512 * 1024
const MENTIONS_FETCH_LIMIT = 80

/** Read-only command prefixes; anything else is refused before spawn. */
const YZJ_READ_ONLY = [
  'whoami',
  'im group recent',
  'im group search',
  'im group.members list',
  'im message list',
  'im message search',
  'contact user search',
  'contact user get',
  'contact dept get',
  'approval flow list',
  'approval flow get',
  'calendar event list',
  'calendar event get',
  'calendar event participants',
  'calendar room find',
  'doc workspace list',
  'doc workspace get',
  'doc list',
  'doc get',
  'doc recent',
  'doc search',
  'doc block list',
  'doc download',
  'sheet get',
  'sheet table get',
  'sheet record list',
  'attendance record list',
]

let yzjPathCache = undefined

function yzjCommandAllowed(argv) {
  if (!Array.isArray(argv) || argv.length < 1) return false
  const parts = argv.map(String)
  // Drop a leading binary name if present: callers pass either the bare
  // subcommand argv ('whoami') or the full argv including the resolved path.
  if (parts.length > 1 && /yzj-cli$/i.test(parts[0])) parts.shift()
  const candidate = parts.join(' ')
  if (candidate.length === 0) return false
  return YZJ_READ_ONLY.some(function (prefix) {
    return candidate === prefix || candidate.startsWith(prefix + ' ')
  })
}

async function resolveYzjPath(ctx) {
  if (yzjPathCache !== undefined) return yzjPathCache
  const subprocess = ctx && ctx.get ? ctx.get('subprocess') : null
  if (subprocess && typeof subprocess.resolveExecutable === 'function') {
    let signal
    try {
      signal = AbortSignal.timeout(2500)
    } catch (e) {
      signal = undefined
    }
    try {
      const resolved = await subprocess.resolveExecutable('yzj-cli', undefined, signal)
      if (typeof resolved === 'string' && resolved.length > 0) {
        yzjPathCache = resolved
        return resolved
      }
    } catch (e) {
      /* fall through to the filesystem scan */
    }
  }
  // Filesystem scan ONLY when no subprocess provider exists AND the host
  // process itself shows an nvm-style environment; a scan that silently
  // executes a discovered binary is a real capability gain, so it must be
  // observable (the connector row reports the resolved path). The scan is
  // skipped entirely when a provider is present but resolution failed — that
  // provider owns the truth about its execution world.
  const home = homedir()
  const nvmDir = process.env.NVM_DIR || join(home, '.nvm')
  const candidates = [
    join(nvmDir, 'versions', 'node'),
    '/usr/local/bin',
    join(home, '.local', 'bin'),
    join(home, '.cargo', 'bin'),
    join(home, 'bin'),
  ]
  const sawProvider = !!subprocess
  for (const dir of candidates) {
    const direct = join(dir, 'yzj-cli')
    if (existsSync(direct)) {
      // A provider that failed to resolve while the file exists is suspicious;
      // trust the provider only when it did resolve. Otherwise fall back.
      if (sawProvider) continue
      yzjPathCache = direct
      return direct
    }
    try {
      const versions = readdirSync(dir)
      for (const version of versions) {
        const nested = join(dir, version, 'bin', 'yzj-cli')
        if (existsSync(nested)) {
          if (sawProvider) continue
          yzjPathCache = nested
          return nested
        }
      }
    } catch (e) {
      /* not an nvm directory */
    }
  }
  // Misses are NOT cached: a yzj-cli installed later (or a subprocess provider
  // appearing in a later test pass) must be picked up without a restart, and a
  // failed probe is cheap compared to a stale "unconfigured" verdict.
  return null
}

/** Invalidate the resolved-binary cache (used by tests and manual reprobe). */
function invalidateYzjPathCache() {
  yzjPathCache = undefined
}

/**
 * Run one read-only yzj-cli command and parse its JSON envelope.
 * Never throws: every failure is data, so callers degrade instead of break.
 */
async function runYzj(ctx, args) {
  if (!yzjCommandAllowed(['yzj-cli'].concat(args))) {
    return { status: 'refused', note: '命令不在云之家只读 allowlist 内：yzj-cli ' + args.join(' ') }
  }
  const path = await resolveYzjPath(ctx)
  if (!path) {
    return { status: 'unavailable', note: '未找到 yzj-cli（PATH 与常见安装位置都没有）' }
  }
  const subprocess = ctx && ctx.get ? ctx.get('subprocess') : null
  if (!subprocess || typeof subprocess.spawn !== 'function') {
    return { status: 'unavailable', note: '当前 profile 未组合 subprocess 服务' }
  }
  let signal
  try {
    signal = AbortSignal.timeout(YZJ_TIMEOUT_MS)
  } catch (e) {
    signal = undefined
  }
  let handle
  try {
    handle = subprocess.spawn({
      argv: [path].concat(args.map(String)),
      cwd: homedir(),
      stdio: {
        stdin: 'ignore',
        stdout: { maxBytes: YZJ_MAX_BYTES },
        stderr: { maxBytes: 16 * 1024 },
      },
      graceMs: 2500,
      signal: signal,
    })
  } catch (e) {
    return { status: 'error', note: '无法启动 yzj-cli：' + String((e && e.message) || e) }
  }
  try {
    const outcome = await handle.done
    const read = function (reader) {
      if (!reader || typeof reader.readFrom !== 'function') return ''
      try {
        return String(reader.readFrom(0).text || '')
      } catch (e) {
        return ''
      }
    }
    const stdout = read(handle.collected && handle.collected.stdout)
    const stderr = read(handle.collected && handle.collected.stderr)
    if (outcome && outcome.exitCode !== 0) {
      return {
        status: 'error',
        exitCode: outcome.exitCode,
        note: (stderr.trim() || stdout.trim() || '退出码 ' + outcome.exitCode).slice(0, 300),
      }
    }
    let json = null
    try {
      json = JSON.parse(stdout)
    } catch (e) {
      json = null
    }
    if (!json || typeof json !== 'object') {
      return { status: 'error', exitCode: 0, note: 'yzj-cli 输出不是 JSON（可能要求重新登录）' }
    }
    if (json.success !== true) {
      const errorCode = json.errorCode || (json.error && json.error.errorCode)
      return {
        status: 'unauthorized',
        note: '云之家返回失败' + (errorCode ? '（errorCode ' + errorCode + '，可能需要重新 auth login）' : ''),
        json: json,
      }
    }
    return { status: 'ok', json: json }
  } catch (e) {
    return { status: 'error', note: String((e && e.message) || e).slice(0, 300) }
  }
}

/** Who is logged in, and is the token usable. Cached briefly per call site. */
async function probeYunzhijia(ctx) {
  const result = await runYzj(ctx, ['whoami'])
  if (result.status === 'unavailable') {
    return { state: 'unconfigured', note: result.note, name: null, openId: null, expiresAt: null }
  }
  if (result.status === 'refused' || result.status === 'error') {
    return { state: 'error', note: result.note || 'whoami 执行失败', name: null, openId: null, expiresAt: null }
  }
  if (result.status === 'unauthorized') {
    return { state: 'unauthorized', note: result.note, name: null, openId: null, expiresAt: null }
  }
  const data = result.json && result.json.data
  if (!data || typeof data.openId !== 'string') {
    return { state: 'error', note: 'whoami 返回缺少 openId', name: null, openId: null, expiresAt: null }
  }
  return {
    state: 'ok',
    note: null,
    name: asString(data.name, 80) || null,
    openId: data.openId,
    expiresAt: asIso(data.expiresAt) || null,
  }
}

/* ------------------------------------------------------------- @mentions */

function yzjMentionTargetsMe(message, myOpenId) {
  if (!message || typeof message !== 'object') return false
  const param = message.param
  if (param && typeof param === 'object') {
    if (param.notifyType === 1) return true
    if (Array.isArray(param.desc)) {
      for (const entry of param.desc) {
        if (entry && typeof entry === 'object' && entry.type === 'at' && entry.data === myOpenId) return true
      }
    }
  }
  return false
}

/** 批量解析 openId → 姓名（一次 CLI 调用，最多 6 个）。 */
async function resolveSenderNames(ctx, openIds) {
  const unique = Array.from(
    new Set(
      (openIds || []).filter(function (id) {
        return typeof id === 'string' && id.length > 0
      }),
    ),
  ).slice(0, 6)
  if (unique.length === 0) return new Map()
  const args = ['contact', 'user', 'get']
  unique.forEach(function (id) {
    args.push('--open-id', id)
  })
  const result = await runYzj(ctx, args)
  const map = new Map()
  if (result.status !== 'ok' || !result.json || !result.json.data) return map
  const list = Array.isArray(result.json.data.list) ? result.json.data.list : [result.json.data]
  list.forEach(function (user) {
    if (user && typeof user.openId === 'string') {
      map.set(user.openId, asString(user.name || user.userName, 80) || null)
    }
  })
  return map
}

function yzjParseMentionSearch(json, myOpenId) {
  const out = []
  const groups = json && json.data && Array.isArray(json.data.list) ? json.data.list : []
  for (const group of groups) {
    const groupName = asString(group && group.group && group.group.groupName, 120) || '未知会话'
    const groupId = asString(group && group.group && group.group.groupId, 60) || null
    const messages = group && Array.isArray(group.messages) ? group.messages : []
    for (const wrapper of messages) {
      const message = wrapper && wrapper.message ? wrapper.message : wrapper
      if (!message || typeof message !== 'object') continue
      if (!yzjMentionTargetsMe(message, myOpenId)) continue
      if (message.fromOpenId === myOpenId) continue
      out.push({
        msgId: asString(message.msgId, 60),
        groupId: groupId,
        groupName: groupName,
        content: asString(message.content, 2000),
        fromOpenId: asString(message.fromOpenId, 60) || null,
        sendTime: asIso(message.sendTime) || null,
      })
    }
  }
  return out
}

/**
 * 增量游标同步（TODO 05）：
 *   1. im group recent 取最近会话；
 *   2. 每个群用 cursor.lastMsgId 拉「新消息」（--type new），没有游标时取最新一页；
 *   3. 用 param.notifyType / desc[].type==='at' 判定「有人在群里 @我」——
 *      这条判据不依赖显示名，因此**昵称 @ 也能覆盖**（关键词检索会漏）；
 *   4. 把每群最新 msgId 存回游标，下次只取增量。
 * 返回 null 表示这条路不可用，调用方回退到关键词检索。
 */
async function fetchMentionsIncremental(ctx, probe, cursors) {
  // 会话发现翻页：直到取回不足一页（支持 >12 个最近会话，TODO 13）
  const groups = []
  for (let pageIndex = 1; pageIndex <= 6; pageIndex += 1) {
    const listed = await runYzj(ctx, ['im', 'group', 'recent', '--limit', '12', '--page', String(pageIndex)])
    if (listed.status !== 'ok') {
      // 会话页失败：已拿到的会话继续处理，失败如实记录（单群仍可各自补采）
      groups.push({ __error: { status: listed.status, note: listed.note } })
      break
    }
    const batch = listed.json && listed.json.data && Array.isArray(listed.json.data.list) ? listed.json.data.list : []
    for (const group of batch) {
      if (group && group.groupId && !groups.some(function (row) { return row.groupId === group.groupId })) groups.push(group)
    }
    if (batch.length < 12) break
  }
  const pageErrors = groups.filter(function (row) { return row && row.__error }).map(function (row) { return row.__error })
  const usableGroups = groups.filter(function (row) { return row && row.groupId })
  if (groups.length === 0) return null

  const mentions = []
  const nextCursors = Object.assign({}, cursors || {})
  const pageFailures = []
  let scannedGroups = 0
  let scannedMessages = 0

  // TODO 13：不再有「前 10 个会话」的旧硬上限——翻页拿到的会话全部处理，上限放宽到 40
  // （每群的排空翻页与单群失败保护独立生效，尽量在单次同步内覆盖真实活跃群）
  for (const group of groups.slice(0, 40)) {
    const groupId = asString(group && group.groupId, 80)
    const groupName = asString(group && group.groupName, 120) || '未知会话'
    if (!groupId) continue
    // 排空翻页（TODO 13，真实 CLI 语义验证）：
    //   第一页 --type newest（最新 20 条，时间升序 list[0] 最旧、list[last] 最新）
    //   翻页 --type old --msg-id <本页最旧 list[0]>（往前翻历史）
    //   游标只推进「该群已见过的最新一条」 = list[last]，且仅当该群所有页都成功
    const cursor = nextCursors[groupId]
    const fetched = []
    let drainPage = 0
    let drainAnchor = null
    let failedPage = null
    while (drainPage < 6) {
      const args = ['im', 'message', 'list', '--group-id', groupId, '--limit', '20']
      if (drainPage === 0) {
        args.push('--type', 'newest')
      } else {
        args.push('--type', 'old', '--msg-id', drainAnchor)
      }
      const listed = await runYzj(ctx, args)
      if (listed.status !== 'ok') {
        failedPage = { group: groupId, at: drainAnchor || null, status: listed.status, note: listed.note }
        break
      }
      const rows = listed.json && listed.json.data && Array.isArray(listed.json.data.list) ? listed.json.data.list : []
      // 遇到上次已见的游标（该消息已采集过）→ 停止向更旧展开
      if (cursor && cursor.lastMsgId && rows.some(function (row) {
        const inner = row && row.message ? row.message : row
        return String((inner && inner.msgId) || '') === String(cursor.lastMsgId)
      })) break
      scannedMessages += rows.length
      fetched.push.apply(fetched, rows)
      if (rows.length > 0) {
        const oldestRow = rows[0]
        const inner = oldestRow && oldestRow.message ? oldestRow.message : oldestRow
        drainAnchor = asString((inner && inner.msgId) || '', 60) || null
      }
      if (rows.length < 20) break
      drainPage += 1
    }
    scannedGroups += 1
    for (const wrapper of fetched) {
      const message = wrapper && wrapper.message ? wrapper.message : wrapper
      if (!message || typeof message !== 'object') continue
      if (!yzjMentionTargetsMe(message, probe.openId)) continue
      if (message.fromOpenId === probe.openId) continue
      mentions.push({
        msgId: asString(message.msgId, 60),
        groupId: groupId,
        groupName: groupName,
        content: asString(message.content, 2000),
        fromOpenId: asString(message.fromOpenId, 60) || null,
        sendTime: asIso(message.sendTime) || null,
      })
    }
    const drained = fetched.length > 0
    if (drained) {
      // 升序列表：list[last] 才是本群最新一条
      const newestInner = fetched[fetched.length - 1]
      const inner = newestInner && newestInner.message ? newestInner.message : newestInner
      if (inner && inner.msgId) {
        nextCursors[groupId] = {
          lastMsgId: asString(inner.msgId, 60),
          lastSendTime: asIso(inner.sendTime) || null,
          groupName: groupName,
          at: hostNowIso(),
        }
      }
    }
    if (failedPage) {
      // 单群失败：不推进游标（保留补采位），错误只进报告
      pageFailures.push(failedPage)
    }
  }
  return {
    mentions: mentions,
    cursors: nextCursors,
    scannedGroups: scannedGroups,
    scannedMessages: scannedMessages,
    pageFailures: pageFailures,
    sessionPageErrors: pageErrors,
  }
}

/**
 * Design report §3.2: pull @-mention messages as source evidence. Deterministic
 * part only — creating tasks with AI-extracted fields stays an agent job.
 * Keyword search matches "@<display name>"; a custom remark name would be
 * missed, and the persisted report says so honestly.
 */
async function fetchYunzhijiaMentionsInto(ctx, state) {
  const probe = await probeYunzhijia(ctx)
  const at = hostNowIso()
  if (probe.state !== 'ok') {
    state.lastMentionsFetch = {
      at: at,
      status: probe.state,
      found: 0,
      added: 0,
      note: probe.note || '云之家不可用',
    }
    auditEntry(state, 'mentions.fetch', '云之家不可用：' + (probe.note || probe.state))
    return state
  }

  // 优先走增量游标（可覆盖昵称 @）；不可用时回退关键词检索
  const incrementalResult = await fetchMentionsIncremental(ctx, probe, state.syncCursors)
  const incremental = incrementalResult && incrementalResult.error ? null : incrementalResult
  const incrementalError = incrementalResult && incrementalResult.error ? incrementalResult.error : null
  let keywords = ['@' + probe.name].concat(
    ensureArray(state.settings && state.settings.mentionKeywords).map(function (word) {
      return String(word).indexOf('@') === 0 ? String(word) : '@' + String(word)
    }),
  )
  const keywordMentions = []
  let searchFailure = incrementalError
  if (!incremental) {
    for (const keyword of keywords.slice(0, 3)) {
      const searched = await runYzj(ctx, ['im', 'message', 'search', '--keyword', keyword])
      if (searched.status !== 'ok') {
        // 如实记录失败：不要把「接口不可用」当成「没有 @我」
        if (!searchFailure) searchFailure = { status: searched.status, note: searched.note }
        continue
      }
      for (const mention of yzjParseMentionSearch(searched.json, probe.openId)) keywordMentions.push(mention)
    }
  }
  if (!incremental && keywordMentions.length === 0 && searchFailure) {
    state.lastMentionsFetch = {
      at: at,
      status: searchFailure.status === 'refused' ? 'error' : searchFailure.status,
      found: 0,
      added: 0,
      note: '消息接口不可用：' + (searchFailure.note || searchFailure.status),
    }
    auditEntry(state, 'mentions.fetch', '消息接口不可用：' + (searchFailure.note || searchFailure.status))
    return state
  }
  const rawMentions = incremental
    ? incremental.mentions
    : keywordMentions
  if (incremental && incremental.cursors) {
    state.syncCursors = incremental.cursors
  }

  const mentions = rawMentions
    .filter(function (mention) {
      return !!mention.msgId
    })
    .slice(0, MENTIONS_FETCH_LIMIT)

  // 发送人姓名：一次批量查询，失败不影响主流程（回退为 openId 短标识）
  const senderNames = await resolveSenderNames(
    ctx,
    mentions.map(function (mention) {
      return mention.fromOpenId
    }),
  )
  const existing = new Set(
    ensureArray(state.sources)
      .filter(function (row) {
        return row.provider === 'yunzhijia'
      })
      .map(function (row) {
        return row.externalId
      }),
  )
  let added = 0
  for (const mention of mentions) {
    const externalId = 'yzj:msg:' + mention.msgId
    if (existing.has(externalId)) continue
    existing.add(externalId)
    const createdSource = normalizeSource({
      provider: 'yunzhijia',
      externalId: externalId,
      url: null,
      title: '@我 · ' + mention.groupName,
      excerpt: mention.content,
      fetchedAt: mention.sendTime || at,
      sender:
        (mention.fromOpenId && senderNames.get(mention.fromOpenId)) ||
        (mention.fromOpenId ? mention.fromOpenId.slice(0, 8) + '…' : null),
      locator: {
        groupId: mention.groupId,
        msgId: mention.msgId,
        groupName: mention.groupName,
      },
    })
    state.sources = ensureArray(state.sources).concat([createdSource])
    added += 1
    // TODO 14：新来源进入分析队列（AI 识别）；采集游标照常推进，互不阻塞
    if (!ensureArray(state.analysisQueue).some(function (row) { return row.sourceId === createdSource.id })) {
      state.analysisQueue = ensureArray(state.analysisQueue).concat([
        {
          id: newId('aq'),
          sourceId: createdSource.id,
          msgId: mention.msgId,
          groupId: mention.groupId,
          status: 'pending',
          attempts: 0,
          at: hostNowIso(),
        },
      ]).slice(-300)
    }
  }

  const mode = incremental
    ? '增量排空（最近 ' +
      incremental.scannedGroups +
      ' 个群 / ' +
      incremental.scannedMessages +
      ' 条新消息，notifyType 判据可覆盖昵称 @' +
      (incremental.pageFailures && incremental.pageFailures.length
        ? '；' + incremental.pageFailures.length + ' 个群待补采'
        : '') +
      (incremental.sessionPageErrors && incremental.sessionPageErrors.length
        ? '；会话翻页失败 ' + incremental.sessionPageErrors.length
        : '') +
      '）'
    : '关键词检索（' + keywords.slice(0, 3).join(' / ') + '）'
  const failureNote = incremental
    ? [
        incremental.pageFailures && incremental.pageFailures.length
          ? '失败保留补采位：' + incremental.pageFailures.map(function (row) { return String(row.group).slice(0, 6) + '…(' + (row.note || row.status) + ')' }).slice(0, 4).join('、')
          : null,
        incremental.sessionPageErrors && incremental.sessionPageErrors.length
          ? '会话翻页失败：' + incremental.sessionPageErrors[0].note
          : null,
      ]
        .filter(Boolean)
        .join('；')
    : null
  state.lastMentionsFetch = {
    at: at,
    status: 'ok',
    found: mentions.length,
    added: added,
    user: probe.name,
    mode: incremental ? 'incremental' : 'keyword',
    status: incremental && failureNote ? 'partial' : 'ok',
    note:
      mode +
      (probe.expiresAt ? '；token 至 ' + probe.expiresAt.slice(0, 16).replace('T', ' ') + ' 有效' : '') +
      (failureNote ? '。' + failureNote : '') +
      (incremental ? '。' : '。昵称 @ 可能漏采，可在「连接与设置」补充关键词。'),
  }
  auditEntry(state, 'mentions.fetch', '发现 ' + mentions.length + ' 条 @我，新增来源 ' + added + ' 条（' + (incremental ? '增量' : '关键词') + '）')
  return state
}

/* ------------------------------------------------------- enterprise search */

/** The 企业（云之家） search group — real results when yzj-cli is usable. */
async function searchEnterpriseGroup(ctx, query) {
  const probe = await probeYunzhijia(ctx)
  if (probe.state !== 'ok') {
    return {
      id: 'enterprise',
      label: '企业（云之家）',
      status: 'unavailable',
      items: [],
      note: probe.note || '云之家 CLI 不可用：' + probe.state,
    }
  }

  const items = []

  const messageResult = await runYzj(ctx, ['im', 'message', 'search', '--keyword', query])
  if (messageResult.status === 'ok') {
    const groups = messageResult.json && messageResult.json.data && messageResult.json.data.list
    if (Array.isArray(groups)) {
      for (const group of groups) {
        const groupName = asString(group && group.group && group.group.groupName, 120) || '未知会话'
        const messages = group && Array.isArray(group.messages) ? group.messages : []
        for (const wrapper of messages.slice(0, 3)) {
          const message = wrapper && wrapper.message ? wrapper.message : wrapper
          if (!message || typeof message !== 'object') continue
          items.push({
            id: 'yzj-msg-' + asString(message.msgId, 60),
            title: asString(message.content, 120) || '(空消息)',
            snippet: asString(message.content, 400),
            url: null,
            kind: 'source',
            extra: { provider: 'yunzhijia', at: asIso(message.sendTime), group: groupName },
          })
        }
      }
    }
  }

  const docResult = await runYzj(ctx, ['doc', 'search', '--keyword', query])
  if (docResult.status === 'ok') {
    const docs = docResult.json && docResult.json.data && docResult.json.data.list
    if (Array.isArray(docs)) {
      for (const doc of docs.slice(0, 5)) {
        if (!doc || typeof doc !== 'object') continue
        items.push({
          id: 'yzj-doc-' + asString(doc.id, 60),
          title: asString(doc.fileName || doc.title, 200) || '未命名文档',
          snippet: [asString(doc.kbName, 80), asString(doc.creatorName, 40) + ' 创建']
            .filter(Boolean)
            .join(' · '),
          url: asUrl(doc.openWebUrl),
          kind: 'knowledge',
          extra: { provider: 'yunzhijia', at: asIso(doc.updateTime || doc.createTime), group: asString(doc.kbName, 80) },
        })
      }
    }
  }

  const imFailed = messageResult.status !== 'ok'
  const docFailed = docResult.status !== 'ok'
  const status = items.length > 0 ? 'ok' : imFailed && docFailed ? 'error' : 'empty'
  const notes = []
  if (imFailed) notes.push('消息一路失败：' + (messageResult.note || messageResult.status))
  if (docFailed) notes.push('文档一路失败：' + (docResult.note || docResult.status))
  return {
    id: 'enterprise',
    label: '企业（云之家）',
    status: status,
    items: items.slice(0, SEARCH_GROUP_LIMIT),
    note: notes.length > 0 ? notes.join('；') : '来自云之家消息与知识库；文档链接以 openWebUrl 为准，为空时不构造地址。',
  }
}


/* --------------------------------------------------- §3.3 其余企业 Provider */

/**
 * 联系人：只在「像人名的查询」或明确的找人意图下触发，避免每次搜索都多打
 * 一次企业通讯录（也对隐私更克制）。
 */
async function searchContactsGroup(ctx, query) {
  const looksLikeName = /^[\u4e00-\u9fa5]{2,4}$/.test(query)
  const explicitIntent = /找人|联系|同事|部门|谁是|联系人|通讯录/.test(query)
  if (!looksLikeName && !explicitIntent) return null

  const result = await runYzj(ctx, ['contact', 'user', 'search', '--keyword', query])
  if (result.status !== 'ok') {
    return {
      id: 'contacts',
      label: '企业联系人',
      status: 'error',
      items: [],
      note: '通讯录查询失败：' + (result.note || result.status),
    }
  }
  const list = (result.json && result.json.data && Array.isArray(result.json.data.list) ? result.json.data.list : []).slice(0, 6)
  const items = list.map(function (user) {
    if (!user || typeof user !== 'object') return null
    const name = asString(user.name || user.userName, 80)
    if (!name) return null
    return {
      id: 'yzj-user-' + (asString(user.openId, 80) || name),
      title: name,
      snippet: [asString(user.department || user.orgName, 80), asString(user.jobTitle, 60)]
        .filter(Boolean)
        .join(' · '),
      url: null,
      kind: 'contact',
      extra: { openId: asString(user.openId, 80), department: asString(user.department || user.orgName, 80) },
    }
  }).filter(Boolean)
  if (items.length === 0) return null
  return {
    id: 'contacts',
    label: '企业联系人',
    status: 'ok',
    items: items,
    note: '按姓名/关键词匹配企业通讯录，仅返回展示所需字段（姓名、部门、职位）。',
  }
}

/** 会议室：只在会议/场地类查询下触发，按当天可用会议室过滤名称。 */
async function searchRoomsGroup(ctx, query) {
  if (!/会议室|会议|场地|room|预定|有空/.test(query)) return null

  const today = new Date()
  const pad = function (value) {
    return value < 10 ? '0' + value : String(value)
  }
  const day = today.getFullYear() + '-' + pad(today.getMonth() + 1) + '-' + pad(today.getDate())
  const result = await runYzj(ctx, ['calendar', 'room', 'find', '--start', day, '--end', day])
  if (result.status !== 'ok') {
    return {
      id: 'rooms',
      label: '会议室',
      status: 'error',
      items: [],
      note: '会议室查询失败：' + (result.note || result.status),
    }
  }
  const rooms = result.json && result.json.data && Array.isArray(result.json.data.list) ? result.json.data.list : []
  const needle = String(query)
    .replace(/会议室|会议|场地|room|预定|有空/g, '')
    .trim()
  const matched = rooms.filter(function (room) {
    if (!room || typeof room.roomName !== 'string') return false
    return needle.length === 0 ? true : room.roomName.indexOf(needle) >= 0
  }).slice(0, 8)
  const items = matched.map(function (room) {
    return {
      id: 'yzj-room-' + (asString(room.roomId, 80) || room.roomName),
      title: asString(room.roomName, 120),
      snippet: [asString(room.roomDetail, 80), room.limitCount ? '可容纳 ' + room.limitCount + ' 人' : '']
        .filter(Boolean)
        .join(' · '),
      url: null,
      kind: 'room',
      extra: { roomId: asString(room.roomId, 80), at: null },
    }
  })
  if (items.length === 0) return null
  return {
    id: 'rooms',
    label: '会议室',
    status: 'ok',
    items: items,
    note: '查的是今天可预约的会议室（calendar room find）；会议室预订属于写操作，不在插件内。',
  }
}

/** 考勤：只在考勤意图下触发，只返回本人打卡流水。 */
async function searchAttendanceGroup(ctx, query) {
  if (!/打卡|考勤|出勤|clock|迟到|早退/.test(query)) return null

  const result = await runYzj(ctx, ['attendance', 'record', 'list'])
  if (result.status !== 'ok') {
    return {
      id: 'attendance',
      label: '考勤',
      status: 'error',
      items: [],
      note: '考勤查询失败：' + (result.note || result.status),
    }
  }
  const list = (result.json && result.json.data && Array.isArray(result.json.data.list) ? result.json.data.list : []).slice(0, 6)
  const items = list.map(function (record, index) {
    if (!record || typeof record !== 'object') return null
    const stamp = Number(record.clockInTime || record.clockTime)
    const at = Number.isFinite(stamp) && stamp > 0 ? new Date(stamp).toISOString() : null
    return {
      id: 'yzj-att-' + index,
      title: (record.clockInType ? record.clockInType + '·' : '') + (record.clockInStatus || '打卡记录'),
      snippet: [asString(record.clockInPosition, 80), at ? new Date(stamp).toLocaleString('zh-CN') : '']
        .filter(Boolean)
        .join(' · '),
      url: null,
      kind: 'attendance',
      extra: { at: at },
    }
  }).filter(Boolean)
  if (items.length === 0) return null
  return {
    id: 'attendance',
    label: '考勤',
    status: 'ok',
    items: items,
    note: '只查询本人当日打卡流水（attendance record list 的能力边界）。',
  }
}


/** 日程与会议（§3.5）：只在日程类意图下触发，查今天到未来 3 天。 */
async function searchEventsGroup(ctx, query) {
  if (!/日程|会议|开会|calendar|安排|纪要/.test(query)) return null
  const pad = function (value) {
    return value < 10 ? '0' + value : String(value)
  }
  const day = function (offset) {
    const date = new Date()
    date.setDate(date.getDate() + offset)
    return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate())
  }
  const result = await runYzj(ctx, ['calendar', 'event', 'list', '--start', day(0), '--end', day(3)])
  if (result.status !== 'ok') {
    return { id: 'events', label: '日程与会议', status: 'error', items: [], note: '日程查询失败：' + (result.note || result.status) }
  }
  const list = result.json && result.json.data && Array.isArray(result.json.data.list) ? result.json.data.list : []
  const needle = String(query).replace(/日程|会议|开会|calendar|安排|纪要/g, '').trim()
  const matched = list.filter(function (event) {
    if (!event || typeof event !== 'object') return false
    const title = asString(event.title || event.subject, 160)
    if (needle.length === 0) return true
    return title.indexOf(needle) >= 0
  }).slice(0, 8)
  const items = matched.map(function (event) {
    const start = event.startTime || event.start || event.beginTime
    const at = typeof start === 'number' ? new Date(start).toISOString() : asIso(start)
    return {
      id: 'yzj-event-' + (asString(event.id || event.eventId, 80) || String(Math.random()).slice(2, 8)),
      title: asString(event.title || event.subject, 160) || '未命名日程',
      snippet: [
        at ? new Date(at).toLocaleString('zh-CN') : '',
        asString(event.location || event.roomName, 80),
        asString(event.organizer || event.creatorName, 40),
      ]
        .filter(Boolean)
        .join(' · '),
      url: null,
      kind: 'event',
      extra: { at: at },
    }
  })
  if (items.length === 0) return null
  return {
    id: 'events',
    label: '日程与会议',
    status: 'ok',
    items: items,
    note: '查的是今天起 3 天内的日程（calendar event list）；创建/取消日程属于写操作，不在插件内。',
  }
}

// ===== 38-candidates.js =====
/* ============================================================================
 * dev-workbench host — 任务候选规则提取（设计报告 §3.2 AI 任务提取 / §8）
 *
 * 报告要的是「规则候选 → LLM 提取 → 结构校验 → 人工确认」。插件内没有模型，
 * 所以这一层只做**确定性规则候选**：行动词、时间线索、长度与指向性给出一个
 * 可解释的置信度，并把命中的规则逐条写进 reasons。低置信度同样进待确认区，
 * 由用户决定采纳或忽略——不自动建任务，也不假装这是 LLM 的结论。
 *
 * 每条候选都绑定 sourceRefId，采纳后任务仍可回溯到原消息（来源证据）。
 * ========================================================================== */

const CANDIDATE_ACTION_WORDS = [
  '请',
  '麻烦',
  '帮忙',
  '帮看',
  '看下',
  '看一下',
  '确认',
  '跟进',
  '处理',
  '提供',
  '安排',
  '给出',
  '回复',
  '支持',
  '排查',
  '修复',
  '评审',
  '同步',
  '整理',
  '输出',
  '评估',
  '补充',
  '对齐',
  '落地',
]

/** 以基准时间（原消息时间）算偏移天数的 18:00。 */
function candidateStartOfDay(base, offsetDays) {
  const date = new Date(base.getTime())
  date.setDate(date.getDate() + (offsetDays || 0))
  date.setHours(18, 0, 0, 0)
  return date
}

function candidateEndOfMonth(base) {
  const date = new Date(base.getTime())
  date.setMonth(date.getMonth() + 1, 0)
  date.setHours(18, 0, 0, 0)
  return date
}

/** 基准时间之后的第 N 个周 X（周一=1），18:00。 */
function candidateNextWeekday(base, target) {
  const date = new Date(base.getTime())
  const current = date.getDay() === 0 ? 7 : date.getDay()
  let delta = target - current
  if (delta <= 0) delta += 7
  date.setDate(date.getDate() + delta)
  date.setHours(18, 0, 0, 0)
  return date
}

/** 下周同一工作日（下周一 + target-1 天），18:00。 */
function candidateNextWeek(base, target) {
  const date = new Date(base.getTime())
  const current = date.getDay() === 0 ? 7 : date.getDay()
  let delta = 8 - current
  if (delta <= 0) delta += 7
  date.setDate(date.getDate() + delta + ((target || 5) - 1))
  date.setHours(18, 0, 0, 0)
  return date
}

/**
 * 时间线索 → ISO。只映射**明确表达**的日期；「尽快」「尽早」不算日期，
 * 只记一条 reason（不编造截止时间）。
 */
function candidateDueFromText(text, baseTime) {
  const source = String(text || '')
  const base = baseTime instanceof Date && !Number.isNaN(baseTime.getTime()) ? baseTime : new Date()
  const hits = []
  const put = function (label, date) {
    hits.push(label + ' → ' + date.toISOString().slice(0, 16).replace('T', ' '))
    return date.toISOString()
  }
  // 顺序很重要：「明天下班前」应先命中「明天」，不能被「下班前」抢走
  if (/后天/.test(source)) return { dueAt: put('后天', candidateStartOfDay(base, 2)), hits: hits }
  if (/明天|明日/.test(source)) return { dueAt: put('明天', candidateStartOfDay(base, 1)), hits: hits }
  const nextWeek = /下周([一二三四五六日天])?/.exec(source)
  if (nextWeek) {
    const map = { 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 日: 7, 天: 7 }
    const target = nextWeek[1] ? map[nextWeek[1]] : 5
    return { dueAt: put('下周' + (nextWeek[1] || '五'), candidateNextWeek(base, target)), hits: hits }
  }
  const weekday = /周([一二三四五六日天])/.exec(source)
  if (weekday) {
    const map = { 一: 1, 二: 2, 三: 3, 四: 4, 五: 5, 六: 6, 日: 7, 天: 7 }
    const target = map[weekday[1]]
    if (target) return { dueAt: put('周' + weekday[1], candidateNextWeekday(base, target)), hits: hits }
  }
  if (/本周|这周|周内/.test(source)) return { dueAt: put('本周内', candidateNextWeekday(base, 5)), hits: hits }
  if (/月底|本月末/.test(source)) return { dueAt: put('月底', candidateEndOfMonth(base)), hits: hits }
  if (/今天|今日|下班前/.test(source)) return { dueAt: put('今天/下班前', candidateStartOfDay(base, 0)), hits: hits }
  if (/尽快|尽早|越快越好/.test(source)) {
    return { dueAt: null, hits: ['提到「尽快」但没有明确日期，未编造截止时间'] }
  }
  return { dueAt: null, hits: [] }
}

/** 从消息正文里切出一句可读的任务标题。 */
/**
 * 取消、已完成与否定表达：这类消息不该生成待办候选。
 * 只匹配明确的收尾语义，避免把「请确认是否取消」误判为取消。
 */
const CANDIDATE_CLOSED_PATTERNS = [
  /已(?:经)?(?:解决|修复|完成|处理完|上线|发布|关闭|搞定)/,
  /不用(?:再)?(?:处理|管|跟进|看了?)/,
  /无需(?:处理|跟进)/,
  /不必(?:处理|跟进)/,
  /(?:问题|这个|此事)(?:已)?(?:解决|关闭|完结)/,
  /取消(?:该|这个|此)?(?:任务|事项|需求)/,
  /作废/,
  /(?:搞定了|已搞定|OK ?了|ok ?了)/,
]

function candidateIsClosed(text) {
  const source = String(text || '')
  // 「请确认是否取消」这类是询问，不是取消本身
  if (/是否|需不需要|要不要|吗\?|吗？/.test(source) && /取消|关闭|作废/.test(source)) return false
  return CANDIDATE_CLOSED_PATTERNS.some(function (pattern) {
    return pattern.test(source)
  })
}

function candidateTitleFromText(text) {
  const source = String(text || '')
    .replace(/@\S+\s*/g, '')
    .replace(/\[图片\]|\[文件\]|\[链接\]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  if (!source) return ''
  const sentence = source.split(/[。!?！？\n]/).map(function (part) {
    return part.trim()
  }).filter(Boolean)[0]
  const picked = sentence || source
  return picked.length > 60 ? picked.slice(0, 58) + '…' : picked
}

/**
 * 对一条来源做规则提取。返回候选草稿或 null（无法提取）。
 * confidence 是**规则置信度**，不是模型概率，reasons 里逐条可查。
 */
/**
 * 把一条消息切成若干「可提事项」句子。一条消息里常有多个交办，
 * 逐句判断能避免只取第一句而漏掉后面的要求。
 */
function candidateSentences(text) {
  return String(text || '')
    .replace(/@\S+\s*/g, '')
    .replace(/\[图片\]|\[文件\]|\[链接\]/g, '')
    .split(/[。!?！？\n]+/)
    .map(function (part) {
      return part.trim()
    })
    .filter(function (part) {
      return part.length >= 6
    })
    .slice(0, 4)
}

function candidateFromSentence(source, sentence, wholeText, baseTime) {
  if (candidateIsClosed(sentence) || candidateIsClosed(wholeText)) return null
  const title = candidateTitleFromText(sentence)
  if (!title) return null

  const reasons = []
  let confidence = 0.35

  const actionHit = CANDIDATE_ACTION_WORDS.filter(function (word) {
    return sentence.indexOf(word) >= 0
  })
  if (actionHit.length > 0) {
    confidence += 0.25
    reasons.push('命中行动词：' + actionHit.slice(0, 3).join(' / '))
  }

  // 相对日期以**原消息时间**为基准（历史消息里的「明天」指消息发出后的明天）
  const due = candidateDueFromText(sentence, baseTime)
  if (due.dueAt) {
    confidence += 0.2
    reasons.push('时间线索：' + due.hits[0])
  } else if (due.hits.length > 0) {
    reasons.push(due.hits[0])
  }

  if (sentence.length <= 80) {
    confidence += 0.1
    reasons.push('正文较短，指向明确')
  } else {
    reasons.push('正文较长（' + sentence.length + ' 字），可能需要拆分')
  }

  if (/我|您|你/.test(sentence)) {
    confidence += 0.1
    reasons.push('正文直接指向收件人')
  }

  confidence = Math.min(0.9, Math.round(confidence * 100) / 100)
  if (reasons.length === 0) reasons.push('仅按正文长度给出基础置信度')

  return {
    sourceRefId: source.id,
    sourceTitle: source.title,
    title: title,
    excerpt: sentence.slice(0, 500),
    dueAt: due.dueAt,
    assignee: null,
    confidence: confidence,
    reasons: reasons,
    status: 'pending',
    /** 明确标记来源：规则提取，不是模型判断 */
    extractor: 'rule',
  }
}

/** 一条来源 → 若干候选（一消息多事项）。取消/已完成语义整体跳过。 */
function candidatesFromSource(source) {
  const text = String((source && source.excerpt) || '').trim()
  if (!text) return []
  if (candidateIsClosed(text)) return []
  const baseTime = new Date(source.fetchedAt || source.createdAt || Date.now())
  const sentences = candidateSentences(text)
  const pool = sentences.length > 0 ? sentences : [text]
  const out = []
  for (const sentence of pool) {
    const candidate = candidateFromSentence(source, sentence, text, baseTime)
    if (candidate) out.push(candidate)
  }
  return out.slice(0, 3)
}

/** 为所有「还没有候选」的云之家来源生成候选。返回新快照。 */
function extractCandidatesInto(state) {
  const sources = ensureArray(state.sources).filter(function (source) {
    return source.provider === 'yunzhijia'
  })
  const seen = new Set(
    ensureArray(state.candidates)
      .map(function (candidate) {
        return candidate.sourceRefId
      })
      .filter(Boolean),
  )
  let added = 0
  let skipped = 0
  let closed = 0
  for (const source of sources) {
    if (seen.has(source.id)) {
      skipped += 1
      continue
    }
    if (candidateIsClosed(source.excerpt)) {
      // 已解决 / 不用处理 / 取消：不生成候选，但记一次跳过，便于核对
      closed += 1
      seen.add(source.id)
      continue
    }
    const drafts = candidatesFromSource(source)
    if (drafts.length === 0) {
      skipped += 1
      continue
    }
    seen.add(source.id)
    for (const draft of drafts) {
      state.candidates = ensureArray(state.candidates).concat([normalizeCandidate(draft, null)]).slice(-CANDIDATE_LIMIT)
      added += 1
    }
  }
  state.lastExtract = {
    at: hostNowIso(),
    scanned: sources.length,
    added: added,
    skipped: skipped,
    closed: closed,
    note:
      sources.length === 0
        ? '还没有云之家 @我 来源：先在首页拉取 @我 消息，或在会话里让 Agent 调 workbench_fetch_mentions。'
        : '规则候选 = 行动词 + 时间线索（以原消息时间为基准）+ 长度/指向性，不是模型结论；' +
          '已解决/不用处理类消息会自动跳过（本次 ' +
          closed +
          ' 条）；采纳前请人工核对。',
  }
  auditEntry(state, 'candidates.extract', '扫描 ' + sources.length + ' 条来源，新增候选 ' + added + ' 条')
  return state
}

// ===== 39-github.js =====
/* ============================================================================
 * dev-workbench host — GitHub 只读快照（设计报告 §3.5 PR / Review / CI）
 *
 * 通过已认证的 `gh` CLI 读取 PR 与 CI 运行状态。命令全部走 28-exec.js 的
 * **多段前缀白名单**（只允许 gh pr list/view/status、gh run list/view、
 * gh repo view、gh search repos），因此 pr merge / pr close / run rerun
 * 这类写操作在 spawn 之前就被拒绝。
 *
 * 没有 github 远端或未认证时如实报告状态，不伪造数据。
 * ========================================================================== */

const GITHUB_TTL_MS = 60 * 1000
let githubCache = { at: 0, value: null }

async function resolveGhPath(ctx) {
  const subprocess = ctx && ctx.get ? ctx.get('subprocess') : null
  if (subprocess && typeof subprocess.resolveExecutable === 'function') {
    try {
      const resolved = await subprocess.resolveExecutable('gh', undefined, AbortSignal.timeout(2500))
      if (typeof resolved === 'string' && resolved.length > 0) return resolved
    } catch (e) {
      /* fall through */
    }
  }
  for (const candidate of ['/opt/homebrew/bin/gh', '/usr/local/bin/gh', join(homedir(), 'bin', 'gh')]) {
    if (existsSync(candidate)) return candidate
  }
  return null
}

function parseGhJson(result) {
  if (result.status !== 'ok') return null
  try {
    return JSON.parse(result.stdout)
  } catch (e) {
    return null
  }
}

async function readPullRequests(ctx, dir) {
  const result = await runReadOnlyCommand(
    ctx,
    ['gh', 'pr', 'list', '--json', 'number,title,state,isDraft,author,updatedAt,url', '--limit', '10'],
    dir,
  )
  if (result.status !== 'ok') {
    return { status: result.status === 'unavailable' ? 'unavailable' : 'error', note: result.reason || result.stderr, items: [] }
  }
  const list = parseGhJson(result)
  if (!Array.isArray(list)) {
    return { status: 'error', note: 'gh 返回不是 JSON 数组（可能未认证或目录不是 GitHub 仓库）', items: [] }
  }
  return {
    status: 'ok',
    note: null,
    items: list.map(function (pr) {
      return {
        number: pr.number,
        title: pr.title,
        state: pr.state,
        draft: pr.isDraft === true,
        author: pr.author && pr.author.login ? pr.author.login : null,
        updatedAt: asIso(pr.updatedAt),
        url: asUrl(pr.url),
      }
    }),
  }
}

async function readCiRuns(ctx, dir) {
  const result = await runReadOnlyCommand(
    ctx,
    ['gh', 'run', 'list', '--json', 'databaseId,status,conclusion,workflowName,headBranch,createdAt,url', '--limit', '10'],
    dir,
  )
  if (result.status !== 'ok') {
    return { status: result.status === 'unavailable' ? 'unavailable' : 'error', note: result.reason || result.stderr, items: [] }
  }
  const list = parseGhJson(result)
  if (!Array.isArray(list)) {
    return { status: 'error', note: 'gh 返回不是 JSON 数组（可能未认证或没有 Actions）', items: [] }
  }
  return {
    status: 'ok',
    note: null,
    items: list.map(function (run) {
      return {
        id: run.databaseId,
        workflow: run.workflowName,
        branch: run.headBranch,
        status: run.status,
        conclusion: run.conclusion,
        createdAt: asIso(run.createdAt),
        url: asUrl(run.url),
      }
    }),
  }
}

/** 选择探测目录：优先项目里的 git 仓库，其次 Host 工作目录。 */
function githubTargetDir(ctx) {
  const state = loadWorkbenchState()
  const project = ensureArray(state.projects).find(function (row) {
    return row.repoPath && existsSync(join(row.repoPath, '.git'))
  })
  if (project) return project.repoPath
  const cwd = cwdForHostCommands(ctx)
  if (cwd && existsSync(join(cwd, '.git'))) return cwd
  return cwd
}

async function buildGithubSnapshot(ctx) {
  if (githubCache.value && Date.now() - githubCache.at < GITHUB_TTL_MS) return githubCache.value
  const dir = githubTargetDir(ctx)
  const ghPath = await resolveGhPath(ctx)
  if (!ghPath) {
    const value = {
      at: hostNowIso(),
      dir: dir,
      status: 'unavailable',
      note: '未找到 gh CLI：安装 GitHub CLI 并 `gh auth login` 后才能读取 PR 与 CI。',
      prs: { status: 'unavailable', items: [], note: null },
      runs: { status: 'unavailable', items: [], note: null },
    }
    githubCache = { at: Date.now(), value: value }
    return value
  }
  const prs = await readPullRequests(ctx, dir)
  const runs = await readCiRuns(ctx, dir)
  const value = {
    at: hostNowIso(),
    dir: dir,
    status: 'ok',
    note: '只读：gh pr list / gh run list。合并、关闭、重跑等写操作不在插件内。',
    prs: prs,
    runs: runs,
  }
  githubCache = { at: Date.now(), value: value }
  return value
}

// ===== 40-remote.js =====
/* ============================================================================
 * dev-workbench host — Remote endpoints
 *
 * Hand-written `src-json` descriptors registered through ctx.typert.register:
 * the supported manual path for a plain-JavaScript plugin, without a generated
 * schema bundle. Each endpoint becomes `workbench/<method>` on the shared
 * `/api` channel, callable from the Client half through
 * `ctx.connection.rpc.call('/api', 'workbench/<method>', { args })`.
 *
 * The plain-object `workbenchApi` carries the same service under
 * `ctx.provide('workbench', …)`, so the gateway can bind the two halves.
 * ========================================================================== */

const WORKBENCH_REMOTE_SIGNATURES = [
  { method: 'snapshot', params: [] },
  { method: 'saveSettings', params: ['patch'] },
  { method: 'createTask', params: ['input'] },
  { method: 'updateTask', params: ['id', 'patch'] },
  { method: 'deleteTask', params: ['id'] },
  { method: 'addSource', params: ['input'] },
  { method: 'createKnowledge', params: ['input'] },
  { method: 'updateKnowledge', params: ['id', 'patch'] },
  { method: 'deleteKnowledge', params: ['id'] },
  { method: 'saveRadarItem', params: ['input'] },
  { method: 'updateRadar', params: ['id', 'patch'] },
  { method: 'deleteRadarItem', params: ['id'] },
  { method: 'recordRun', params: ['input'] },
  { method: 'updateRun', params: ['id', 'patch'] },
  { method: 'saveProject', params: ['input'] },
  { method: 'fetchRadar', params: [] },
  { method: 'fetchMentions', params: [] },
  { method: 'extractCandidates', params: [] },
  { method: 'acceptCandidate', params: ['id', 'patch'] },
  { method: 'rejectCandidate', params: ['id'] },
  { method: 'createTaskFromRadar', params: ['id'] },
  { method: 'deleteProject', params: ['id'] },
  { method: 'search', params: ['request'] },
  { method: 'environment', params: [] },
  { method: 'github', params: [] },
  { method: 'reset', params: ['scope'] },
  { method: 'seedDemo', params: [] },
  { method: 'analysisStatus', params: [] },
  { method: 'analyzeRun', params: ['request'] },
  { method: 'analyzeReset', params: [] },
  { method: 'radarSummarize', params: ['request'] },
  { method: 'analyzeConfirm', params: ['entryId'] },
  { method: 'taskMarkHuman', params: ['id', 'mark'] },
  { method: 'assistantMessage', params: ['request'] },
  { method: 'deleteSource', params: ['id'] },
  { method: 'deleteRun', params: ['id'] },
  { method: 'deleteCandidate', params: ['id'] },
  { method: 'assistantAsk', params: ['request'] },
  { method: 'assistantSend', params: ['request'] },
  { method: 'assistantDelta', params: ['request'] },
  { method: 'assistantHistory', params: [] },
  { method: 'assistantSessions', params: ['request'] },
  { method: 'assistantTranscript', params: ['request'] },
  { method: 'assistantReset', params: [] },
  { method: 'automationRun', params: [] },
  { method: 'automationStatus', params: [] },
  { method: 'backup', params: [] },
  { method: 'backups', params: [] },
  { method: 'restoreBackup', params: ['id'] },
  { method: 'revision', params: [] },
  { method: 'diagnostics', params: [] },
]

function remoteJsonParam(name) {
  return { name: name, wire: name, source: 'json', codec: { mode: 'src-json' } }
}

function remoteJsonInvocation(service, namespace, method, params) {
  return {
    id: PLUGIN_NAME + '#' + namespace + '/' + method,
    service: service,
    namespace: namespace,
    method: method,
    invocation: { kind: 'direct' },
    parameters: params.map(remoteJsonParam),
    result: { mode: 'src-json' },
  }
}

const WORKBENCH_REMOTE = {
  package: PLUGIN_NAME,
  face: 'host',
  schemas: [],
  model: { services: [], events: [], objects: [] },
  invocations: WORKBENCH_REMOTE_SIGNATURES.map(function (entry) {
    return remoteJsonInvocation('workbench', 'workbench', entry.method, entry.params)
  }),
}

// ===== 45-automation.js =====
/* ============================================================================
 * dev-workbench host — 后台自动化（TODO 07 的可落地部分）
 *
 * 设计文档 07 要求「无前台聊天时仍能按配置执行」。宿主的 `schedule` 只做
 * 会话提醒投递、`jobs` 是抽象契约（需要具体 Provider），因此这里用**插件自身**
 * 的定时器执行**确定性采集**（资讯抓取/联网发现、@我 拉取），不涉及模型调用：
 *
 *   - 每 60s 检查一次是否到期（lastAutomation.at + intervalMinutes），
 *     因此开关、间隔、启用的子任务都能在运行时改变，无需重启；
 *   - 单飞锁：同一时刻只有一个 tick 在跑，避免重复写入；
 *   - 启动时若已过期则补跑一次（catch-up），并记录在 lastAutomation；
 *   - 失败只记状态与原因，不做无限重试；
 *   - 进程退出即停止（不假装自己能常驻），文档里如实说明。
 * ========================================================================== */

let automationInFlight = false
let automationTimer = null

function automationDue(state, now) {
  const config = (state.settings && state.settings.automation) || {}
  if (!config.enabled) return false
  const intervalMs = Math.max(5, Number(config.intervalMinutes) || 60) * 60 * 1000
  const last = state.lastAutomation && state.lastAutomation.at ? new Date(state.lastAutomation.at).getTime() : 0
  return !Number.isFinite(last) || last === 0 || now - last >= intervalMs
}

/**
 * 跑一次自动化 tick。返回 { ran, radarAdded, mentionsAdded, status, note }。
 * 内部捕获所有异常：后台任务不能把插件带崩。
 */
async function runAutomationTick(ctx) {
  if (automationInFlight) {
    return { ran: false, status: 'busy', note: '上一次自动化仍在执行，本次跳过' }
  }
  const state = loadWorkbenchState()
  const config = (state.settings && state.settings.automation) || {}
  const extractSettings = (state.settings && state.settings.aiExtract) || {}
  if (!config.enabled) {
    return { ran: false, status: 'disabled', note: '自动化未开启' }
  }

  automationInFlight = true
  const at = hostNowIso()
  let radarAdded = 0
  let mentionsAdded = 0
  let analysisDone = 0
  let analysisPending = 0
  let analysisFailed = false
  const notes = []
  let status = 'ok'

  try {
    if (config.radar !== false) {
      try {
        const afterRadar = await runRadarFetchOrDiscover(ctx)
        const report = afterRadar.lastRadarFetch || {}
        radarAdded = Number(report.added) || 0
        notes.push('资讯新增 ' + radarAdded)
        if (report.note) notes.push(report.note)
      } catch (e) {
        status = 'partial'
        notes.push('资讯失败：' + String((e && e.message) || e).slice(0, 120))
      }
    }

    if (config.analyze !== false && extractSettings.enabled) {
      // TODO 19：采集 → 分析在同一 tick 顺序执行；识别在写入临界区外跑，
      // 提交时走统一的 mutate（短写），失败计入重试（attempts<3 每个 tick 重放一次）
      try {
        const analyzed = await runAnalysisBatch(ctx, {})
        notes.push('AI 识别 ' + (analyzed.status === 'ok' ? processed_ + '' : analyzed.status) + (analyzed.processed !== undefined ? '/' + analyzed.processed + ' 条' : ''))
        if (analyzed.status !== 'ok' && analyzed.status !== 'disabled') {
          status = status === 'ok' ? 'partial' : status
          notes.push(analyzed.note || analyzed.status)
        }
      } catch (e) {
        status = 'partial'
        notes.push('AI 识别失败：' + String((e && e.message) || e).slice(0, 120))
      }
    }

    if (config.mentions !== false) {
      try {
        const probe = await probeYunzhijia(ctx)
        if (probe.state === 'ok') {
          const afterMentions = await mutateWorkbenchState(function (current) {
            return fetchYunzhijiaMentionsInto(ctx, current)
          })
          const report = afterMentions.lastMentionsFetch || {}
          mentionsAdded = Number(report.added) || 0
          notes.push('@我 新增 ' + mentionsAdded + '（' + (report.mode || '关键字') + '）')
          if (report.status !== 'ok') {
            status = status === 'ok' ? 'partial' : status
            notes.push(report.note || report.status)
          }
        } else {
          notes.push('云之家不可用：' + (probe.note || probe.state))
          if (probe.state !== 'unconfigured') status = status === 'ok' ? 'partial' : status
        }
      } catch (e) {
        status = 'partial'
        notes.push('@我 失败：' + String((e && e.message) || e).slice(0, 120))
      }
    }

    if (config.analyze !== false && extractSettings.enabled) {
      // TODO 19：采集 → 分析在同一 tick 顺序执行；识别在写入临界区外跑，
      // 提交时走统一的 mutate（短写），失败计入重试（attempts<3 每个 tick 重放一次）
      try {
        const analyzed = await runAnalysisBatch(ctx, {})
        const analyzedCount = Number(analyzed.processed) || 0
        analysisDone = analyzedCount
        analysisPending = Number(analyzed.failures) || 0
        notes.push('AI 识别处理 ' + analyzedCount + ' 条' + (analyzed.failures ? ('，失败 ' + analyzed.failures) : ''))
        if (analyzed.status !== 'ok' && analyzed.status !== 'disabled') {
          status = status === 'ok' ? 'partial' : status
          notes.push(analyzed.note || analyzed.status)
        }
      } catch (e) {
        status = 'partial'
        analysisFailed = true
        notes.push('AI 识别失败：' + String((e && e.message) || e).slice(0, 120))
      }
    }
  } finally {
    automationInFlight = false
  }

  await mutateWorkbenchState(function (current) {
    current.lastAutomation = {
      at: at,
      radarAdded: radarAdded,
      mentionsAdded: mentionsAdded,
      analysisDone: analysisDone,
      analysisFailedAttempts: analysisPending,
      analysisErrored: analysisFailed,
      status: status,
      note: notes.join('；').slice(0, 300),
    }
    auditEntry(current, 'automation.tick', '自动执行：资讯 +' + radarAdded + '，@我 +' + mentionsAdded + '，AI 识别 ' + analysisDone)
    return current
  })

  return {
    ran: true,
    status: status,
    radarAdded: radarAdded,
    mentionsAdded: mentionsAdded,
    analysisDone: analysisDone,
    note: notes.join('；'),
  }
}

/** 启动后台检查循环（每 60s 判断是否到期）；返回清理函数。 */
function startAutomation(ctx) {
  if (automationTimer) return function () {}
  automationTimer = setInterval(function () {
    const state = loadWorkbenchState()
    if (!automationDue(state, Date.now())) return
    runAutomationTick(ctx).catch(function () {})
  }, 60 * 1000)
  // 不要因为后台定时器阻止宿主正常退出
  if (automationTimer && typeof automationTimer.unref === 'function') automationTimer.unref()
  // 启动补跑：如果已过期，等 8s 让宿主其它服务就绪后跑一次
  const boot = setTimeout(function () {
    const state = loadWorkbenchState()
    if (automationDue(state, Date.now())) runAutomationTick(ctx).catch(function () {})
  }, 8000)
  if (boot && typeof boot.unref === 'function') boot.unref()
  return function () {
    if (automationTimer) clearInterval(automationTimer)
    automationTimer = null
    clearTimeout(boot)
  }
}

// ===== 46-assistant.js =====
/* ============================================================================
 * dev-workbench host — 工作台助手（TODO 04：侧栏内可对话）
 *
 * 复用宿主原生的会话与模型链路，不在插件里自建模型调用：
 *
 *   插件侧栏输入 → workbench/assistantAsk
 *      → sessions.create()（首次，之后复用同一个会话）
 *      → sessionController.prompt({requestId, sessionId, mode:'queue', content})
 *      → 轮询 session.snapshotEvents() 等本轮 turn/end
 *      → 抽取 assistant/message 文本 + 本轮工具调用 → 回给侧栏
 *
 * 因为走的是原生会话，Agent 在回答时可以直接调用 workbench_* 工具，
 * 结果写回同一份工作台数据（页面靠 revision 轮询自动刷新）。
 *
 * 任一依赖缺失（sessions / sessionController）都如实返回 unavailable，
 * 侧栏会显示原因而不是假装能对话。
 * ========================================================================== */

const ASSISTANT_TIMEOUT_MS = 120000
const ASSISTANT_POLL_MS = 400

function sleepMs(ms) {
  // 请求内的等待必须持有活跃定时器：unref 会让事件循环在没有其它句柄时提前退出，
  // 导致 await 永远悬空（测试里表现为 unsettled top-level await）。
  return new Promise(function (resolve) {
    setTimeout(resolve, ms)
  })
}

function hostService(ctx, key) {
  if (!ctx) return null
  if (typeof ctx.get === 'function') {
    const value = ctx.get(key)
    if (value) return value
  }
  return ctx[key] || null
}

/**
 * 过滤宿主注入的系统消息：这些不是用户输入，展示出来只会干扰阅读。
 * 命中任一特征即视为系统文本（<system-reminder>、运行时上下文、turn 元信息）。
 */
/**
 * 剥离助手 prompt 的样板（上下文头 / 尾部工具指令），还原真实用户内容。
 * 会话标题与回显都应基于它，否则侧栏会出现「添加时区（需要落库时请直接调用…」这类杂料。
 */
function stripAssistantBoilerplate(text) {
  const lines = String(text || '').split('\n')
  const kept = []
  let inContext = false
  for (const line of lines) {
    if (line.indexOf('【工作台上下文】') === 0) {
      inContext = true
      continue
    }
    if (inContext) {
      if (line.trim() === '') {
        inContext = false
      }
      continue
    }
    if (line.indexOf('（需要落库时') === 0) continue
    kept.push(line)
  }
  const cleaned = kept.join('\n').replace(/^\n+|\n+$/g, '').trim()
  return cleaned
}

function isSystemInjectedText(text) {
  const source = String(text || '')
  if (source.indexOf('<system-reminder>') >= 0) return true
  if (source.indexOf('</system-reminder>') >= 0) return true
  if (/Time sampled while preparing turn/i.test(source)) return true
  if (/Browser time zone for this request/i.test(source)) return true
  if (/Elapsed since the preceding/i.test(source)) return true
  if (/model-visible message/i.test(source)) return true
  if (/^\[system\]/i.test(source.trim())) return true
  return false
}

/** 从 assistant/message 事件里抽出纯文本（content 是 ContentBlock[]）。 */
function assistantTextOf(message) {
  if (!message || !Array.isArray(message.content)) return ''
  return message.content
    .map(function (block) {
      if (!block || typeof block !== 'object') return ''
      if (block.type === 'text' && typeof block.text === 'string') return block.text
      if (block.type === 'reasoning') return ''
      return ''
    })
    .filter(Boolean)
    .join('\n')
    .trim()
}

/** 本会话里最近 N 轮问答，供侧栏恢复历史。 */
function assistantHistoryFrom(session, limit) {
  if (!session || typeof session.snapshotEvents !== 'function') return []
  const events = session.snapshotEvents()
  const out = []
  for (const event of events) {
    if (event.type === 'user/message') {
      const content = Array.isArray(event.data.content) ? event.data.content : []
      const text = content
        .map(function (block) {
          return block && block.type === 'text' ? block.text : ''
        })
        .filter(Boolean)
        .join('\n')
        .trim()
      const historyText = stripAssistantBoilerplate(text)
      if (historyText && !isSystemInjectedText(historyText)) out.push({ role: 'user', text: historyText, at: event.time })
    } else if (event.type === 'assistant/message') {
      const text = assistantTextOf(event.data.message)
      if (text) out.push({ role: 'assistant', text: text, at: event.time })
    }
  }
  return out.slice(-(limit || 20))
}

/** 会话的展示标题：优先取首条用户消息，其次给短 id。 */
function sessionTitleOf(session) {
  try {
    const events = session.snapshotEvents()
    for (const event of events) {
      if (event.type !== 'user/message') continue
      const content = Array.isArray(event.data.content) ? event.data.content : []
      const text = content
        .map(function (block) {
          return block && block.type === 'text' ? block.text : ''
        })
        .filter(Boolean)
        .join('\n')
      // 先剥样板再压缩空白：一旦把换行压掉，整条 prompt 会变成「以样板开头的一行」被整行吃掉
      const titleText = stripAssistantBoilerplate(text)
        .replace(/\s+/g, ' ')
        .trim()
      if (titleText && !isSystemInjectedText(titleText)) return titleText.slice(0, 40)
    }
  } catch (e) {
    /* 读不到就给短 id */
  }
  return '会话 ' + String(session.id).slice(-6)
}

function sessionLastAt(session) {
  try {
    const events = session.snapshotEvents()
    const last = events[events.length - 1]
    return last && last.time ? last.time : session.header && session.header.createdAt ? session.header.createdAt : null
  } catch (e) {
    return null
  }
}

/** 把会话事件转成侧栏可渲染的记录条目。 */
function transcriptOf(session, limit) {
  if (!session || typeof session.snapshotEvents !== 'function') return []
  const events = session.snapshotEvents()
  const entries = []
  let pendingCalls = []
  for (const event of events) {
    if (event.type === 'user/message') {
      const content = Array.isArray(event.data.content) ? event.data.content : []
      const text = content
        .map(function (block) {
          return block && block.type === 'text' ? block.text : ''
        })
        .filter(Boolean)
        .join('\n')
        .trim()
      const transcriptText = stripAssistantBoilerplate(text)
      if (transcriptText && !isSystemInjectedText(transcriptText)) entries.push({ role: 'user', text: transcriptText, at: event.time })
    } else if (event.type === 'tool/call') {
      const name = event.data && event.data.name ? String(event.data.name) : 'tool'
      const args = event.data && event.data.arguments ? event.data.arguments : null
      let summary = ''
      try {
        summary = args ? JSON.stringify(args).slice(0, 160) : ''
      } catch (e) {
        summary = ''
      }
      pendingCalls.push({ name: name, summary: summary })
    } else if (event.type === 'assistant/message') {
      const text = assistantTextOf(event.data.message)
      if (text || pendingCalls.length > 0) {
        entries.push({ role: 'assistant', text: text, at: event.time, toolCalls: pendingCalls.slice(0, 8) })
      }
      pendingCalls = []
    }
  }
  return entries.slice(-(limit || 40))
}

/** 旧版本存下来的默认计数字 id（session-1 / session-2…）：没有持久化日志，必须丢弃。 */
function isLegacySessionId(id) {
  return /^session-\d+$/.test(String(id || ''))
}

/**
 * 建一个**持久化**的会话。
 *
 * 关键：不能用 `sessions.create()`——它只造内存对象、不写会话日志，随后
 * `sessionController.prompt` 内部 resume 会抛 `SessionPersistenceNotFoundError`
 * （表现为 remote 端 `resume failed for session "session-1"`）。
 * 正确入口是 `sessionController.create`：它走 `createAgent → ctx.agents.create`，
 * 会建立可恢复的会话记录。
 */
async function createPersistedSession(ctx) {
  const controller = hostService(ctx, 'sessionController')
  if (!controller) return null
  const request = { cwd: cwdForHostCommands(ctx) }
  const creator =
    typeof controller.createSession === 'function'
      ? controller.createSession.bind(controller)
      : typeof controller.create === 'function'
        ? controller.create.bind(controller)
        : null
  if (!creator) return null
  const created = await creator(request)
  const sessions = hostService(ctx, 'sessions')
  // 不同版本的返回形状不一致：{agent:{session}} / {session} / Session / {sessionId}
  const candidates = [
    created && created.agent && created.agent.session,
    created && created.session,
    created && created.agentSession,
    created && created.id ? created : null,
  ]
  let session = candidates.find(function (item) {
    return item && typeof item === 'object' && item.id
  })
  if (!session && created && created.sessionId && sessions && typeof sessions.get === 'function') {
    session = sessions.get(String(created.sessionId)) || null
  }
  if (!session) {
    const detail = 'create() 返回里没有可用会话：' + (function () {
      try {
        return JSON.stringify(created).slice(0, 200)
      } catch (e) {
        return String(created).slice(0, 200)
      }
    })()
    const error = new Error(detail)
    error.userFacing = true
    throw error
  }
  return session
}

function rememberAssistantSession(sessionId) {
  mutateWorkbenchState(function (current) {
    current.settings.assistantSessionId = sessionId ? String(sessionId) : null
    return current
  })
}

/** 取（或建）助手会话；陈旧 id 自动丢弃重建。 */
async function ensureAssistantSession(ctx) {
  const sessions = hostService(ctx, 'sessions')
  const controller = hostService(ctx, 'sessionController')
  if (!sessions || typeof sessions.get !== 'function' || !controller) return null

  const state = loadWorkbenchState()
  const savedId = state.settings && state.settings.assistantSessionId
  if (savedId && !isLegacySessionId(savedId)) {
    const existing = sessions.get(savedId)
    if (existing) return existing
  }
  const session = await createPersistedSession(ctx)
  if (!session) return null
  rememberAssistantSession(session.id)
  return session
}

/**
 * 一次助手问答：提交提示 → 等待本轮结束 → 返回回复与工具调用。
 * 所有失败都以 {status, note} 返回，不抛给 Remote 层（侧栏要显示原因）。
 */
/** 最近会话列表（含助手会话标记），供侧栏切换。 */
async function listAssistantSessions(ctx, request) {
  const sessions = hostService(ctx, 'sessions')
  if (!sessions || typeof sessions.list !== 'function') {
    return { status: 'unavailable', note: '没有可用的会话服务', sessions: [], assistantSessionId: null }
  }
  const limit = Math.max(1, Math.min(20, Number(request && request.limit) || 12))
  const state = loadWorkbenchState()
  const currentId = state.settings && state.settings.assistantSessionId ? String(state.settings.assistantSessionId) : null
  const rows = sessions
    .list()
    .map(function (session) {
      return {
        id: String(session.id),
        title: sessionTitleOf(session),
        lastAt: sessionLastAt(session),
        createdAt: session.header && session.header.createdAt ? new Date(session.header.createdAt).toISOString() : null,
        isAssistant: currentId === String(session.id),
      }
    })
    .sort(function (a, b) {
      const left = a.lastAt ? new Date(a.lastAt).getTime() : 0
      const right = b.lastAt ? new Date(b.lastAt).getTime() : 0
      return right - left
    })
    .slice(0, limit)
  return { status: 'ok', sessions: rows, assistantSessionId: currentId }
}

/** 读取指定会话（缺省为助手会话）的记录。 */
async function readAssistantTranscript(ctx, request) {
  const sessions = hostService(ctx, 'sessions')
  if (!sessions || typeof sessions.get !== 'function') {
    return { status: 'unavailable', note: '没有可用的会话服务', messages: [] }
  }
  const wanted = asString(request && request.sessionId, 120)
  let session = null
  if (wanted) {
    session = sessions.get(wanted)
    if (!session) return { status: 'not_found', note: '找不到该会话', messages: [] }
  } else {
    session = await ensureAssistantSession(ctx)
    if (!session) return { status: 'unavailable', note: '没有可用的会话服务', messages: [] }
  }
  return {
    status: 'ok',
    sessionId: String(session.id),
    title: sessionTitleOf(session),
    messages: transcriptOf(session, Math.min(80, Number(request && request.limit) || 40)),
  }
}

/**
 * 增量读取（方案 A1）：只返回 fromSeq 之后的新条目，并告知本轮是否仍在进行。
 * 侧栏在 turnActive 期间轮询这个端点，实现「工具调用 → 结果 → 回复分段」的渐进渲染，
 * 不依赖未验证的 stream 描述符。
 */
function transcriptDelta(session, fromSeq) {
  const start = Number(fromSeq)
  const events = session.snapshotEvents(Number.isFinite(start) && start >= 0 ? start : 0)
  const entries = []
  let turnActive = false
  for (const event of events) {
    if (event.type === 'turn/start') {
      turnActive = true
      continue
    }
    if (event.type === 'turn/end') {
      turnActive = false
      continue
    }
    if (event.type === 'user/message') {
      const content = Array.isArray(event.data.content) ? event.data.content : []
      const text = content
        .map(function (block) {
          return block && block.type === 'text' ? block.text : ''
        })
        .filter(Boolean)
        .join('\n')
        .trim()
      const entryText = stripAssistantBoilerplate(text)
      if (entryText && !isSystemInjectedText(entryText)) entries.push({ role: 'user', text: entryText, at: event.time, seq: event.seq })
    } else if (event.type === 'assistant/message') {
      const text = assistantTextOf(event.data.message)
      if (text) entries.push({ role: 'assistant', text: text, at: event.time, seq: event.seq })
    } else if (event.type === 'tool/call') {
      const name = event.data && event.data.name ? String(event.data.name) : 'tool'
      let summary = ''
      try {
        summary = event.data && event.data.arguments ? JSON.stringify(event.data.arguments).slice(0, 200) : ''
      } catch (e) {
        summary = ''
      }
      entries.push({ role: 'tool', text: name, summary: summary, at: event.time, seq: event.seq })
    } else if (event.type === 'tool/result') {
      const name = event.data && event.data.name ? String(event.data.name) : 'tool'
      const ok = !(event.data && (event.data.isError === true || event.data.error))
      entries.push({ role: 'toolResult', text: name, ok: ok, at: event.time, seq: event.seq })
    } else if (event.type === 'turn/error') {
      const note = event.data && event.data.message ? String(event.data.message) : '本轮执行出错'
      entries.push({ role: 'error', text: note, at: event.time, seq: event.seq })
    }
  }
  return { entries: entries, nextSeq: session.seq, turnActive: turnActive }
}

/**
 * 把内部错误翻译成用户能看懂的一句话；技术细节只放进 detail（不主动展示）。
 * 代码级异常（例如「返回值里没有 session」）绝不能原样抛给界面。
 */
function userFacingAssistantError(failure) {
  const detail = String((failure && failure.message) || failure || '').slice(0, 300)
  let note = 'AI 助手暂时不可用，请稍后重试'
  if (/resume failed|SessionPersistenceNotFound/i.test(detail)) {
    note = '助手会话已失效，请点标题栏「新会话」重开一个'
  } else if (/writer-held|SessionAlreadyOwned/i.test(detail)) {
    note = '这个会话正在被另一个窗口使用，换一个会话或稍后再试'
  } else if (/timeout|aborted/i.test(detail)) {
    note = '这次等待超时了，可以稍后在主面板查看结果'
  } else if (/create|session/i.test(detail)) {
    note = 'AI 助手连接失败，请稍后重试'
  }
  return { status: 'error', note: note, detail: detail }
}

/**
 * 提交提示，并在会话日志丢失时自愈。
 *
 * `prompt` 内部会对目标会话做 resume；如果该会话没有持久化日志（旧版本用
 * `sessions.create()` 建的空会话、或会话被清理过），就会抛
 * `resume failed for session "…": SessionPersistenceNotFoundError`。
 * 这里捕获这一类错误，重建一个持久化会话并重试一次，同时更新记录的会话 id。
 */
async function submitPrompt(ctx, controller, session, text, steer) {
  const build = function (sessionId) {
    return {
      requestId: 'wb-assistant-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8),
      sessionId: sessionId,
      mode: steer === true ? 'steer' : 'queue',
      content: [{ type: 'text', text: text }],
      clientTimeZone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    }
  }
  const attempt = async function (target) {
    const fromSeq = target.seq
    await controller.prompt(build(target.id), AbortSignal.timeout(30000))
    return { session: target, fromSeq: fromSeq, recovered: false }
  }
  try {
    return await attempt(session)
  } catch (error) {
    const message = String((error && error.message) || error)
    if (!/resume failed|SessionPersistenceNotFound/i.test(message)) throw error
    const fresh = await createPersistedSession(ctx)
    if (!fresh) throw error
    rememberAssistantSession(fresh.id)
    const retried = await attempt(fresh)
    return Object.assign({}, retried, { recovered: true })
  }
}

/** 只提交提示并立即返回（不等待本轮结束），供侧栏渐进渲染。 */
async function sendAssistantPrompt(ctx, request) {
  const input = request && typeof request === 'object' ? request : {}
  const text = asString(input.text, 4000)
  if (!text) return { status: 'invalid', note: '请输入内容' }

  const controller = hostService(ctx, 'sessionController')
  if (!controller || typeof controller.prompt !== 'function') {
    return {
      status: 'unavailable',
      note: '当前宿主没有 sessionController 服务，无法把提示提交给模型；可改用「复制上下文并打开会话」。',
    }
  }

  const wantedSession = asString(input.sessionId, 120)
  let session = null
  if (wantedSession) {
    const sessions = hostService(ctx, 'sessions')
    session = sessions && typeof sessions.get === 'function' ? sessions.get(wantedSession) : null
    if (!session) return { status: 'not_found', note: '找不到该会话：' + wantedSession }
    mutateWorkbenchState(function (current) {
      current.settings.assistantSessionId = String(session.id)
      return current
    })
  } else {
    session = await ensureAssistantSession(ctx)
    if (!session) return { status: 'unavailable', note: '当前宿主没有可用的 sessions / sessionController 服务。' }
  }

  const refs = Array.isArray(input.refs) ? input.refs.slice(0, 6) : []
  const lines = []
  if (refs.length > 0) {
    lines.push('【工作台上下文】')
    refs.forEach(function (ref, index) {
      lines.push(
        (index + 1) + '. [' + asString(ref.kind, 20) + '] ' + asString(ref.title, 200) +
          (ref.url ? ' — ' + asString(ref.url, 500) : '') +
          (ref.body ? '\n   ' + asString(ref.body, 600).replace(/\n/g, ' ') : ''),
      )
    })
    lines.push('')
  }
  lines.push(text)
  lines.push('')
  lines.push('（需要落库时请直接调用 workbench_* 工具：建/改待办、登记执行记录、写回资讯摘要。）')

  try {
    const submitted = await submitPrompt(ctx, controller, session, lines.join('\n'), input.steer === true)
    return {
      status: 'ok',
      sessionId: String(submitted.session.id),
      fromSeq: submitted.fromSeq,
      recovered: submitted.recovered === true,
    }
  } catch (e) {
    return userFacingAssistantError(e)
  }
}

/** 增量读取端点：供侧栏渐进渲染。 */
async function readAssistantDelta(ctx, request) {
  const input = request && typeof request === 'object' ? request : {}
  const sessions = hostService(ctx, 'sessions')
  if (!sessions || typeof sessions.get !== 'function') {
    return { status: 'unavailable', note: '没有可用的会话服务', entries: [], nextSeq: 0, turnActive: false }
  }
  const wanted = asString(input.sessionId, 120)
  let session = null
  if (wanted) {
    session = sessions.get(wanted)
    if (!session) return { status: 'not_found', note: '找不到该会话', entries: [], nextSeq: 0, turnActive: false }
  } else {
    session = await ensureAssistantSession(ctx)
    if (!session) return { status: 'unavailable', note: '没有可用的会话服务', entries: [], nextSeq: 0, turnActive: false }
  }
  const delta = transcriptDelta(session, Number(input.fromSeq) || 0)
  return Object.assign({ status: 'ok', sessionId: String(session.id) }, delta)
}

async function runAssistantAsk(ctx, request) {
  const input = request && typeof request === 'object' ? request : {}
  const text = asString(input.text, 4000)
  if (!text) return { status: 'invalid', note: '请输入内容', reply: '' }

  const controller = hostService(ctx, 'sessionController')
  if (!controller || typeof controller.prompt !== 'function') {
    return {
      status: 'unavailable',
      note: '当前宿主没有 sessionController 服务，无法把提示提交给模型；可改用「复制上下文并打开会话」。',
      reply: '',
    }
  }
  const wantedSession = asString(input.sessionId, 120)
  let session = null
  if (wantedSession) {
    const sessions = hostService(ctx, 'sessions')
    session = sessions && typeof sessions.get === 'function' ? sessions.get(wantedSession) : null
    if (!session) {
      return { status: 'not_found', note: '找不到该会话：' + wantedSession, reply: '' }
    }
    mutateWorkbenchState(function (current) {
      current.settings.assistantSessionId = String(session.id)
      return current
    })
  } else {
    try {
      session = await ensureAssistantSession(ctx)
    } catch (e) {
      return Object.assign(userFacingAssistantError(e), { reply: '' })
    }
    if (!session) {
      return {
        status: 'unavailable',
        note: 'AI 助手连接失败，请稍后重试',
        detail: '宿主没有可用的 sessions / sessionController 服务',
        reply: '',
      }
    }
  }
  let fromSeq = session.seq

  // 上下文引用拼进提示（保持可见、可回溯），Agent 可直接调用 workbench_* 工具回写
  const refs = Array.isArray(input.refs) ? input.refs.slice(0, 6) : []
  const lines = []
  if (refs.length > 0) {
    lines.push('【工作台上下文】')
    refs.forEach(function (ref, index) {
      lines.push(
        (index + 1) + '. [' + asString(ref.kind, 20) + '] ' + asString(ref.title, 200) +
          (ref.url ? ' — ' + asString(ref.url, 500) : '') +
          (ref.body ? '\n   ' + asString(ref.body, 600).replace(/\n/g, ' ') : ''),
      )
    })
    lines.push('')
  }
  lines.push(text)
  lines.push('')
  lines.push('（需要落库时请直接调用 workbench_* 工具：建/改待办、登记执行记录、写回资讯摘要。）')
  const promptText = lines.join('\n')

  try {
    const submitted = await submitPrompt(ctx, controller, session, promptText, false)
    session = submitted.session
    fromSeq = submitted.fromSeq
  } catch (e) {
    return Object.assign(userFacingAssistantError(e), { reply: '', sessionId: String(session && session.id ? session.id : '') })
  }

  // 等待本轮结束（turn/end）或超时；期间持续读取已产生的 assistant 消息
  const deadline = Date.now() + ASSISTANT_TIMEOUT_MS
  let reply = ''
  let toolCalls = []
  let finished = false
  while (Date.now() < deadline) {
    await sleepMs(ASSISTANT_POLL_MS)
    let events
    try {
      events = session.snapshotEvents(fromSeq, session.seq)
    } catch (e) {
      break
    }
    const assistantEvents = events.filter(function (event) {
      return event.type === 'assistant/message'
    })
    if (assistantEvents.length > 0) {
      reply = assistantEvents
        .map(function (event) {
          return assistantTextOf(event.data.message)
        })
        .filter(Boolean)
        .join('\n\n')
    }
    toolCalls = events
      .filter(function (event) {
        return event.type === 'tool/call'
      })
      .map(function (event) {
        return String(event.data && event.data.name ? event.data.name : '')
      })
      .filter(Boolean)
    if (events.some(function (event) {
      return event.type === 'turn/end'
    })) {
      finished = true
      break
    }
  }

  return {
    status: finished ? 'ok' : reply ? 'partial' : 'timeout',
    note: finished
      ? null
      : reply
        ? '本轮仍未结束，先返回已生成的内容。'
        : '等待超时：模型可能仍在执行，可稍后用「打开完整会话」查看。',
    reply: reply,
    toolCalls: toolCalls.slice(0, 12),
    sessionId: String(session.id),
  }
}

/** 侧栏历史：读助手会话最近若干条问答。 */
async function readAssistantHistory(ctx) {
  const session = await ensureAssistantSession(ctx)
  if (!session) return { status: 'unavailable', note: '没有可用的会话服务', messages: [] }
  return {
    status: 'ok',
    sessionId: String(session.id),
    messages: assistantHistoryFrom(session, 20),
  }
}

/** 清空助手上下文（换一个新会话，旧会话仍保留在原生会话列表里）。 */
async function resetAssistantSession(ctx) {
  const session = await createPersistedSession(ctx)
  if (!session) {
    return { status: 'unavailable', note: '没有可用的 sessionController.create', sessionId: null }
  }
  rememberAssistantSession(session.id)
  return { status: 'ok', sessionId: String(session.id) }
}


/**
 * 按「持久化消息 id」取一条助手回复的正文，供原生聊天的内嵌动作使用
 * （conversation.chat.assistant-actions 只下发 messageId）。
 * 事件形状不完全一致，按 id → data.messageId → seq 三种顺序兜底匹配。
 */
async function readAssistantMessage(ctx, request) {
  const input = request && typeof request === 'object' ? request : {}
  const sessions = hostService(ctx, 'sessions')
  if (!sessions || typeof sessions.get !== 'function') {
    return { status: 'unavailable', note: '没有可用的会话服务', text: '' }
  }
  const wantedSession = asString(input.sessionId, 120)
  let session = wantedSession ? sessions.get(wantedSession) : await ensureAssistantSession(ctx)
  if (!session) return { status: 'not_found', note: '找不到该会话', text: '' }

  const wanted = asString(input.messageId, 120)
  let events = []
  try {
    events = session.snapshotEvents()
  } catch (e) {
    return { status: 'error', note: '读取会话事件失败：' + String((e && e.message) || e).slice(0, 160), text: '' }
  }

  const assistantEvents = events.filter(function (event) {
    return event.type === 'assistant/message'
  })
  let hit = null
  if (wanted) {
    hit =
      assistantEvents.find(function (event) {
        const message = event.data && event.data.message ? event.data.message : null
        return String((message && message.id) || (event.data && event.data.messageId) || '') === wanted
      }) || null
    if (!hit && /^\d+$/.test(wanted)) {
      hit =
        events.find(function (event) {
          return Number(event.seq) === Number(wanted)
        }) || null
    }
  }
  if (!hit) {
    // 兜底：取最后一条助手消息（动作按钮总是挂在已定稿消息上）
    hit = assistantEvents.length > 0 ? assistantEvents[assistantEvents.length - 1] : null
  }
  // 命中但内容是系统注入文本时，继续往前找真实消息
  while (hit && isSystemInjectedText(assistantTextOf(hit.data && hit.data.message ? hit.data.message : null))) {
    const index = assistantEvents.indexOf(hit)
    hit = index > 0 ? assistantEvents[index - 1] : null
  }
  if (!hit) return { status: 'not_found', note: '该会话还没有助手回复', text: '', sessionId: String(session.id) }

  const message = hit.data && hit.data.message ? hit.data.message : null
  return {
    status: 'ok',
    sessionId: String(session.id),
    messageId: String((message && message.id) || wanted || hit.seq),
    text: assistantTextOf(message),
    at: hit.time || null,
    seq: hit.seq,
  }
}

// ===== 47-analysis.js =====
/* ============================================================================
 * dev-workbench host — AI 结构化识别（TODO 15）
 *
 * 复用 DSH 原生会话链路（sessions + sessionController.prompt）做结构化提取：
 *   队列条目 → 严格 JSON 提示词 → 原生模型 → 回复解析/校验 → 合并语义
 *
 * 合并规则（TODO 15/16）：
 *   - 噪声（问候/感谢/纯知会）→ 标记 noise，不建任务；
 *   - 一条消息可拆多个事项（items 上限 6）；
 *   - 若已存在引用同一来源的待办 → 更新那条（追加 sourceRefs / 字段），不重建；
 *   - settings.aiExtract.autoRegister 开启时自动建待办，否则条目停在
 *     awaiting_human 等人工确认（analyzeConfirm 建任务）；
 *   - humanGuard.editedFields 里的字段绝不被 AI 覆盖（TODO 17 人工保护）。
 * ========================================================================== */

const ANALYSIS_TURN_TIMEOUT_MS = 90000
const ANALYSIS_POLL_MS = 350

function analysisPrompt(source, existingTitles) {
  const lines = []
  lines.push('请把下面这条云之家消息解析成结构化事项，只输出一个 JSON 对象，不要输出其它文字。')
  lines.push('')
  lines.push('消息内容：')
  lines.push(source.excerpt || source.title || '')
  lines.push('')
  lines.push('已有待办标题（判断是否同一事项的参考，需要续接时用其中一个 title）：')
  lines.push(existingTitles.slice(0, 12).map(function (title) { return '- ' + title }).join('\n') || '（暂无）')
  lines.push('')
  lines.push('输出 JSON 格式：')
  lines.push('{')
  lines.push('  "noise": true|false,')
  lines.push('  "summary": "一句话概括",')
  lines.push('  "items": [')
  lines.push('    { "needsReply": true|false, "needsAction": true|false, "eventType": "meeting|feature|logging|other|null", "title": "事项标题", "dueAt": "ISO 日期|null", "deliverable": "交付物|null", "replyStage": "待答复|已确认收到|已实质答复|null" }')
  lines.push('  ]')
  lines.push('}')
  lines.push('规则：问候/感谢/表情/纯知会 → noise=true 且 items=[]；询问不是承诺，不编造负责人或日期；一条消息可拆多个事项（最多 3 个）。')
  return lines.join('\n')
}

function extractJsonFromReply(reply) {
  const text = String(reply || '')
  const fenced = /```(?:json)?\s*([\s\S]*?)```/.exec(text)
  const candidates = []
  if (fenced) candidates.push(fenced[1])
  const braced = /\{[\s\S]*\}/.exec(text)
  if (braced) candidates.push(braced[0])
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate)
      if (parsed && typeof parsed === 'object') return parsed
    } catch (e) {
      /* 尝试下一个候选 */
    }
  }
  return null
}

/** 校验来源存在 → 已存在引用它的待办（同一事项续接）。 */
function findTaskBySourceRef(state, sourceId) {
  return ensureArray(state.tasks).find(function (task) {
    if (task.sourceRefId === sourceId) return true
    return ensureArray(task.sourceRefs).some(function (ref) {
      return ref.sourceId === sourceId
    })
  }) || null
}

/** 把分析结果合并进状态：建待办（受配置与人工保护）或续接既有待办。 */
function mergeAnalysisIntoState(state, entry, analysis, options) {
  const mergeOptions = options || {}
  const source = ensureArray(state.sources).find(function (row) {
    return row.id === entry.sourceId
  })
  const sourceRef = { sourceId: entry.sourceId, msgId: entry.msgId, snippet: (source && source.excerpt ? String(source.excerpt).slice(0, 160) : null) }
  const existingTitles = ensureArray(state.tasks).map(function (task) { return task.title })
  const created = []
  const updated = []
  const items = ensureArray(analysis.items).slice(0, 3)
  // 拆多事项时，「同一来源消息」不是合并依据（多条事项共享一条证据是正常的）

  const multiItem = items.length > 1

  if (analysis.noise === true || items.length === 0) {
    return { created: created, updated: updated, noise: true }
  }

  for (const item of items) {
    const related = item.title
      ? ensureArray(state.tasks).find(function (task) {
          return existingTitles.indexOf(task.title) >= 0 && (task.title === item.title || task.title.indexOf(item.title) >= 0 || item.title.indexOf(task.title) >= 0)
        })
      : null
    const target = related || (multiItem ? null : findTaskBySourceRef(state, entry.sourceId))

    if (target && !analysis.noise) {
      // 续接：追加来源引用、合并义务/回复阶段；不覆盖人工已编辑字段
      const guard = normalizeHumanGuard(target.humanGuard)
      const patch = {
        sourceRefs: ensureArray(target.sourceRefs).concat([sourceRef]),
        needsReply: target.needsReply === true || item.needsReply === true,
        needsAction: target.needsAction === true || item.needsAction === true,
      }
      if (item.replyStage && guard.editedFields.indexOf('replyStage') < 0) patch.replyStage = item.replyStage
      if (item.dueAt && guard.editedFields.indexOf('dueAt') < 0 && !target.dueAt) patch.dueAt = item.dueAt
      const applied = applyUpdateTask(state, target.id, patch)
      updated.push(applied.entity)
      continue
    }

    // 新建：批量分析时受 autoRegister 控制；人工确认路径强制允许
    if (!mergeOptions.forceCreate && (!state.settings.aiExtract || state.settings.aiExtract.autoRegister !== true)) continue
    const payload = {
      title: item.title || (source ? source.title : '未命名事项'),
      description: (source ? String(source.excerpt || '').slice(0, 1000) : '') + (item.deliverable ? '\n交付物：' + item.deliverable : ''),
      priority: item.dueAt ? 'high' : 'normal',
      dueAt: item.dueAt || null,
      tags: ['AI 识别'],
      aiExtracted: true,
      sourceRefId: entry.sourceId,
      sourceRefs: [sourceRef],
      needsReply: item.needsReply === true,
      needsAction: item.needsAction !== false,
      replyStage: item.replyStage || (item.needsReply === true ? '待答复' : null),
      eventType: item.eventType || null,
      deliverable: item.deliverable || null,
      confidence: 0.72,
      projectId: state.settings.defaultProjectId || undefined,
    }
    const applied = applyCreateTask(state, payload)
    created.push(applied.entity)
  }

  return { created: created, updated: updated, noise: false }
}

/**
 * 手动/后台触发的分析批处理：从队列取 pending（或重放 failed），逐条调原生会话。
 * 单条失败计入 attempts/lastError，不阻断批次其余条目。
 */
async function runAnalysisBatch(ctx, request) {
  const controller = hostService(ctx, 'sessionController')
  if (!controller || typeof controller.prompt !== 'function') {
    return { status: 'unavailable', note: '宿主没有 sessionController 服务，无法运行 AI 识别。' }
  }
  const settings = loadWorkbenchState().settings
  if (!settings.aiExtract || settings.aiExtract.enabled !== true) {
    return { status: 'disabled', note: 'AI 识别未开启（连接与设置 → 自动化 → AI 识别）。' }
  }
  const resolved = await ensureAssistantSession(ctx)
  if (!resolved) return { status: 'unavailable', note: '当前宿主没有可用的 sessions / sessionController 服务。' }

  const input = request && typeof request === 'object' ? request : {}
  const limit = Math.max(1, Math.min(20, Number(input.limit) || (settings.aiExtract.batchSize || 5)))
  const at = hostNowIso()

  const state0 = loadWorkbenchState()
  const queue = ensureArray(state0.analysisQueue)
  const sources = ensureArray(state0.sources)
  const entries = queue
    .filter(function (row) {
      return row.status === 'pending' || (row.status === 'failed' && row.attempts < 3)
    })
    .filter(function (row) {
      return sources.some(function (source) {
        return source.id === row.sourceId
      })
    })
    .slice(0, limit)

  const processed = []
  const failures = []

  for (const entry of entries) {
    const source = sources.find(function (row) {
      return row.id === entry.sourceId
    })
    if (!source) continue

    const titles = ensureArray(loadWorkbenchState().tasks).map(function (task) { return task.title })
    const submitted = await submitPrompt(ctx, controller, resolved, analysisPrompt(source, titles), false)
    const session = submitted.session
    const fromSeq = submitted.fromSeq

    // 等待本轮结束并抽取回复（复用助手的轮询语义）
    const deadline = Date.now() + ANALYSIS_TURN_TIMEOUT_MS
    let reply = ''
    while (Date.now() < deadline) {
      await sleepMs(ANALYSIS_POLL_MS)
      const delta = transcriptDelta(session, fromSeq)
      const assistantTexts = delta.entries
        .filter(function (item) { return item.role === 'assistant' })
        .map(function (item) { return item.text })
      if (assistantTexts.length > 0) reply = assistantTexts.join('\n\n')
      if (!delta.turnActive) break
    }

    const parsed = extractJsonFromReply(reply)
    if (!parsed) {
      failures.push(entry.sourceId)
      await mutateWorkbenchState(function (current) {
        current.analysisQueue = ensureArray(current.analysisQueue).map(function (row) {
          if (row.id !== entry.id) return row
          return Object.assign({}, row, {
            status: 'failed',
            attempts: (Number(row.attempts) || 0) + 1,
            lastError: '模型回复无法解析为 JSON',
          })
        })
        return current
      })
      continue
    }

    const applied = await mutateWorkbenchState(function (current) {
      const analysis = {
        noise: parsed.noise === true,
        items: ensureArray(parsed.items).slice(0, 6),
        summary: asString(parsed.summary, 400) || null,
      }
      const queueRow = ensureArray(current.analysisQueue).find(function (row) {
        return row.id === entry.id
      })
      const merged = mergeAnalysisIntoState(current, queueRow || entry, analysis)
      current.analysisQueue = ensureArray(current.analysisQueue).map(function (row) {
        if (row.id !== entry.id) return row
        const status = merged.created.length > 0 || merged.updated.length > 0
          ? 'done'
          : analysis.noise
            ? 'done'
            : 'awaiting_human'
        return Object.assign({}, row, {
          status: status,
          analyzedAt: hostNowIso(),
          analysis: analysis,
          taskIds: merged.created.map(function (task) { return task.id }).concat(merged.updated.map(function (task) { return task.id })).slice(0, 6),
        })
      })
      auditEntry(current, 'analysis.run', entry.sourceId + ' → ' + (merged.noise ? '噪声' : merged.created.length + ' 新建 / ' + merged.updated.length + ' 续接'))
      return current
    })

    processed.push({
      sourceId: entry.sourceId,
      created: applied.analysisQueue.filter(function (row) { return row.id === entry.id })[0],
    })
  }

  return {
    status: failures.length > 0 ? 'partial' : 'ok',
    processed: processed.length,
    failures: failures.length,
    note: failures.length > 0 ? failures.join('、') : null,
  }
}

/** 人工确认：把 awaiting_human 的条目按已保存的分析建待办（不调模型）。 */
async function confirmAnalysis(ctx, entryId) {
  const entry = ensureArray(loadWorkbenchState().analysisQueue).find(function (row) {
    return row.id === entryId
  })
  if (!entry || !entry.analysis) throw new Error('找不到该分析条目或它还没有分析结果：' + String(entryId))
  if (entry.status === 'done') return loadWorkbenchState()
  return mutateWorkbenchState(function (current) {
    const merged = mergeAnalysisIntoState(current, entry, entry.analysis, { forceCreate: true })
    current.analysisQueue = ensureArray(current.analysisQueue).map(function (row) {
      if (row.id !== entry.id) return row
      return Object.assign({}, row, {
        status: 'done',
        analyzedAt: hostNowIso(),
        taskIds: merged.created.map(function (task) { return task.id }).concat(merged.updated.map(function (task) { return task.id })).slice(0, 6),
      })
    })
    auditEntry(current, 'analysis.confirmed', entry.sourceId)
    return current
  })
}

// ===== 48-radar-summarize.js =====
/* ============================================================================
 * dev-workbench host — 资讯四段摘要批处理（TODO 20）
 *
 * 流程与 15 的分析批处理一致（复用 19 的执行纪律）：
 *   挑四段为空的资讯 → web.fetch 读原文（每条独立容错）→ 严格 JSON 提示 →
 *   原生会话 → 解析/校验 → writeRadarSummary（不改动来源/发布时间）→
 *   lastRadarSummarize 如实记录 done/failed。
 *
 * 纪律：
 *   - 单条失败不影响其余批次（partial 如实）；
 *   - 原文超过 4000 字截断，提示词明确「不在原文中的不得编造」；
 *   - 每条独立 muted failure 保留原因。
 * ========================================================================== */

const SUMMARY_TURN_TIMEOUT_MS = 120000

function radarNeedsSummary(item) {
  const summary = item.summary || {}
  return !(summary.change || summary.usage || summary.risk || summary.practice)
}

/** 读取原文文本：剥掉标签，压空白；失败/长度不足都如实报告。 */
function stripHtmlToText(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim()
}

function summaryPrompt(item, articleText) {
  const lines = []
  lines.push('请阅读下面这篇资讯原文，输出一个 JSON 对象，不要输出其它文字。')
  lines.push('')
  lines.push('标题：' + (item.title || ''))
  lines.push('发布时间：' + (item.publishedAt ? item.publishedAt : '原文未注明'))
  lines.push('')
  lines.push('原文（节选）：')
  lines.push(String(articleText || '').slice(0, 4000))
  lines.push('')
  lines.push('输出 JSON：')
  lines.push('{')
  lines.push('  "change": "技术变化：这次变化的关键事实",')
  lines.push('  "usage": "应用场景：适合用在哪里",')
  lines.push('  "risk": "采用风险：可能踩的坑",')
  lines.push('  "practice": "推荐实践：怎么落地"')
  lines.push('}')
  lines.push('规则：结论必须来自原文；原文没讲就不写，宁缺毋滥。')
  return lines.join('\n')
}

/**
 * 批量生成四段摘要。单条失败聚合到 partial；最多处理 limit 条。
 */
async function runRadarSummarizeBatch(ctx, request) {
  const controller = hostService(ctx, 'sessionController')
  if (!controller || typeof controller.prompt !== 'function') {
    return { status: 'unavailable', note: '宿主没有 sessionController 服务，无法生成摘要。' }
  }
  const settings = loadWorkbenchState().settings
  if (!settings.aiExtract || settings.aiExtract.enabled !== true) {
    return { status: 'disabled', note: 'AI 识别未开启（设置 → 自动化 → AI 识别）。' }
  }
  const web = ctx && ctx.get ? ctx.get('web') : null
  if (!web || typeof web.fetch !== 'function') {
    return { status: 'unavailable', note: '当前 profile 没有 web 抓取服务，无法读取原文。' }
  }

  const input = request && typeof request === 'object' ? request : {}
  const limit = Math.max(1, Math.min(10, Number(input.limit) || 3))

  const state0 = loadWorkbenchState()
  const onlyIds = ensureArray(input.onlyIds).map(function (id) { return String(id) })
  const all = ensureArray(state0.radar).filter(function (item) {
    return item.url && radarNeedsSummary(item)
  })
  const candidates = (onlyIds.length > 0
    ? all.filter(function (item) { return onlyIds.indexOf(item.id) >= 0 })
    : all
  ).slice(0, limit)

  if (candidates.length === 0) {
    return { status: 'ok', done: 0, failed: 0, note: '没有待摘要的资讯（都有四段摘要或没有 url）。' }
  }

  const resolved = await ensureAssistantSession(ctx)
  if (!resolved) return { status: 'unavailable', note: '当前宿主没有可用的 sessions / sessionController 服务。' }

  let done = 0
  let failed = 0
  const perItem = []

  for (const item of candidates) {
    try {
      const fetched = await web.fetch({ url: item.url, method: 'GET' }, AbortSignal.timeout(15000))
      const bodyText =
        fetched && fetched.body && typeof fetched.body.content === 'string'
          ? stripHtmlToText(fetched.body.content)
          : ''
      if (bodyText.length < 40) {
        throw new Error('原文内容不足（可能被反爬或需要登录）')
      }

      const submitted = await submitPrompt(ctx, controller, resolved, summaryPrompt(item, bodyText), false)
      const deadline = Date.now() + SUMMARY_TURN_TIMEOUT_MS
      let reply = ''
      while (Date.now() < deadline) {
        await sleepMs(ANALYSIS_POLL_MS)
        const delta = transcriptDelta(submitted.session, submitted.fromSeq)
        const assistantTexts = delta.entries
          .filter(function (row) { return row.role === 'assistant' })
          .map(function (row) { return row.text })
        if (assistantTexts.length > 0) reply = assistantTexts.join('\n\n')
        if (!delta.turnActive) break
      }

      const parsed = extractJsonFromReply(reply)
      if (!parsed) throw new Error('模型回复无法解析为 JSON')

      const wrote = await mutateWorkbenchState(function (current) {
        const target = ensureArray(current.radar).find(function (row) {
          return row.id === item.id
        })
        if (!target) throw new Error('资讯已被删除：' + item.id)
        const index = current.radar.indexOf(target)
        const next = normalizeRadarItem(
          { summary: parsed },
          target,
        )
        next.id = target.id
        next.createdAt = target.createdAt
        next.updatedAt = hostNowIso()
        current.radar = current.radar.slice()
        current.radar[index] = next
        auditEntry(current, 'radar.summarized', target.title)
        return current
      })
      done += 1
      perItem.push({ id: item.id, ok: true })
      void wrote
    } catch (error) {
      failed += 1
      perItem.push({ id: item.id, ok: false, note: String((error && error.message) || error).slice(0, 160) })
    }
  }

  await mutateWorkbenchState(function (current) {
    current.lastRadarSummarize = {
      at: hostNowIso(),
      done: done,
      failed: failed,
      note: failed > 0 ? perItem.filter(function (row) { return !row.ok }).map(function (row) { return row.note }).slice(0, 3).join('；') : null,
    }
    auditEntry(current, 'radar.summarize', '摘要生成：成功 ' + done + ' / 失败 ' + failed)
    return current
  })

  return {
    status: failed > 0 ? 'partial' : 'ok',
    done: done,
    failed: failed,
    note: failed > 0 ? '失败条目见 lastRadarSummarize' : null,
  }
}

// ===== 50-tools.js =====
/* ============================================================================
 * dev-workbench host — Agent tools
 *
 * The workbench is only an "AI workbench" if the model can read and write the
 * same objects the UI shows. These five tools are the write-back path from
 * design report §4.4 (createTask / attachResult) expressed as ordinary DSH
 * tools: they mutate the same host state the pages read, so a result an agent
 * records appears in the task center on the next refresh.
 *
 * Every tool returns plain JSON plus a `text` field, so the model gets an
 * unambiguous result either way.
 * ========================================================================== */

function toolText(text) {
  return [{ type: 'text', text: text }]
}

function toolOutputSchema() {
  return {
    type: 'object',
    properties: {
      text: { type: 'string', description: '人类可读的结果摘要。' },
    },
    required: ['text'],
    additionalProperties: true,
  }
}

function renderToolText(args, value) {
  const text = value && typeof value.text === 'string' ? value.text : JSON.stringify(value)
  return toolText(text)
}

function taskLine(task) {
  const due = task.dueAt ? ' · 截止 ' + task.dueAt.slice(0, 16).replace('T', ' ') : ''
  const project = task.projectId ? ' · 项目 ' + task.projectId : ''
  return '- [' + task.status + '] ' + task.title + ' (id=' + task.id + ')' + due + project
}

function workbenchToolDefinitions() {
  return [
    {
      name: 'workbench_list_tasks',
      description:
        '列出开发者工作台里的待办。用它回答“我今天还有什么没做”“哪些任务逾期”“某项目的待办有哪些”。' +
        '默认只返回未完成（不是 completed/cancelled）的任务，按优先级与截止时间排序。' +
        '返回里的每个任务都带 id，需要修改时把该 id 传给 workbench_update_task。',
      parameters: {
        type: 'object',
        properties: {
          status: {
            type: 'string',
            enum: TASK_STATUSES,
            description: '只看某个状态；省略表示所有未完成状态。',
          },
          includeCompleted: {
            type: 'boolean',
            description: '为 true 时连已完成与已取消一起返回（默认 false）。',
          },
          limit: {
            type: 'number',
            description: '最多返回多少条，默认 20，上限 100。',
          },
        },
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute(args) {
        const input = args && typeof args === 'object' ? args : {}
        const state = loadWorkbenchState()
        const limit = Math.max(1, Math.min(100, Number(input.limit) || 20))
        const tasks = ensureArray(state.tasks)
          .filter(function (task) {
            if (input.status) return task.status === input.status
            if (input.includeCompleted === true) return true
            return task.status !== 'completed' && task.status !== 'cancelled'
          })
          .sort(function (a, b) {
            const rank = { urgent: 4, high: 3, normal: 2, low: 1 }
            const priority = (rank[b.priority] || 0) - (rank[a.priority] || 0)
            if (priority !== 0) return priority
            const left = a.dueAt ? new Date(a.dueAt).getTime() : Number.MAX_SAFE_INTEGER
            const right = b.dueAt ? new Date(b.dueAt).getTime() : Number.MAX_SAFE_INTEGER
            return left - right
          })
          .slice(0, limit)
        if (tasks.length === 0) {
          return { text: '工作台当前没有匹配的待办。', count: 0 }
        }
        const header = '共 ' + tasks.length + ' 条待办：'
        return {
          text: header + '\n' + tasks.map(taskLine).join('\n'),
          count: tasks.length,
        }
      },
    },

    {
      name: 'workbench_create_task',
      description:
        '在开发者工作台新建一条待办。当用户说“记一下”“帮我建个待办”“把这个加进任务中心”时使用。' +
        '标题必填，其余字段可省略。不要把用户没有提到的截止时间或负责人编造出来：' +
        '不确定就留空，让用户在任务中心补。',
      parameters: {
        type: 'object',
        properties: {
          title: { type: 'string', description: '一句话说清要做的事。' },
          description: { type: 'string', description: '背景、期望结果、链接；保留原始上下文。' },
          priority: { type: 'string', enum: TASK_PRIORITIES, description: '默认 normal。' },
          dueAt: { type: 'string', description: 'ISO 8601 时间；用户没有明确期限时不要填。' },
          tags: { type: 'array', items: { type: 'string' }, description: '最多 12 个短标签。' },
          projectId: { type: 'string', description: '已存在的项目 id；不确定就省略。' },
          idempotencyKey: {
            type: 'string',
            description:
              '可选幂等键：同一个键重复调用只会创建一次（用于网络重试或模型重复调用）。' +
              '建议用「意图 + 目标」的稳定字符串，例如 "create-task:压测结论"（不要用随机值）。',
          },
        },
        required: ['title'],
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute(args) {
        const input = args && typeof args === 'object' ? args : {}
        if (!asString(input.title, 200)) throw new Error('title 不能为空')
        const key = asString(input.idempotencyKey, 160)
        if (key) {
          const previous = findOperation(loadWorkbenchState(), key)
          if (previous && previous.entityIds.length > 0) {
            return {
              text: '幂等命中：' + key + ' 之前已创建（taskId=' + previous.entityIds[0] + '），本次未重复创建。',
              taskId: previous.entityIds[0],
              idempotent: true,
            }
          }
        }
        const result = await mutateWorkbenchState(function (current) {
          const applied = applyCreateTask(current, Object.assign({}, input))
          if (key) recordOperation(current, { key: key, tool: 'workbench_create_task', entityIds: [applied.entity.id] })
          auditEntry(current, 'task.created', applied.entity.title + '（来自 Agent 工具）')
          return current
        })
        const created = result.tasks[result.tasks.length - 1]
        return {
          text: '已创建待办：' + created.title + ' (id=' + created.id + '，状态 ' + created.status + ')',
          taskId: created.id,
        }
      },
    },

    {
      name: 'workbench_update_task',
      description:
        '修改开发者工作台里的一条待办：状态、优先级、截止时间、标题或描述。需要 id —— 先用 ' +
        'workbench_list_tasks 拿到。用户说“这个做完了”就把 status 设为 completed。',
      parameters: {
        type: 'object',
        properties: {
          id: { type: 'string', description: '待办 id。' },
          status: { type: 'string', enum: TASK_STATUSES },
          priority: { type: 'string', enum: TASK_PRIORITIES },
          dueAt: { type: 'string', description: 'ISO 8601；传空字符串表示清除截止时间。' },
          title: { type: 'string' },
          description: { type: 'string' },
          assignee: { type: 'string' },
        },
        required: ['id'],
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute(args) {
        const input = args && typeof args === 'object' ? args : {}
        if (!asString(input.id, 100)) throw new Error('id 不能为空')
        const patch = Object.assign({}, input)
        delete patch.id
        if (patch.dueAt === '') patch.dueAt = null
        const state = await mutateWorkbenchState(function (current) {
          const applied = applyUpdateTask(current, input.id, patch)
          auditEntry(current, 'task.updated', applied.entity.title + ' → ' + applied.entity.status + '（来自 Agent 工具）')
          return current
        })
        const updated = state.tasks.find(function (task) {
          return task.id === input.id
        })
        return { text: '已更新：' + taskLine(updated), taskId: input.id }
      },
    },

    {
      name: 'workbench_record_run',
      description:
        '把一次 Agent 执行的结果登记到开发者工作台的 Agent 中心，并在任务详情里留下执行记录。' +
        '分析、诊断、代码审查这类工作完成后调用，让用户能在 UI 里回看结论与证据。' +
        'evidence 里每条都要是可以回跳的来源（文件、URL 或报告章节）。',
      parameters: {
        type: 'object',
        properties: {
          taskId: { type: 'string', description: '关联的待办 id；纯探索可以不填。' },
          status: {
            type: 'string',
            enum: RUN_STATUSES,
            description: '本次执行的最终状态，通常是 completed 或 failed。',
          },
          summary: { type: 'string', description: '一到三句话说明做了什么、结论是什么。' },
          idempotencyKey: { type: 'string', description: '可选幂等键：同一个键重复调用只登记一次。' },
          profile: { type: 'string', description: '逻辑 Agent 角色，如 Coding Agent / Research Agent。' },
          sessionId: { type: 'string', description: '关联会话 id，便于回跳。' },
          evidence: {
            type: 'array',
            items: {
              type: 'object',
              properties: { label: { type: 'string' }, url: { type: 'string' } },
              required: ['label'],
            },
          },
          steps: {
            type: 'array',
            items: {
              type: 'object',
              properties: { text: { type: 'string' } },
              required: ['text'],
            },
          },
        },
        required: ['status', 'summary'],
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute(args, exec) {
        const input = args && typeof args === 'object' ? args : {}
        const payload = Object.assign({}, input)
        const runKey = asString(input.idempotencyKey, 160)
        if (runKey) {
          const previous = findOperation(loadWorkbenchState(), runKey)
          if (previous && previous.entityIds.length > 0) {
            return {
              text: '幂等命中：' + runKey + ' 之前已登记（runId=' + previous.entityIds[0] + '），本次未重复登记。',
              runId: previous.entityIds[0],
              idempotent: true,
            }
          }
        }
        if (!payload.sessionId && exec && exec.agent && exec.agent.session && exec.agent.session.id) {
          payload.sessionId = String(exec.agent.session.id)
        }
        const state = await mutateWorkbenchState(function (current) {
          const applied = applyRecordRun(current, payload)
          if (runKey) recordOperation(current, { key: runKey, tool: 'workbench_record_run', entityIds: [applied.entity.id] })
          auditEntry(current, 'agent.run.created', applied.entity.summary || applied.entity.id)
          return current
        })
        const run = state.runs[state.runs.length - 1]
        return { text: '已登记执行记录 ' + run.id + '（' + run.status + '）：' + run.summary, runId: run.id }
      },
    },

    {
      name: 'workbench_fetch_radar',
      description:
        '按用户在「连接与设置 → 资讯源」里配置的 RSS/Atom 地址抓取技术雷达增量。' +
        '用户说“抓一下最新的技术资讯”“刷新雷达”，或用户设置了每日提醒让你更新雷达时调用。' +
        '返回每个源的抓取结果（新增/跳过/失败原因）；没有配置资讯源时如实说明，不要编造结果。' +
        '这个工具只采集原始条目和原文摘录，不生成 AI 摘要——如需摘要，读完原文后自己归纳，' +
        '把结论用 workbench_record_run 写回，并附来源链接。',
      parameters: {
        type: 'object',
        properties: {},
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute() {
        const state = await runRadarFetch(workbenchCtx)
        const report = state.lastRadarFetch || {}
        if (!report.perFeed || report.perFeed.length === 0) {
          return { text: '技术雷达：' + (report.note || '没有可用的抓取结果。') }
        }
        const lines = report.perFeed.map(function (row) {
          return (
            '- ' +
            row.label +
            '：' +
            (row.status === 'ok'
              ? '新增 ' + row.added + ' 条，跳过 ' + row.skipped + ' 条'
              : row.status + (row.note ? '（' + row.note + '）' : ''))
          )
        })
        return {
          text:
            '技术雷达抓取完成：新增 ' + (report.added || 0) + ' 条，跳过 ' + (report.skipped || 0) + ' 条。\n' +
            lines.join('\n') +
            '\n可在工作台的「今日简报 → 技术雷达」查看。',
        }
      },
    },

    {
      name: 'workbench_fetch_mentions',
      description:
        '通过云之家 CLI（yzj-cli）拉取 @我 的消息，作为待办来源证据存入工作台。' +
        '用户说“看看有没有人@我”“拉一下@我的消息”时调用。' +
        '只做确定性采集：把消息原文、所在群、时间存为来源（SourceRef），不自动创建待办——' +
        '是否生成待办、标题和截止时间怎么定，由你在会话里分析后决定（可用 workbench_create_task 并带 sourceRef）' +
        '或交回用户。云之家未配置或 token 失效时如实报告，不要编造。',
      parameters: {
        type: 'object',
        properties: {},
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute() {
        const state = await mutateWorkbenchState(function (current) {
          return fetchYunzhijiaMentionsInto(workbenchCtx, current)
        })
        const report = state.lastMentionsFetch || {}
        if (report.status !== 'ok') {
          return { text: '@我 拉取未完成：' + (report.note || report.status) }
        }
        const lines = []
        for (const source of ensureArray(state.sources).slice(-Math.max(report.added, 0))) {
          if (source.provider !== 'yunzhijia') continue
          lines.push('- [' + source.title + '] ' + source.excerpt.slice(0, 80))
        }
        return {
          text:
            '云之家 @我 检索完成：发现 ' + (report.found || 0) + ' 条，新增来源 ' + (report.added || 0) + ' 条。' +
            (report.note ? '\n' + report.note : '') +
            (lines.length > 0 ? '\n新增：\n' + lines.join('\n') : '\n没有新增（此前已采集过）。') +
            '\n要分析这些消息时，用 workbench_task_brief 或直接读来源证据。',
        }
      },
    },

    {
      name: 'workbench_update_radar',
      description:
        '把四段摘要写回一条技术雷达资讯：技术变化 / 应用场景 / 采用风险 / 推荐实践。' +
        '先用 workbench_fetch_radar 抓取（或联网发现）拿到条目 id，读原文后再归纳并调用本工具。' +
        '每条结论都应来自原文，不要凭标题猜测；无法确认的段落留空。',
      parameters: {
        type: 'object',
        properties: {
          id: { type: 'string', description: '资讯 id（来自抓取报告或快照）。' },
          change: { type: 'string', description: '技术变化：这次变化的关键事实。' },
          usage: { type: 'string', description: '应用场景：适合用在哪里。' },
          risk: { type: 'string', description: '采用风险：可能踩的坑。' },
          practice: { type: 'string', description: '推荐实践：怎么落地。' },
        },
        required: ['id'],
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute(args) {
        const input = args && typeof args === 'object' ? args : {}
        if (!asString(input.id, 100)) throw new Error('id 不能为空')
        if (!input.change && !input.usage && !input.risk && !input.practice) {
          throw new Error('至少填写一段摘要（change / usage / risk / practice）')
        }
        const state = await mutateWorkbenchState(function (current) {
          const item = ensureArray(current.radar).find(function (row) {
            return row.id === input.id
          })
          if (!item) throw new Error('找不到该资讯：' + input.id)
          const index = current.radar.indexOf(item)
          const next = normalizeRadarItem(
            {
              summary: {
                change: asString(input.change, 800),
                usage: asString(input.usage, 800),
                risk: asString(input.risk, 800),
                practice: asString(input.practice, 800),
              },
            },
            item,
          )
          next.id = item.id
          next.createdAt = item.createdAt
          current.radar = current.radar.slice()
          current.radar[index] = next
          auditEntry(current, 'radar.summary', next.title + '（来自 Agent 工具）')
          return current
        })
        const updated = ensureArray(state.radar).find(function (row) {
          return row.id === input.id
        })
        return { text: '已写回摘要：' + updated.title + '（' + updated.url + '）', radarId: updated.id }
      },
    },

    {
      name: 'workbench_search',
      description:
        '统一检索工作台的多路来源（待办 / 知识 / 雷达 / 来源证据 / 本地项目 / 企业云之家 / PR·CI / 互联网），' +
        '返回按来源分组的结果与每路状态。回答用户问题时先用它取证据，再在回答里给出处；' +
        '某一路 status 不是 ok 时要如实说明该路不可用，不要把「没查到」说成「不存在」。',
      parameters: {
        type: 'object',
        properties: {
          query: { type: 'string', description: '检索词。' },
          includeWeb: { type: 'boolean', description: '是否查互联网（默认 true）。' },
        },
        required: ['query'],
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute(args) {
        const input = args && typeof args === 'object' ? args : {}
        const result = await runUnifiedSearch(workbenchCtx, {
          query: input.query,
          includeWeb: input.includeWeb !== false,
        })
        const lines = []
        for (const group of result.groups) {
          lines.push('## ' + group.label + '（' + group.status + '，' + group.items.length + ' 条）')
          if (group.note) lines.push('说明：' + group.note)
          for (const item of group.items.slice(0, 6)) {
            const ref = item.url ? ' — ' + item.url : ''
            lines.push('- ' + item.title + (item.snippet ? '｜' + item.snippet.slice(0, 80) : '') + ref)
          }
        }
        return { text: '检索「' + input.query + '」共 ' + result.total + ' 条：\n' + lines.join('\n') }
      },
    },

    {
      name: 'workbench_task_brief',
      description:
        '把一条待办连同它的来源证据渲染成可直接用作提示词的任务简报。' +
        '需要上下文（背景、来源、期望产出）时先调用它，再开始分析。',
      parameters: {
        type: 'object',
        properties: {
          id: { type: 'string', description: '待办 id。' },
        },
        required: ['id'],
        additionalProperties: false,
      },
      output: { schema: toolOutputSchema(), render: renderToolText },
      async execute(args) {
        const input = args && typeof args === 'object' ? args : {}
        const state = loadWorkbenchState()
        const task = ensureArray(state.tasks).find(function (item) {
          return item.id === input.id
        })
        if (!task) throw new Error('找不到该待办：' + String(input.id))
        const source = task.sourceRefId
          ? ensureArray(state.sources).find(function (item) {
              return item.id === task.sourceRefId
            })
          : null
        return { text: taskBrief(task, source) }
      },
    },
  ]
}

// ===== 90-apply.js =====
/* ============================================================================
 * dev-workbench host — plugin entry
 *
 * Two registrations, both owned by this plugin fiber:
 *   1. `workbench` service (ctx.provide) + its typert Remote descriptors, so
 *      the Client half can read and mutate state over the shared /api channel;
 *   2. the `workbench_*` Agent tools, so the model can read and write the same
 *      objects the pages show.
 *
 * A profile without `typert` or `tools` still loads the plugin: the service is
 * mounted, the missing capability is simply absent. That keeps state readable
 * (and recoverable) even when a profile composes fewer subsystems.
 * ========================================================================== */

export function apply(ctx, config) {
  workbenchCtx = ctx
  const settings = config && typeof config === 'object' ? config : {}

  ctx.provide('workbench', workbenchApi)

  ctx.inject(['typert'], function (host) {
    return host.typert.register(WORKBENCH_REMOTE)
  })

  ctx.inject(['tools'], function (host) {
    ctx.effect(function () {
      const definitions = workbenchToolDefinitions()
      const disposers = definitions.map(function (definition) {
        return host.tools.register(definition)
      })
      registerWorkbenchToolNames(
        definitions.map(function (definition) {
          return definition.name
        }),
      )
      return function () {
        registerWorkbenchToolNames([])
        disposers.forEach(function (dispose) {
          try {
            dispose()
          } catch (e) {
            /* already withdrawn by the owning context */
          }
        })
      }
    })
  })

  // 后台自动化（TODO 07）：定时检查是否到期，到期跑确定性采集
  ctx.effect(function () {
    return startAutomation(ctx)
  })

  ctx.effect(function () {
    const state = loadWorkbenchState()
    if (ctx.logger && typeof ctx.logger.info === 'function') {
      ctx.logger.info(
        '[dev-workbench] ready: ' +
          workbenchStatePath() +
          ' · ' +
          ensureArray(state.tasks).length +
          ' task(s)' +
          (settings.verbose === true ? ' · verbose' : ''),
      )
    }
    return function () {
      workbenchCtx = null
    }
  })
}
